// Tournaments and contests of every size: village wrestling and county fairs, city opens, sect and family
// contests, selection trials, the military examination, drinking, poetry, archery and lightness races,
// wagers, fixed bouts, judging, rivalries born in the ring, and famous young fighters from the roster.
// Complements the Dragon-Phoenix Assembly bracket in witness.js (tl_assembly / tourney_*): qualifiers,
// odds, aftermath, and the Assemblies after the war. Ring fights are non-lethal; many bouts are rolls.
import { E, O, C, R, P, M, Q, LATER } from './kit.js';
import { template } from '../../engine/registry.js';

const WIN = 'tn.wins+1';
const T = 'tournament';
// The seasons before each Dragon-Phoenix Assembly (held in autumn of years 12, 18, 24, 30 and 44).
const before = (y) => ({ or: [{ year: [y - 1, y - 1] }, { year: [y, y], season: [0, 1] }] });
const PRE_ASSEMBLY = { or: [12, 18, 24, 30, 44].flatMap((y) => before(y).or) };
const POST_ASSEMBLY = { or: [12, 18, 24, 30, 44].map((y) => ({ year: [y, y], season: [3] })) };
const JUDGE = { or: [{ flag: 'tn.judge' }, { realm: '>=4', stat: { fame: '>=40' } }] };

const handWritten = [
  // ── Village and childhood ───────────────────────────────────────
  E('tn_harvest_wrestle', T, { if: { age: [9, 17], loc: 'willow', season: [2] }, once: false, cd: 2, art: 'feast', title: 'The harvest wrestling', text: 'After the harvest, Willow Creek clears the threshing floor for wrestling. The prize is a whole smoked ham, and the reigning champion is the blacksmith’s son, who has a neck like a tree stump.', choices: [
    R('Wrestle', 'body', 22, O('You got under the blacksmith’s son and tipped him over like a sack of millet. The village cheered. One more bout stood between you and the ham.', { body: 1, fame: 1, next: 'tn_harvest_final' }), O('He sat on you. It was like being sat on by a well-fed ox. The village cheered anyway, because the village always cheers.', { body: 1, health: -3 })),
    P('Grease yourself with lamp oil first', 0.5, O('You slipped out of every hold like a river eel. Willow Creek called it cheating and ate the ham with you anyway.', { fame: 1, health: 4, charm: -1 }), O('You slid clean off the threshing floor and into the pig pen. The pigs were the only ones who did not laugh.', { charm: -1 })),
    C('Cheer from the haystack', O('You cheered so loudly for the underdog that the underdog’s mother gave you a slice of ham for loyalty.', { charm: 1, health: 2 })),
  ] }),
  E('tn_harvest_final', T, { on: 'scheduled', title: 'For the ham', text: 'The final bout: you against Han Ji-ho, the miller’s son, who has carried flour sacks since he could walk and has never once let you win at anything.', choices: [
    R('Go for his legs', 'body', 26, O('You took his legs, he took your collar, and you both went down, but he went down first. The ham was yours. Ji-ho shook your hand with flour still on his.', { fame: 2, health: 5, flag: [WIN, 'tn.village_champ'], rel: { '@jiho': { res: 10, aff: 3 } } }), O('Ji-ho lifted you like a flour sack and set you down, gently, outside the circle. Then he split the ham with you, because that is who he is.', { health: 3, rel: { '@jiho': { aff: 8 } } })),
    C('Let him win, and make it look real', O('You fought hard and lost carefully. His father clapped him on the back until he coughed. Ji-ho knew, of course. He gave you the bigger half of the ham.', { rel: { '@jiho': { aff: 12, res: -3 } }, sanity: 3 })),
    R('Use a trick you saw the sect boys use', 'insight', 22, O('You stepped aside the way the Mount Hua boys do in the market square. Ji-ho went past you and out of the circle on his own momentum. He laughed about it for a week.', { fame: 2, flag: WIN, rel: { '@jiho': { res: 8 } } }), O('You tried the sect boys’ trick. It needs years of training that you did not have. Ji-ho caught you mid-step and carried you out like a lamb.', { rel: { '@jiho': { aff: 4 } } })),
  ] }),
  E('tn_stick_swords', T, { if: { age: [6, 11] }, art: 'garden', title: 'General of the shrine yard', text: 'The neighbourhood children are holding a stick-sword tournament behind the shrine. The rules: no hitting faces, no crying, and no telling mothers.', choices: [
    R('Fight for the title of General', 'body', 14, O('You won four bouts and a crown of woven grass. For one whole summer you were General, and you ruled with mercy.', { body: 1, fame: 1, flag: 'tn.child_general' }), O('You lost to a girl two years younger who hit like a mule. You did not cry. You came close.', { body: 1 })),
    C('Appoint yourself judge', O('Nobody had asked for a judge, but once you had one, nobody could imagine doing without. You settled eleven disputes and started two.', { charm: 1, insight: 1 })),
    M('Use a real sword form you remember', 'theory.sword_basic', O('You beat every child in the neighbourhood with forms none of them had ever seen. An old wanderer resting by the shrine stopped smoking his pipe to watch, then walked away shaking his head.', { fame: 2, insight: 1 })),
  ] }),
  E('tn_sneak_in', T, { if: { age: [8, 14], locType: 'city' }, title: 'The cheap seats', text: 'There is a contest in the square today, and the stands cost three coppers you do not have. The old locust tree behind the platform, however, is free.', choices: [
    R('Climb the tree', 'body', 18, O('You watched the whole contest from a branch with the best view in the city, until the branch broke during the final. You landed on a judge, who was surprisingly kind about it.', { insight: 2, body: 1 }), O('A steward pulled you down by the ankle and boxed your ears. You heard the final from the street, which is not the same.', { health: -2 })),
    C('Carry water for the fighters', O('You carried water to the fighters’ bench all day. A tired woman with a split lip told you, "Never fight when you are thirsty," and gave you a copper. You never forgot either.', { wealth: 1, insight: 1, charm: 1 })),
    C('Sell your seat on the tree to other children', O('You charged a copper a branch. By noon the tree held nine children and you held nine coppers. A future in commerce beckoned.', { wealth: 2, charm: 1 })),
  ] }),

  // ── The stands ──────────────────────────────────────────────────
  E('tn_seed_eater', T, { if: { age: [14, 60], locType: 'city' }, once: false, cd: 6, title: 'The man with the sunflower seeds', text: 'In the stands, the old man beside you eats sunflower seeds and calls every bout three exchanges before it ends. He has not been wrong yet.', choices: [
    R('Ask him how he knows', 'charm', 20, O('He looked at you sidelong and spat a husk. "Watch the feet, not the hands. Hands lie." For the rest of the day you watched feet, and the bouts slowed down in front of your eyes.', { insight: 3, codex: { id: 'secret.tn_watch_feet', cat: 'theory', title: 'Watch the feet', text: 'An old man in the stands told you: the hands lie, the feet cannot. A fighter’s weight shifts a breath before the blow. Watch the back heel.' } }), O('He offered you sunflower seeds and nothing else. They were very good seeds.', { insight: 1 })),
    R('Try to call the bouts yourself', 'insight', 35, O('You called three bouts in a row before he did. He grunted, and pushed the bag of seeds a little toward you.', { insight: 2 }), O('You were wrong every time. He was right every time. He seemed to enjoy this very much.', { sanity: -1 })),
    M('Call the bouts before he does: watch the feet', 'secret.tn_watch_feet', O('"Back heel," you said, a breath before the winning blow. The old man stopped chewing. "Who taught you that?" "You did," you said, and he did not know what to do with that at all.', { insight: 3, fame: 1 })),
  ] }),
  E('tn_stands_brawl', T, { if: { age: [14, 50], locType: 'city' }, once: false, cd: 5, bind: { x: { ageRel: [-3, 3], realm: [1, 2], role: 'acquaintance', aff: 30 } }, title: 'Sore losers', text: 'A youngmaster in silk lost to a nobody from the provinces, and his retainers have decided the nobody needs to apologise to the paving stones with his face.', choices: [
    R('Step between them', 'power', 40, O('You put the first retainer on the ground and smiled at the second until he remembered an errand. The provincial fighter, {x}, bowed to you very low.', { fame: 3, rep: { families: -2 }, rel: { x: { aff: 15, res: 15, role: 'friend' } } }), O('You stepped between them and took the beating meant for {x}. It was a sincere gesture and a painful one.', { health: -6, rel: { x: { aff: 20 } } })),
    R('Shout for the stewards', 'charm', 22, O('You shouted until the stewards came at a run. The retainers discovered they had always respected the provinces.', { rep: { orthodox: 2 }, rel: { x: { aff: 8 } } }), O('Nobody heard you over the crowd. {x} got the worst of it and limped off before you could help.', { sanity: -2 })),
    C('Buy the provincial a drink afterwards', O('You found {x} in a cheap wine-house, nursing a black eye and a bowl of noodles, and bought the second bowl. You talked until closing.', { wealth: -1, rel: { x: { aff: 15, role: 'friend' } } })),
  ] }),
  E('tn_storyteller', T, { on: 'tavern', if: { age: [12, 90] }, once: false, cd: 4, title: 'The storyteller’s version', text: 'A storyteller is recounting a famous tournament. In his version, the winner split the platform with a single stroke and the loser became a monk out of shame.', choices: [
    C('Correct his details', O('You pointed out that the platform was stone and nobody split it. The tavern turned on you. Nobody wants the truth with their wine.', { insight: 1, charm: -1 })),
    C('Buy him a cup for a better ending', O('For a cup of wine he added a dragon, a princess and a second platform. It was a much better story.', { wealth: -1, sanity: 2 })),
    Q('Point out that the winner was you', { flag: 'tn.wins>=3' }, O('He looked at you, then at your hands, and changed the ending on the spot. In the new version, the winner was modest, generous and very good-looking.', { fame: 2, charm: 1 })),
  ] }),
  E('tn_dock_wrestle', T, { if: { age: [14, 50], loc: ['wuchang', 'dongting', 'hangzhou'] }, once: false, cd: 3, art: 'river', title: 'Big Sister Ok', text: 'Dockworkers arm-wrestle on an upturned barrel for coppers. The champion is a woman called Big Sister Ok, who unloads salt barges for a living and has forearms like mooring posts.', choices: [
    R('Put down a copper and your elbow', 'body', 35, O('Her arm went down a finger at a time, and the docks went silent, and then very loud. She paid you, and then she paid for the noodles.', { wealth: 3, fame: 1 }), O('Her arm did not move. Then yours did, all at once, into the barrel.', { wealth: -1, body: 1 })),
    P('Cheat with a trickle of qi', 0.5, O('Your arm did not move, and neither did hers, until the barrel split. She called it a draw. "Next time," she said, "no qi." She knew.', { wealth: 2, charm: 1 }), O('She felt the qi and put your hand through the barrel lid on principle.', { health: -3, infamy: 1 }), { req: { realm: '>=2' } }),
    P('Bet on Big Sister Ok', 0.7, O('A merchant’s guard tried his luck against her. He is still trying to straighten his wrist. You won two coppers.', { wealth: 2 }), O('A quiet boatman beat her, to everyone’s horror, including his own. You lost two coppers.', { wealth: -2 })),
  ] }),
  E('tn_drunk_nobody', T, { if: { age: [14, 50], alive: 'sword_saint', or: ['luoyang', 'dongting', 'mounthua', 'kunlun', 'zhongnan'].map((l) => ({ loc: l, npc: { '@sword_saint': { loc: l } } })) }, title: 'Entered as Nobody', text: 'A drunk old man has entered the open contest under the name "Nobody". He has won four bouts without spilling his wine, and seems faintly surprised each time.', choices: [
    R('Challenge Nobody', 'power', 200, O('Impossibly, you made him put the wine down. He looked at you for a long moment. "Huh," he said, and that was all, and it was enough.', { fame: 8, rel: { '@sword_saint': { res: 25 } } }), O('He beat you with the wine jar. Not by swinging it: by drinking from it while you missed. Afterwards he patted your head and said, "Not bad. Not good, either."', { insight: 3, rel: { '@sword_saint': { res: 5, aff: 5 } } })),
    Q('Bring him a jar of wine', { item: 'rice_wine' }, O('He took the jar without looking at you, drank half of it, and said, "Your elbow drops when you thrust. Stop that." He was right.', { take: { rice_wine: 1 }, insight: 2, rel: { '@sword_saint': { aff: 12 } } })),
    C('Watch him', O('You watched him win two more bouts and then wander off before the final, to find more wine. Nobody who saw him fight will ever call him nobody again.', { insight: 2 })),
  ] }),

  // ── Drink, poetry and appetite ──────────────────────────────────
  E('tn_paeng_duel', T, { if: { age: [16, 40], alive: 'paeng_gu', loc: ['paeng', 'luoyang', 'taihang', 'capital'] }, once: false, cd: 6, title: 'A Paeng duel', text: 'Paeng Gu slams a jar of sorghum spirit on the table. "A Paeng duel," he announces. "Whoever falls off the bench first pays. Whoever falls off second is my brother."', choices: [
    R('Drink', 'health', 60, O('Paeng Gu fell off the bench on the ninth cup, laughing. You fell off on the tenth, also laughing. You woke up with his arm across your face and a brother.', { sanity: 3, rel: { '@paeng_gu': { aff: 15, res: 10, role: 'friend' } } }), O('You fell off first and woke in a stable. Paeng Gu had paid anyway and left a note: "Again next year."', { wealth: -5, health: -3, rel: { '@paeng_gu': { aff: 10 } } })),
    P('Sweat the wine out through your fingertips', 0.5, O('Your fingertips dripped wine under the table all night. Paeng Gu never noticed, and declared you the greatest drinker in Hebei.', { fame: 1, rel: { '@paeng_gu': { res: 12, aff: 8 } } }), O('He noticed the puddle under your hand. "Cheating!" he roared, delighted. "Teach me!"', { rel: { '@paeng_gu': { aff: 10 } } }), { req: { realm: '>=2' } }),
    Q('Swear brotherhood over the last cup', { npc: { '@paeng_gu': { aff: '>=60' } } }, O('You cut your palms, mixed the blood into the last of the sorghum, and drank. "Brother," Paeng Gu said, and wept, and then threw up, and then wept again.', { achieve: 'sworn', rel: { '@paeng_gu': { aff: 20, role: 'sworn' } }, sanity: 5 })),
    C('Decline', O('He looked so wounded that you nearly changed your mind. "Next time," he said. He will remember.', { rel: { '@paeng_gu': { aff: -3 } } })),
  ] }),
  E('tn_west_lake_verse', T, { if: { age: [15, 45], loc: 'hangzhou', season: [0, 1] }, art: 'lake', title: 'Poems and swords on West Lake', text: 'The young gentry of Hangzhou hold a gathering on painted boats. Each guest composes a couplet, then defends it with a sword on a plank laid between two boats.', choices: [
    R('Compose your couplet', 'insight', 35, O('Your couplet compared the lake to a sword at rest. The gentry murmured. Someone wrote it on a fan. Then they pointed you at the plank.', { fame: 1, flag: 'tn.couplet', next: 'tn_west_lake_plank' }), O('Your couplet rhymed "moon" with "moon". The guests were kind about it, which was worse. Then they pointed you at the plank.', { charm: -1, next: 'tn_west_lake_plank' })),
    P('Borrow a famous poem and hope', 0.35, O('Nobody recognised it. You were praised for an hour for a poem by a man who died three hundred years ago, and then sent to the plank.', { fame: 1, next: 'tn_west_lake_plank' }), O('An old scholar recognised it in the first line and finished it for you, aloud. You were asked to leave the boat.', { charm: -2, fame: -1 })),
    C('Stay on the shore and eat lotus cakes', O('You ate lotus cakes on the shore and watched gentlemen fall into the lake one by one. It was the best afternoon of the season.', { sanity: 4 })),
  ] }),
  E('tn_west_lake_plank', T, { on: 'scheduled', art: 'lake', title: 'The plank', text: 'The plank is a hand wide and wet. Your opponent is a scholar’s son with an elegant sword, damp sandals and an expression of great literary seriousness.', choices: [
    R('Fence on the plank', 'body', 35, O('Three exchanges, a wobble, and a splash, and it was his. The boats applauded. A girl threw you a lotus flower, and missed.', { fame: 3, flag: WIN }), O('You fell in. The lake was cold. Your couplet, at least, stayed dry.', { health: -2 })),
    Q('Recite your couplet as you strike', { flag: 'tn.couplet' }, O('You spoke the first line as you thrust, the second as he fell. The gentry of Hangzhou talked of nothing else for a month. A silk merchant sent you a jade pendant with the couplet carved on it.', { fame: 5, charm: 2, item: { jade_pendant: 1 }, flag: WIN })),
    C('Bow, and step off the plank yourself', O('You bowed and stepped neatly into the lake. "Graceful," said the gentry, "and humble." It was the most praise anyone has ever given you for falling into water.', { charm: 1 })),
  ] }),
  E('tn_ilgak_buns', T, { if: { age: [12, 30], alive: 'ilgak', loc: ['luoyang', 'songshan'], season: [0] }, title: 'The bun contest', text: 'At the lantern fair there is a steamed-bun contest, and a young Shaolin monk named Il-gak has been banned from it for three years running. He would like you to enter on his behalf. He will advise.', choices: [
    R('Eat for Shaolin', 'health', 50, O('Under Il-gak’s whispered coaching ("Breathe through the nose. Do not think of tomorrow.") you ate forty-one buns and won a sack of flour. He wept with joy and carried it home for you.', { wealth: 3, rel: { '@ilgak': { aff: 20, role: 'friend' } } }), O('You stopped at twenty-two. Il-gak, overcome, finished your plate, which disqualified you both. He has never been happier.', { health: -2, rel: { '@ilgak': { aff: 12 } } })),
    C('Arm-wrestle him for the right to enter', O('He won, entered under a false name, ate fifty buns, and was banned for a fourth year. He shared the flour with you anyway.', { rel: { '@ilgak': { aff: 10, res: 3 } }, health: 2 })),
    C('Tell him gluttony is a sin', O('"It is," Il-gak agreed sadly. "But so is waste." He was quiet for the rest of the fair. You felt terrible.', { rel: { '@ilgak': { aff: -3, res: 5 } } })),
  ] }),

  // ── Fixed bouts, pits and wagers ────────────────────────────────
  E('tn_purse_under_table', T, { if: { age: [16, 40], realm: '>=1', locType: 'city' }, once: false, cd: 6, title: 'A purse under the table', text: 'Before your next bout, a man in a merchant’s hat sits beside you at the noodle stall and slides a purse across the table. "Lose in the second exchange," he says. "Make it look honest."', choices: [
    C('Take it and lose', O('You lost in the second exchange, convincingly. The purse was heavy. So, for some time afterwards, was your sleep.', { wealth: 30, infamy: 2, fame: -2, sanity: -3, flag: 'tn.thrown' })),
    C('Take it and win anyway', O('You took his silver and won in the fourth exchange. Across the square, a man in a merchant’s hat stopped smiling.', { wealth: 30, infamy: 2, flag: [WIN, 'tn.crossed_fixer'], next: { id: 'tn_fixer_returns', in: 3 } })),
    R('Report him to the judges', 'charm', 25, O('The judges threw him out of the square and wrote your name in the ledger of honest fighters, which is a short ledger.', { rep: { orthodox: 4 }, fame: 2 }), O('The judges listened gravely. The next morning one of them was wearing a new hat. Nothing happened.', { sanity: -2 })),
    C('Push the purse back', O('He shrugged and stood. "Everyone has a price," he said. "Next time I will bring yours."', { sanity: 2 })),
  ] }),
  E('tn_fixer_returns', T, { on: 'scheduled', art: 'night', title: 'Interest', text: 'Three men are waiting in the alley behind your lodging. The man in the merchant’s hat is not with them, but his purse is, in spirit: they want it back, with interest.', choices: [
    Q('Pay them back with interest (45 taels)', { stat: { wealth: '>=45' } }, O('You paid. They counted it twice, wished you a long career and left. Expensive, but you still have all your fingers.', { wealth: -45 })),
    R('Fight your way out', 'power', 45, O('The first man found a wall, the second found the first man, and the third found urgent business elsewhere. Word got around.', { fame: 1, infamy: 1 }), O('There were three of them and one of you, and they had done this before. They took what you had and a tooth for interest.', { wealth: -20, health: -12, injury: { name: 'cracked ribs', seasons: 3, sev: 6 } })),
    R('Talk them round', 'charm', 30, O('You pointed out that their employer had bet badly, not you, and offered to tell them who he owed money to. They left to visit him instead.', { charm: 1, infamy: 1 }), O('They did not want to be talked round. They wanted silver, and took it.', { wealth: -15, health: -5 })),
    R('Go over the rooftops', 'body', 35, O('You were on the roof before the first one finished his threat, and three streets away before the second one found a ladder.', { body: 1 }), O('A loose tile ended your escape and nearly your ankle. They were very patient while you climbed down.', { wealth: -15, health: -8 })),
  ] }),
  E('tn_ghost_pit', T, { if: { age: [16, 45], realm: '>=1', loc: 'kaifeng' }, once: false, cd: 3, danger: true, art: 'night', title: 'The cistern', text: 'Beneath the Ghost Market, men fight in a dry cistern for silver and for the amusement of people who wear masks to watch. Tonight the house fighter is a shaven giant they call the Ox.', choices: [
    C('Climb down and fight the Ox', O('You climbed down the rope ladder. Above you, masks leaned over the rim.', { combat: { foe: { name: 'the Ox', kind: 'brawler', rel: 0.5, key: 'tn_ox' }, context: T, lethal: 0.05, win: { text: 'The Ox went down like a felled temple pillar. The masks threw silver into the cistern, and a little of it hit you.', wealth: 25, infamy: 2, fame: 1, flag: [WIN, 'tn.pit_won'] }, lose: { text: 'The Ox threw you against the cistern wall until you stopped getting up. They hauled you out with a hook and a bucket of water.', health: -6, sanity: -2 } } })),
    P('Bet on the Ox (8 taels)', 0.6, O('The Ox broke a southern boxer in four blows. The house paid you with a sneer and a string of cash.', { wealth: 8 }), O('A skinny southerner danced around the Ox until it fell over its own feet. The house kept your eight taels with real pleasure.', { wealth: -8 }), { req: { wealth: '>=8' } }),
    M('Fight the Ox. He drops his left shoulder before every rush.', 'foe.tn_ox', O('He dropped his left shoulder. You were already moving. The Ox found himself on his back, looking at the masks, and the masks were silent for the first time anyone could remember.', { wealth: 30, fame: 2, infamy: 1, flag: [WIN, 'tn.pit_won'] })),
    C('Leave', O('You climbed back up into the lantern light of the Ghost Market. Behind you, the crowd roared at somebody else’s pain.')),
  ] }),
  E('tn_cheat_needle', T, { if: { age: [14, 35], realm: '>=1', locType: ['city', 'estate'] }, once: false, cd: 5, title: 'A glint in the sleeve', text: 'The bout is declared bare-handed, but in the third exchange you catch a glint in your opponent’s sleeve: a needle, held between two fingers, waiting for a clinch.', choices: [
    R('Call the foul and prove it', 'insight', 35, O('You stepped back, raised a hand, and pointed. The judges found two needles and a very embarrassed cousin of somebody important. The bout went to you.', { fame: 3, flag: WIN, rep: { orthodox: 1 } }), O('By the time the judges looked, the needle was gone. They warned you for wasting their time.', { fame: -1 })),
    R('Never let him clinch', 'body', 40, O('You kept him at arm’s length for six exchanges, then swept his legs. When he fell, the needle rolled out of his sleeve in front of everyone.', { fame: 4, flag: WIN }), O('He got the clinch. The needle went into your forearm, and your arm went numb, and so did the bout.', { health: -6 })),
    Q('Catch the needle and give it back', { realm: '>=3' }, O('You took the needle out of his fingers in the clinch and pinned his sleeve to his collar with it. He yielded so fast the judges thought he had fainted.', { fame: 5, flag: WIN, infamy: 1 })),
  ] }),
  E('tn_bias', T, { if: { age: [14, 32], realm: '>=1', region: ['jiangnan', 'central', 'hebei'] }, once: false, cd: 6, title: 'The judges’ decision', text: 'You won. Everyone in the stands saw you win. The judges, after a short whispered conference, have awarded the bout to your opponent, whose uncle is sitting beside them.', choices: [
    R('Protest, publicly and well', 'charm', 35, O('You spoke for three minutes without raising your voice. By the end the crowd was chanting your name and the uncle was studying the sky. The decision was reversed.', { fame: 4, flag: WIN, rep: { families: -3 } }), O('You protested. The judges fined you for disrespect. The crowd booed them, which helped your pride and nothing else.', { wealth: -5, fame: 1 })),
    C('Bow to the judges, and to the crowd', O('You bowed to the judges, then turned and bowed to the stands. The stands roared. The judges looked at each other. Everyone knew who had won, including the uncle.', { fame: 3, sanity: 2 })),
    C('Challenge him to a rematch, no judges', O('He refused, of course. But he refused in front of four hundred people, and that is a kind of defeat that lasts.', { fame: 2, rep: { families: -1 } })),
  ] }),
  E('tn_blind_sword', T, { if: { age: [14, 45], realm: '>=1', locType: 'city' }, once: false, cd: 8, title: 'The blind swordsman', text: 'The crowd jeered when the blind swordsman entered, and stopped jeering after his second bout. Your name is next to his on the board.', choices: [
    R('Fight in silence', 'insight', 45, O('You took off your shoes and fought without a sound. He found you anyway, eventually, but by then you had found him first. He laughed and asked your name, so he would know your footsteps next time.', { fame: 3, flag: WIN, insight: 2 }), O('You fought in silence. He listened to your breathing instead, and tapped your wrist with his sword. "You hold your breath before you strike," he said. "Everyone does."', { insight: 3 })),
    R('Overwhelm him with speed', 'body', 45, O('Too many feet, too fast, too close. He yielded with a smile, and told you that you sounded like a summer rainstorm.', { fame: 3, flag: WIN }), O('You were fast. He heard the speed coming the way you would see a cart, and stepped aside.', { body: 1 })),
    C('Close your eyes too', O('You fought with your eyes shut, out of respect, and lost in four exchanges, and he embraced you afterwards in front of everyone. The crowd did not understand. He did.', { fame: 1, sanity: 4, insight: 1 })),
  ] }),
  E('tn_gentle_monk', T, { if: { age: [14, 40], realm: '>=1', region: ['central', 'jingchu'] }, once: false, cd: 8, title: 'The monk who would not strike', text: 'Your opponent is a young Shaolin monk who has taken a vow not to strike anyone this year. He has reached the fourth round by blocking until his opponents collapse.', choices: [
    R('Out-last him', 'health', 70, O('You struck for half an hour while he blocked. At last his arms dropped, and he bowed, and thanked you for helping him keep his vow.', { fame: 3, flag: WIN, body: 1 }), O('You collapsed first. He caught you before you hit the stone and laid you down gently, which is the most humiliating way to lose.', { health: -4 })),
    C('Refuse to strike either', O('You stood there with your hands at your sides. He stood there. After an hour the judges declared a draw and the crowd threw fruit. You and the monk shared the fruit.', { sanity: 4, rep: { orthodox: 2 }, insight: 1 })),
    R('Make him laugh until his guard breaks', 'charm', 35, O('Laughter is not a strike. You told him about your worst day. He laughed until he cried and stepped out of the ring by accident.', { fame: 2, flag: WIN }), O('He did not laugh. He listened, gravely, and then offered to pray for you.', { sanity: 2 })),
  ] }),

  // ── Rivals born in the ring ─────────────────────────────────────
  E('tn_mirror_rival', T, { if: { age: [14, 30], realm: '>=1', locType: 'city' }, art: 'duel', bind: { x: { ageRel: [-2, 2], realm: [1, 3], role: 'acquaintance', aff: 20, res: 30 } }, title: 'A mirror that dislikes you', text: 'In the semifinal you face {x}, who fights exactly like you: the same impatience, the same favourite feint, the same habit of smiling when hurt. It is like crossing swords with a mirror that dislikes you.', choices: [
    C('Fight', O('You both drew at the same moment, which annoyed you both.', { combat: { foe: 'x', context: T, lethal: 0, win: { text: '{x} picked {x.him}self up, wiped {x.his} mouth and said, "Again. Not today. But again." You found that you were looking forward to it.', fame: 2, flag: [WIN, 'tn.mirror'], rel: { x: { role: 'rival', res: 15, aff: -5 } }, next: { id: 'tn_mirror_rematch', in: 8 } }, lose: { text: '{x} won with your own favourite feint, half a breath faster. You will be thinking about it for years. So, it turns out, will {x.he}.', flag: 'tn.mirror', rel: { x: { role: 'rival', res: 10 } }, next: { id: 'tn_mirror_rematch', in: 8 } } } })),
    R('Out-think {x.him}: do the opposite of what you would do', 'insight', 35, O('You did everything you would never do, and {x} lost to a stranger wearing your face. "Who are you?" {x.he} demanded afterwards. A rivalry was born.', { fame: 2, flag: [WIN, 'tn.mirror'], rel: { x: { role: 'rival', res: 15 } }, next: { id: 'tn_mirror_rematch', in: 8 } }), O('{x} had the same idea. You both did the opposite, which made you the same again, and {x} was luckier.', { flag: 'tn.mirror', rel: { x: { role: 'rival', res: 8 } }, next: { id: 'tn_mirror_rematch', in: 8 } })),
    C('Shake {x.his} hand after the bout instead of glaring', O('You lost, shook hands, and laughed at the same moment about the same thing. You were friends before the next bout began.', { rel: { x: { aff: 20, res: 10, role: 'friend' } } })),
  ] }),
  E('tn_mirror_rematch', T, { on: 'scheduled', if: { npc: { x: { alive: true } } }, art: 'tournament', title: 'The bracket, again', text: 'Two years later, in another city, the bracket is posted, and there is {x}’s name beside yours again. {x.He} has been training. You can tell from across the square. So have you.', choices: [
    C('Fight', O('You met in the middle of the platform. Neither of you bowed.', { combat: { foe: 'x', context: T, lethal: 0, win: { text: 'You won, barely. {x} sat on the edge of the platform for a long time afterwards. Then {x.he} came and found you and told you exactly what you had done right, which no one else could have.', fame: 4, flag: WIN, rel: { x: { res: 15 } }, next: { id: 'tn_mirror_last', in: 40 } }, lose: { text: '{x} won, barely, and looked more relieved than proud. "I have been afraid of you for two years," {x.he} said. It was the nicest thing a rival ever told you.', fame: 2, rel: { x: { res: 10 } }, next: { id: 'tn_mirror_last', in: 40 } } } })),
    C('Withdraw, and buy {x.him} a drink', O('{x} was furious, then puzzled, then drunk. You talked about everyone you had both beaten. It was a long list and a good evening.', { rel: { x: { aff: 15, role: 'friend' } } })),
  ] }),
  E('tn_mirror_last', T, { on: 'scheduled', if: { npc: { x: { alive: true } } }, art: 'moon', title: 'One more', text: 'Years later, {x} finds you, greyer, with a limp {x.he} does not explain. "One more," {x.he} says. "For nobody. No judges, no crowd."', choices: [
    R('Fight under the moon', 'power', 60, O('You fought in an empty field until neither of you could lift a sword. You won, or you think you did. Neither of you was keeping score anymore.', { sanity: 6, rel: { x: { res: 10, aff: 15, role: 'friend' } } }), O('{x} won, and sat down in the grass laughing until {x.he} cried. "Finally," {x.he} said. You were glad for {x.him}, which surprised you both.', { sanity: 5, rel: { x: { aff: 20, role: 'friend' } } })),
    C('Swear brotherhood instead', O('You knelt in the field and swore to Heaven and Earth. Your rival is your sworn sibling now, which is what {x.he} always was, in a way.', { achieve: 'sworn', sanity: 8, rel: { x: { aff: 30, res: 10, role: 'sworn' } } })),
    C('Refuse', O('"We are too old," you said. {x} looked at you for a long moment and left without a word. You regretted it before {x.he} reached the road.', { rel: { x: { aff: -10 } }, sanity: -4 })),
  ] }),
  E('tn_young_master', T, { if: { age: [14, 28], realm: '>=1', locType: 'city' }, once: false, cd: 5, title: 'A lesson in public', text: 'A Qingcheng youngmaster in green silk, trailed by four juniors, declares that your stance insults the martial arts and that he will correct it for you, on the contest platform, in front of everyone.', choices: [
    C('Accept the exhibition bout', O('You climbed onto the platform. He made a speech. You waited.', { combat: { foe: { name: 'the Qingcheng youngmaster', kind: 'disciple', rel: 0.5 }, context: T, lethal: 0, win: { text: 'He landed in the front row of the stands. His juniors pretended not to know him. Qingcheng forgets no insult, and this one will be written down in a fine hand.', fame: 4, flag: [WIN, 'tn.qingcheng_grudge'], rep: { orthodox: -1 } }, lose: { text: 'He corrected your stance with the flat of his sword, at length. His juniors applauded every correction.', fame: -1 } } })),
    R('Decline with a joke the crowd will repeat', 'charm', 25, O('You said something about green silk and green fighters. The crowd laughed until he left. Qingcheng will remember that, too.', { fame: 2, flag: 'tn.qingcheng_grudge' }), O('Nobody laughed. He corrected your stance anyway, verbally, for some time.', { fame: -1 })),
    Q('End it in one move', { realm: '>=3' }, O('One step, one touch, and his sword was in your hand, hilt first, held out to him. The square went quiet. He took it back with both hands and did not make another speech that day.', { fame: 5, flag: [WIN, 'tn.qingcheng_grudge'], rep: { orthodox: -2 } })),
  ] }),
  E('tn_qingcheng_letter', T, { if: { age: [15, 45], flag: 'tn.qingcheng_grudge' }, fmt: 'letter', title: 'From Mount Qingcheng', text: 'A letter on fine green paper. The youngmaster’s uncle, an elder of Qingcheng, "invites" you to demonstrate your remarkable art at the sect’s next open day. The brushwork is beautiful. The meaning is not.', choices: [
    R('Go, and fight the uncle', 'power', 70, O('You went to Mount Qingcheng and beat the uncle in front of his whole sect. He bowed afterwards, stiffly, and struck your name from the grudge ledger. Then he wrote it in another one.', { fame: 6, rep: { orthodox: 3 } }), O('The uncle was a very different fighter from his nephew. He beat you courteously and thoroughly, and the grudge ledger was satisfied.', { fame: -2, health: -8, unflag: 'tn.qingcheng_grudge' })),
    Q('Send an apology and a brick of good tea', { item: 'tea_brick' }, O('Qingcheng accepted the tea, criticised its age, and closed the matter. Expensive humility, but cheaper than a grudge.', { take: { tea_brick: 1 }, rep: { orthodox: 2 }, unflag: 'tn.qingcheng_grudge' })),
    C('Ignore it', O('You used the letter to start a fire. Somewhere in Shu, an elder wrote a note in a ledger. You will meet Qingcheng again.', { rep: { orthodox: -3 } })),
  ] }),
  E('tn_sohee_disguise', T, { if: { age: [14, 22], alive: 'namgung_sohee', year: [14, 22], region: ['jiangnan', 'central'], realm: '>=1' }, art: 'tournament', title: 'A slender boy', text: 'Your third-round opponent is a slender boy with a cap pulled low and a sword style you would know anywhere: the Heavenly Emperor Sword of the Namgung. Boys do not usually have hands that small.', choices: [
    C('Fight her seriously', O('You drew. Beneath the cap, her eyes narrowed: she had seen that you knew.', { combat: { foe: '@namgung_sohee', context: T, lethal: 0, win: { text: 'You won, and kept your mouth shut. Namgung So-hee found you afterwards, cap in hand, hair down. "Thank you for not holding back," she said. "Nobody ever does that for me."', fame: 3, flag: [WIN, 'tn.sohee_secret'], rel: { '@namgung_sohee': { res: 20, aff: 10 } } }, lose: { text: 'She beat you clean and slipped away before the next round, before anyone could look too closely. Later, a note without a name: "You fought me as a swordsman. Thank you."', fame: 1, flag: 'tn.sohee_secret', rel: { '@namgung_sohee': { res: 10, aff: 10 } } } } })),
    R('Expose her to the judges', 'charm', 20, O('The judges pulled off her cap. Namgung retainers arrived within the hour to take her home. She looked at you once, and you will remember that look for the rest of your life.', { rep: { families: 3 }, rel: { '@namgung_sohee': { aff: -25 } } }), O('The judges thought you were making excuses, and laughed at you. She looked at you with something like pity.', { fame: -1, rel: { '@namgung_sohee': { aff: -5 } } })),
    C('Throw the bout, so she goes further', O('You lost on purpose, badly. She found you that night. "I did not need your help," she said. She did, and you both knew it, and she was furious about it for years.', { fame: -1, flag: 'tn.sohee_secret', rel: { '@namgung_sohee': { aff: 12, res: -5 } } })),
  ] }),
  E('tn_familiar_round', 'tournament', { if: { age: [14, 30], realm: '>=1', region: 'guanzhong', mem: 'secret.tn_kongtong_hook', ...LATER }, title: 'A face you know', text: 'Your first-round opponent is a broad-faced Kongtong boy with scarred knuckles. You have never met him in this life. In another, he put you on the boards in this same square with a left hook from below the belt.', choices: [
    M('Step right as the hook comes', 'secret.tn_kongtong_hook', O('The hook came, from below the belt, exactly as you remembered. You stepped right and it found nothing, and he found the boards. He stared up at you, bewildered. "How did you know?" You did not tell him.', { fame: 3, flag: WIN, sanity: 2 })),
    C('Fight him as if you did not know', O('You let the past go and fought him fresh. He hooked; you took it on the arm this time. You won on points, and bought him noodles, as you once had, in another life, after losing.', { fame: 2, flag: WIN, sanity: 3 })),
  ] }),

  // ── Sect, family and Cult ───────────────────────────────────────
  E('tn_red_sand', T, { if: { sect: 'cult', age: [8, 15] }, once: false, cd: 2, art: 'demonic', title: 'The Pit of Red Sand', text: 'The Cult’s children are counted twice a year in the Pit of Red Sand. Those who win eat at the long table. Those who lose eat what the winners leave.', choices: [
    C('Fight', O('A shaven-headed child with old eyes stepped into the pit opposite you.', { combat: { foe: { name: 'a Cult child with old eyes', kind: 'brawler', rel: 0 }, context: T, lethal: 0, win: { text: 'You won, and ate at the long table, and found you could not taste the food. The child you beat watched you from the sand.', rep: { cult: 4 }, fame: 1, sanity: -2, flag: WIN }, lose: { text: 'You lost, and ate the scraps, and learned what the Cult wanted you to learn from that.', health: -4, sanity: -3 } } })),
    R('Win without hurting anyone', 'insight', 30, O('You pinned your opponent without breaking anything. The watcher on the rim frowned, then wrote something down. Mercy is noted in the Cult, though not always kindly.', { rep: { cult: 2 }, insight: 1, flag: WIN }), O('There is no way to win in the Pit without hurting someone. You learned that the hard way, as the someone.', { health: -5 })),
    Q('Share your bread with Mok Cheol, who lost', { alive: 'mokcheol' }, O('You pushed half your bread across the sand to the quiet boy, Mok Cheol. He did not thank you. The next season, when you lost, he did the same.', { rel: { '@mokcheol': { aff: 20, role: 'friend' } }, rep: { cult: -1 }, sanity: 3 })),
  ] }),
  E('tn_haryeong_points', T, { if: { sect: 'cult', age: [10, 20], alive: 'haryeong', year: '<=28' }, art: 'demonic', title: 'That one', text: 'The Young Heavenly Demon, Dan Ha-ryeong, has come down to the Pit to watch. She is bored by the third bout. Then she points at you. "That one," she says. "Against me."', choices: [
    R('Fight her', 'power', 70, O('You touched her sleeve, once. The whole Pit went silent. She looked at the place on her sleeve for a long time, and then at you. "Again," she said, "next year."', { fame: 3, rep: { cult: 8 }, rel: { '@haryeong': { res: 25, aff: 10 } } }), O('She beat you in two moves and seemed disappointed it was not three. "You did not look away," she said. "Most of them look away."', { health: -5, rep: { cult: 3 }, rel: { '@haryeong': { res: 10 } } })),
    C('Kneel and decline the honour', O('"Boring," she said, and turned away. The Cult elders around her smiled. Nobody in the Pit spoke to you for a month.', { rep: { cult: -2 }, rel: { '@haryeong': { res: -5 } } })),
    R('Ask why she wants to fight a child', 'charm', 40, O('The elders froze. Dan Ha-ryeong laughed out loud. "Because everyone else lets me win," she said, and stayed to talk to you instead, which was much more dangerous.', { rel: { '@haryeong': { aff: 15, res: 10 } } }), O('She did not laugh. "Because I can," she said, and that was the end of it, and of your dinner.', { health: -3, rel: { '@haryeong': { res: 3 } } })),
  ] }),
  E('tn_red_banner', T, { if: { sect: 'cult', rank: [1, 2], age: [16, 45], realm: '>=2' }, once: false, cd: 4, art: 'demonic', title: 'The Red Banner Gathering', text: 'At the monthly Red Banner Gathering, any Demon Warrior may challenge a Commander for his place. It is called a contest. Losers rarely contest anything again.', choices: [
    R('Issue a challenge', 'power', 85, O('You broke the Commander’s guard and stopped your palm a finger from his heart, before the whole Gathering. The Cult respects strength; it respects restraint as a kind of strength.', { merit: 25, rep: { cult: 8 }, fame: 3 }), O('He broke your guard and did not stop. You crawled off the stage and spent a season healing in the dark.', { health: -15, injury: { name: 'shattered collarbone', seasons: 4, sev: 6 }, merit: -5 })),
    C('Watch, and note who is weak', O('You watched and counted: which Commanders favoured a leg, which looked at the elders before answering. Knowledge, in the Cult, is a blade with no hilt.', { insight: 2, merit: 3 })),
    Q('Challenge in the name of the Young Heavenly Demon', { alive: 'haryeong', year: '<=29', npc: { '@haryeong': { aff: '>=50' } } }, O('At her name, the Commander you challenged yielded without a blow and bowed to the empty seat at the top of the hall. You had made a point for her. She heard about it by nightfall.', { merit: 15, rep: { cult: 5 }, rel: { '@haryeong': { res: 12 } } })),
  ] }),
  E('tn_succession_call', T, { if: { faction: 'families', rank: [1, 2], age: [20, 45], realm: '>=2' }, art: 'estate', title: 'The succession contest', text: 'The family elders have announced a succession contest among the younger generation: three trials, one season apart. Your name is on the list, though nowhere near the top.', choices: [
    C('Enter', O('You bowed to the ancestral tablets and wrote your name in the book. Several cousins stopped speaking to you that afternoon.', { flag: 'tn.succession', next: { id: 'tn_succession_art', in: 1 } })),
    C('Support a cousin instead', O('You threw your weight behind a gentle cousin who had no chance. With you, the cousin had slightly more. The family noticed your loyalty, and filed it.', { rep: { families: 3 }, merit: 6 })),
    C('Withdraw quietly', O('You withdrew. Some heads are safer below the parapet, and yours has always been fond of your neck.', { sanity: 2 })),
  ] }),
  E('tn_succession_art', T, { on: 'scheduled', if: { faction: 'families' }, art: 'estate', title: 'The first trial', text: 'The first trial: perform the family’s ancestral art before the elders in the hall of tablets. Seven cousins go before you. Two of them weep afterwards.', choices: [
    R('Perform it as written', 'insight', 45, O('You performed it so exactly that an elder checked the scroll afterwards to be sure. You passed to the second trial.', { merit: 10, next: { id: 'tn_succession_bout', in: 1 } }), O('You forgot the ninth posture and improvised. The elders wrote something short. You are out.', { merit: 3 })),
    R('Perform it as you understand it', 'power', 80, O('You performed it as it ought to be, not as it was written. The oldest elder sat up straight for the first time in ten years. Second trial.', { merit: 12, insight: 2, next: { id: 'tn_succession_bout', in: 1 } }), O('Your understanding and the family’s did not agree. The family won.', { merit: 1, rep: { families: -2 } })),
  ] }),
  E('tn_succession_bout', T, { on: 'scheduled', if: { faction: 'families' }, art: 'tournament', bind: { x: { ageRel: [-3, 3], realm: [2, 4], role: 'acquaintance', aff: 25, res: 40 } }, title: 'The second trial', text: 'The second trial is a bout, in the family training yard, against your cousin {x}. The elders watch from the gallery. So do both your mothers.', choices: [
    C('Fight', O('You and {x} bowed to the gallery, then to each other.', { combat: { foe: 'x', context: T, lethal: 0, win: { text: '{x} yielded on one knee, and stood, and offered you {x.his} hand. Whatever happens in the last trial, you will need {x.him}.', merit: 10, rel: { x: { res: 15 } }, next: { id: 'tn_succession_question', in: 1 } }, lose: { text: '{x} beat you fairly. You bowed to {x.him}, and to the gallery, and went to your room, and did not come out for three days.', merit: 4, rel: { x: { res: 10, role: 'rival' } } } } })),
    R('Persuade {x} you should both withdraw', 'charm', 45, O('You persuaded {x} that the eldest cousin would be ruined by losing to either of you. You both withdrew; the eldest won; the family was saved a scandal, and noted who had saved it.', { merit: 8, rep: { families: 4 }, rel: { x: { aff: 15, role: 'friend' } } }), O('{x} heard you out and said, "No. I want to win." You respected that, and lost to it.', { merit: 3, rel: { x: { res: 5 } } })),
  ] }),
  E('tn_succession_question', T, { on: 'scheduled', if: { faction: 'families' }, art: 'estate', title: 'The last trial', text: 'The final trial is not a fight. The patriarch asks each remaining candidate one question, alone, in the hall of tablets: "What would you sacrifice for this family?"', choices: [
    C('"Anything."', O('The patriarch nodded slowly, as if it were the answer he had feared. You were named among the family’s chosen heirs. It weighs more than any sword.', { flag: 'tn.heir', rank: 1, merit: 20, rep: { families: 10 } })),
    C('"Not my conscience."', O('He was silent for a long time. Then he said, "Good," and gave the seat to someone else. Later, he sent you his own copy of the family’s heart method, with notes.', { merit: 10, insight: 3, sanity: 4, rep: { families: 2 } })),
    R('Answer him with a question', 'insight', 55, O('"What did you sacrifice?" you asked. The patriarch laughed until he coughed, then told you, for an hour. You came out heir-in-waiting, and the only one who knows his story.', { flag: 'tn.heir', rank: 1, merit: 25, rep: { families: 6 }, insight: 2 }), O('He looked at you coldly. "That is not an answer." It was not, and you were not chosen.', { merit: 3 })),
  ] }),

  // ── Trades and careers ──────────────────────────────────────────
  E('tn_escort_posts', T, { if: { age: [15, 35], loc: 'luoyang', career: 'none' }, title: 'The Dragon-Tiger posts', text: 'The Dragon-Tiger Escort Agency is hiring, and Chief Pyo Gwang hires the way his grandfather did: stand on the wooden posts for a hundred breaths while his men throw sandbags at you.', choices: [
    R('Climb the posts', 'body', 30, O('You stood through ninety breaths of sandbags and ten of pure stubbornness. Pyo Gwang grunted and handed you a red escort sash. A shy young guard named Kang Tae-o grinned at you with a crooked smile.', { career: 'escort', rep: { merchants: 3 }, meet: ['@escort_chief', '@taeo'], rel: { '@taeo': { aff: 10 } } }), O('A sandbag took you off the posts at breath forty. Pyo Gwang helped you up. "Come back when you are heavier," he said.', { body: 1, meet: '@escort_chief' })),
    R('Knock the sandbags back at the throwers', 'power', 45, O('You batted the sandbags back until the throwers ran out of arms. Pyo Gwang laughed for the first time in a year and hired you on the spot, as a guard, not a porter.', { career: 'escort', careerUp: 3, fame: 1, meet: '@escort_chief', rel: { '@escort_chief': { res: 15 } } }), O('You knocked one back. It hit Pyo Gwang. He was not amused, and you were not hired.', { rel: { '@escort_chief': { aff: -5 } } })),
    C('Watch, and ask about the pay first', O('The pay was poor and the roads were worse. The guards who passed the posts looked very proud of themselves anyway.', { insight: 1 })),
  ] }),
  E('tn_cutting_contest', T, { if: { age: [16, 70], career: 'smith' }, once: false, cd: 4, art: 'forge', title: 'The cutting contest', text: 'Smiths from three provinces have brought blades to the cutting contest: each blade must cut a rolled straw mat, a green bamboo pole, and a silk scarf dropped on its edge.', choices: [
    R('Enter a blade you forged with care', 'insight', 35, O('Your blade cut the mat, the pole and the scarf, which parted around the edge like water. Three swordsmen tried to buy it on the spot.', { careerUp: 4, wealth: 25, fame: 2 }), O('The mat and the pole, yes. The silk draped over your edge and lay there, mocking you.', { careerUp: 1 })),
    R('Swing the blade yourself, for the crowd', 'body', 40, O('You cut all three, then the judges’ table, by accident. The crowd adored you. The judges sent you a bill and an order for six swords.', { careerUp: 3, wealth: 12, fame: 3 }), O('The blade was perfect. Your swing was not. The bamboo won.', { careerUp: 1, charm: -1 })),
    C('Inspect the winners’ blades instead', O('You spent the afternoon squinting at other smiths’ edges and learned three things your master never told you, and one he did not know.', { careerUp: 2, insight: 1 })),
  ] }),
  E('tn_infirmary_tent', T, { if: { age: [14, 70], career: 'physician', locType: 'city' }, once: false, cd: 4, title: 'The infirmary tent', text: 'You are hired to run the infirmary tent at a city tournament. By noon you have set four arms, stitched a scalp, and confiscated a suspicious "tonic" from a fighter with very bright eyes.', choices: [
    R('Work the whole day through', 'insight', 30, O('Nobody died, nobody lost a limb, and by evening the fighters were calling you "physician" without a sneer. You learned more about broken bones in a day than in a year of books.', { careerUp: 3, wealth: 10, insight: 1, recipe: 'healing_salve' }), O('A fighter you cleared collapsed in his next bout. He lived. You did not sleep well for a week.', { careerUp: 1, sanity: -4 })),
    C('Sell the confiscated tonic', O('A bookmaker bought it for fifteen taels and the tonic’s owner for thirty. You sold it to the bookmaker. That was a mistake you will carry.', { wealth: 15, infamy: 2 })),
    R('Work out what was in the tonic', 'insight', 45, O('Ephedra, ground beetle and a dash of something from Dang country. It makes a fighter fearless and stops his heart at forty. You wrote it down and burned the rest.', { careerUp: 2, insight: 2, codex: { id: 'secret.tn_tonic', cat: 'recipes', title: 'The fighters’ tonic', text: 'Bright eyes before a bout mean ephedra, ground beetle and Dang mountain moss. It works, and it kills its users by forty. Licorice root and cold tea undo it, if given early.' } }), O('You could not tell. You poured it out on principle.', { careerUp: 1 })),
  ] }),
  E('tn_broker_odds', T, { if: { age: [14, 70], career: 'informant', locType: 'city' }, once: false, cd: 4, title: 'Selling the odds', text: 'Bettors pay well to know which fighter drank too much last night, and whose master is secretly ill. You know both.', choices: [
    R('Sell the secrets, carefully', 'charm', 30, O('You sold each secret once, to the right buyer, at the right price. By evening you had made more than the winner.', { wealth: 20, careerUp: 3 }), O('Your buyer had already heard it from a beggar for half the price. You had to sell cheap.', { wealth: 4, careerUp: 1 })),
    P('Sell the same secret to both sides', 0.5, O('Both sides paid. Both sides lost. Neither side has worked out why.', { wealth: 35, infamy: 2, careerUp: 2 }), O('The two buyers compared notes. Then they compared fists, on you.', { wealth: -10, health: -8 })),
    C('Keep it, and bet on it yourself', P('Keep it, and bet on it yourself', 0.6, O('You bet on the sober fighter with the healthy master. Information is a kind of money, and today it bred.', { wealth: 15 }), O('The drunk fighter fought better drunk. Information is a kind of money, and today it was counterfeit.', { wealth: -10 }))),
  ] }),

  // ── The military examination ────────────────────────────────────
  E('tn_wuju', T, { if: { age: [17, 35], loc: 'capital', notSect: ['cult'] }, art: 'palace', title: 'The military examination', text: 'Every three years the Ministry of War holds the martial examinations: archery from horseback, the lifting of the stone, and an essay on strategy that most candidates pay someone else to write.', choices: [
    C('Register as a candidate', O('You wrote your name, your father’s name and your county on a form in triplicate. A clerk stamped all three without looking up.', { next: { id: 'tn_wuju_field', in: 1 } })),
    R('Sell essays to the candidates', 'insight', 40, O('You wrote eleven essays on strategy in a week, each in a different hand. Four of your essays passed. You did not.', { wealth: 25, infamy: 1 }), O('A Ministry clerk recognised your hand in two essays from two different candidates. You paid a fine and an apology.', { wealth: -5, rep: { court: -3 } })),
    C('Watch the archery from the wall', O('You watched country boys and generals’ sons shoot from galloping horses. The country boys were better. The generals’ sons passed.', { insight: 1 })),
  ] }),
  E('tn_wuju_field', T, { on: 'scheduled', art: 'palace', title: 'The field', text: 'The field: three arrows from a galloping horse at a straw target, then a stone weighing as much as two men to be raised above the head while the examiners count.', choices: [
    R('Shoot, then lift', 'body', 45, O('Two arrows of three and the stone overhead for a count of ten. The examiners wrote something longer than usual. On to the essay.', { fame: 2, next: { id: 'tn_wuju_essay', in: 1 } }), O('You hit the target once and the stone not at all. The examiners wrote something short.', { body: 1 })),
    Q('Lift the stone with one hand, for the crowd', { realm: '>=3' }, O('You lifted the stone with one hand and held it there while you bowed to the examiners with the other. The crowd went wild. The examiners, who disapprove of showmanship, passed you anyway.', { fame: 4, rep: { court: 2 }, next: { id: 'tn_wuju_essay', in: 1 } })),
  ] }),
  E('tn_wuju_essay', T, { on: 'scheduled', art: 'scroll', title: 'The essay', text: 'The essay question: "On the proper use of the murim in the defence of the realm." Every examiner in the hall was appointed by the Eastern Depot.', choices: [
    R('Write what they want to read', 'insight', 35, O('You wrote that the murim is a sword and the Court its hand. The examiners nodded all the way down the page. You passed, with a seal and a sword from the Ministry.', { rep: { court: 10 }, fame: 2, item: { fine_sword: 1 }, flag: 'tn.wuju_pass', next: { id: 'tn_wuju_post', in: 2 } }), O('You wrote what they wanted, badly. They could tell you did not mean it, which is worse than meaning the wrong thing.', { rep: { court: 1 } })),
    R('Write what you believe', 'insight', 50, O('You wrote that a realm that fears its own martial artists will soon need them and not have them. You passed, narrowly. One examiner wrote "dangerous" in the margin.', { rep: { court: 3 }, insight: 2, flag: 'tn.wuju_pass', next: { id: 'tn_wuju_post', in: 2 } }), O('You wrote what you believed. The examiners agreed it was what you believed, and failed you for it.', { rep: { court: -3 }, sanity: 2 })),
    C('Draw a turtle and leave', O('You drew a very good turtle and handed it in. You are, as far as anyone knows, the only candidate in a century to fail the essay with a drawing. It is still in the Ministry archive.', { fame: 1, charm: 1 })),
  ] }),
  E('tn_wuju_post', T, { on: 'scheduled', if: { flag: 'tn.wuju_pass' }, fmt: 'letter', title: 'A posting', text: 'A Ministry clerk delivers your posting: a junior officer’s commission at the frontier garrison of Jade Gate, with a horse, a salary and a great deal of sand.', choices: [
    C('Accept the commission', O('You rode west with a commission in your sleeve. The garrison at Jade Gate was glad to see someone who could read and fight, and gladder still to see your horse.', { travel: 'jadegate', wealth: 20, rep: { court: 5 } })),
    C('Decline it politely', O('You declined. The clerk was not surprised; the best candidates usually do. Your degree still opens doors in the capital, quietly.', { rep: { court: 1 } })),
  ] }),

  // ── The Murim Alliance’s assemblies ─────────────────────────────
  E('tn_qualifier', T, { if: { age: [11, 30], realm: '>=1', notLoc: 'luoyang', ...PRE_ASSEMBLY }, once: false, cd: 5, art: 'tournament', title: 'The regional qualifier', text: 'Before the Dragon-Phoenix Assembly, each region holds a qualifying contest. The winner gets a jade token, a map of the road to Luoyang, and a lecture about representing {region} with dignity.', choices: [
    R('Fight for the token', 'power', 45, O('You won the token, the map and the lecture, and set out for Luoyang with the whole region’s hopes on your back. They were heavier than the jade.', { fame: 3, flag: ['tn.qualified', WIN], travel: 'luoyang' }), O('You lost in the semifinal to someone who will probably lose in Luoyang. That is the consolation everyone offered you.', { fame: 1 })),
    C('Go to Luoyang anyway, as a spectator', O('You packed a bag and walked to Luoyang to watch the Assembly from the cheap seats. Everyone who matters will be there.', { travel: 'luoyang' })),
    C('Stay home', O('You stayed home. The Assembly will happen without you, as most things do.')),
  ] }),
  E('tn_assembly_after', T, { if: { age: [11, 60], loc: 'luoyang', ...POST_ASSEMBLY }, once: false, cd: 5, art: 'inn', title: 'After the Assembly', text: 'The Assembly is over. Luoyang’s inns are full of losers drinking to forget and winners pretending they do not want to be recognised.', bind: { x: { ageRel: [-3, 3], realm: [1, 3], role: 'acquaintance', aff: 35 } }, choices: [
    C('Drink with the losers', O('You drank with a table of first-round losers until the losers were singing. One of them, {x}, sang worst and laughed loudest, and you liked {x.him} immediately.', { charm: 1, sanity: 4, rel: { x: { aff: 20, role: 'friend' } } })),
    R('Find a semifinalist and ask for a private bout', 'power', 65, O('A semifinalist, bored and a little drunk, agreed. You beat {x.him} in the inn yard. Nobody saw it except the cook, who tells everyone.', { fame: 3, rel: { x: { res: 20 } } }), O('The semifinalist was not drunk enough. You learned why {x.he} had reached the semifinal.', { health: -4, insight: 1 })),
    P('Collect the dropped betting slips', 0.25, O('Among the trampled slips you found an unclaimed winner. The bookmaker paid it with a face like spoiled milk.', { wealth: 12 }), O('Losing slips, every one. A whole city’s worth of bad decisions, and none of them yours.', { insight: 1 })),
  ] }),
  E('tn_seol_loses', T, { if: { year: [18, 18], season: [2, 3], loc: 'luoyang', alive: 'seol', age: [14, 40] }, art: 'tournament', title: 'A careful loss', text: 'In the second round of the Assembly, a girl from a ruined Chang’an family loses to a fighter she was clearly beating. It looks like an accident to everyone in the stands but you.', choices: [
    R('Watch her closely afterwards', 'insight', 45, O('She walked off the platform without looking at the crowd, then stopped and looked straight at you, as if checking you were where she expected. You were not, it seemed. She looked, for a moment, frightened.', { flag: 'tn.seol_watched', insight: 1, codex: { id: 'secret.tn_seol_loss', cat: 'people', title: 'The girl who lost on purpose', text: 'At the Assembly of Year 18, a girl from a ruined Chang’an family threw a bout she was winning. She did not want to be noticed. She looked at you as if you were somewhere you should not be.' } }), O('You looked for her afterwards, but she was gone before the next round began, the way people go who know the crowd’s every move in advance.', { insight: 1 })),
    C('Forget it', O('People lose bouts for all sorts of reasons. You had a dumpling and thought no more about it.')),
  ] }),
  E('tn_wartime_ring', T, { if: { year: [35, 41], age: [14, 60], region: ['central', 'jingchu', 'guanzhong', 'hebei'] }, once: false, cd: 3, art: 'war', title: 'A ring of rope', text: 'There are no tournaments in wartime. In the refugee camp outside the city, men fight barehanded inside a ring of rope, and the prize is a sack of rice.', choices: [
    R('Fight for the rice', 'body', 45, O('You won the sack and carried it to the woman with three children who had been watching from the edge of the ring. She did not thank you. She did not have to.', { sanity: 5, fame: 1 }), O('A man who had not eaten in three days beat you, because he needed it more. You did not begrudge him.', { health: -5, sanity: -2 })),
    R('Organise the camp so the rice is shared', 'charm', 35, O('You talked the fighters into fighting for a common pot. For one winter that camp ate better than its neighbours, and fought less.', { fame: 3, sanity: 6, rep: { orthodox: 2 } }), O('Hungry men do not want speeches. They wanted the rice, and fought you for it.', { health: -4 })),
    C('Give your own rations to the losers', O('You gave away your rations, and were hungry for a month, and did not regret it.', { health: -6, sanity: 4 })),
  ] }),
  E('tn_war_orphans', T, { if: { year: [43, 44], age: [30, 90], realm: '>=3' }, title: 'A generation raised in war', text: 'The Alliance is reviving the Dragon-Phoenix Assembly for a generation that grew up in war. There are orphans with talent and no sect, and the Alliance is asking for sponsors.', bind: { x: { age: [14, 17], realm: [1, 2], role: 'acquaintance', aff: 50 } }, choices: [
    Q('Sponsor a war orphan (30 taels)', { stat: { wealth: '>=30' } }, O('You paid the entry fee for a sharp-eyed orphan named {x}, bought {x.him} boots, and spent a season teaching {x.him} to stop flinching. {x.He} calls you master now, and means it.', { wealth: -30, fame: 3, achieve: 'first_disciple', rel: { x: { aff: 30, res: 30, role: 'disciple' } }, next: { id: 'tn_orphan_bout', in: 2 } })),
    C('Donate rice to the Assembly kitchens', O('You sent ten sacks of rice. Nobody will remember who sent it, which is fine. Everybody will remember that they ate.', { wealth: -10, fame: 2, sanity: 3 })),
    C('Decline', O('You have done your part, you told yourself. The war took enough from everyone.')),
  ] }),
  E('tn_orphan_bout', T, { on: 'scheduled', if: { npc: { x: { alive: true } } }, art: 'tournament', title: 'In a borrowed robe', text: '{x} steps onto the Assembly platform in a borrowed robe, looks for you in the stands, and finds you.', choices: [
    R('Shout the advice you agreed on', 'insight', 45, O('"Left!" you shouted, and {x} went left, and the bout was over. {x.He} reached the third round, which for an orphan with borrowed boots is a kind of miracle.', { fame: 3, rel: { x: { res: 15, aff: 10 } }, npcRealm: { x: 1 } }), O('Your advice was wrong. {x} lost in the first round, and forgave you before you could apologise.', { rel: { x: { aff: 8 } } })),
    P('Stay silent, and let {x.him} fight', 0.45, O('{x} fought like someone with nothing to lose, which was true, and won two rounds on courage alone. You did not cheer. You could not speak.', { sanity: 6, rel: { x: { res: 20 } } }), O('{x} lost, and walked off the platform with {x.his} head up. You have never been prouder of anyone.', { sanity: 4, rel: { x: { aff: 10 } } })),
  ] }),
  E('tn_kunlun_challenge', T, { if: { year: [48, 50], age: [16, 90], region: 'central', realm: '>=2' }, art: 'snow', title: 'Kunlun comes down', text: 'Kunlun has come down from its mountains. Its young swordsmen are challenging the best of the Central Plains on a platform in Luoyang, one bout a day, for a month. They have not lost yet.', choices: [
    C('Answer the challenge', O('A Kunlun swordsman in white bowed to you, barely.', { combat: { foe: { name: 'a Kunlun swordsman in white', kind: 'disciple', rel: 0.5 }, context: T, lethal: 0, win: { text: 'The Kunlun swordsman picked himself up, looked at you as if you were weather he had not been warned about, and bowed properly this time. The Central Plains roared.', fame: 8, flag: WIN, rep: { orthodox: 5 } }, lose: { text: 'Cloud Dragon steps: he was never where your sword went. Kunlun’s record stood. Yours did not.', fame: 1 } } })),
    R('Study their footwork from the stands', 'insight', 50, O('By the twentieth day you could see the Cloud Dragon steps before they happened. You did not fight. You did not need to; you will need it later.', { insight: 3, mastery: { kun_cloud_step: 6 } }), O('They moved like falling snow. You could not follow it, only admire it.', { insight: 1 })),
    C('Buy the Kunlun disciples a hot meal', O('They had never eaten Luoyang noodles. You watched a dozen of the most aloof swordsmen under Heaven fight over the last bowl like children.', { wealth: -3, charm: 1, rep: { orthodox: 1 } })),
  ] }),
  E('tn_registry_trials', T, { if: { year: [55, 62], age: [16, 80], realm: '>=1', notSect: ['easterndepot'] }, art: 'palace', title: 'Loyalty trials', text: 'Since the Registry Edict, every martial artist must register with the Court, and the Eastern Depot holds "loyalty trials": public bouts in which registered fighters demonstrate their arts for the officials’ files.', choices: [
    C('Register, and fight for the record', O('You fought three Depot officers for the record and were filed under "capable, cooperative". The orthodox world will call it collaboration. The Court will call it sense.', { rep: { court: 6, orthodox: -3 }, fame: 1, flag: 'tn.registered' })),
    R('Perform badly on purpose, so they file you as harmless', 'insight', 40, O('You fumbled every form with total conviction. Your file says "mediocre". It is the safest word in the empire.', { rep: { court: 1 }, sanity: 2, flag: 'tn.registered' }), O('The officers were not fooled. Your file is thick now, and has your face in it.', { rep: { court: -4 } })),
    C('Refuse to register', O('You refused, loudly, in the square. Some cheered. The Depot clerks wrote your name down with great care.', { rep: { court: -8, orthodox: 3 }, infamy: 3 })),
  ] }),
  E('tn_century', T, { if: { year: [100, 100], age: [60, 300], region: 'central' }, art: 'tournament', title: 'The Century Assembly', text: 'A hundred years of the Murim Alliance, and every living master has come to Luoyang. You are among the oldest there. Young people keep bowing to you by accident.', bind: { x: { age: [14, 18], realm: [1, 1], role: 'acquaintance', aff: 40 } }, choices: [
    R('Give an exhibition the young will remember', 'power', 150, O('You moved through a form you had practised for ninety years. When you finished, nobody in the arena spoke. A child in the front row began, very quietly, to copy it.', { fame: 12, rep: { orthodox: 5 }, sanity: 5 }), O('Your knees had opinions. The exhibition was dignified, short and politely applauded.', { fame: 3 })),
    C('Sit with the other old masters and trade lies', O('You and the other relics told each other about duels that went on longer every telling. Half of you had fought each other. Nobody remembered who won, and nobody minded.', { sanity: 8, charm: 1 })),
    C('Find the youngest competitor and teach {x.him} one thing', O('You found {x}, fourteen and terrified, and showed {x.him} how to breathe before a bout. {x.He} lost anyway. But {x.he} came back the next day and asked to be your disciple.', { achieve: 'first_disciple', rel: { x: { aff: 30, res: 30, role: 'disciple' } }, sanity: 4 })),
  ] }),

  // ── Judges, elders and family ───────────────────────────────────
  E('tn_judge_invite', T, { if: { age: [35, 90], realm: '>=3', stat: { fame: '>=30' }, not: 'tn.judge' }, fmt: 'letter', from: '@alliance_leader', title: 'An invitation to judge', text: 'A letter with the Murim Alliance seal: you are invited to sit on the judging panel of the regional tournaments. The Alliance Leader adds a postscript in his own hand, praising your fairness, which he has never witnessed.', choices: [
    C('Accept', O('You accepted. The robe is uncomfortable, the chair is worse, and everyone you rule against will hate you for a decade. It is an honour.', { flag: 'tn.judge', rep: { orthodox: 4 }, fame: 2 })),
    C('Decline politely', O('You declined. Judging tournaments is how good fighters turn into bad politicians.', { sanity: 2 })),
  ] }),
  E('tn_old_legend', T, { if: { age: [55, 300], realm: '>=2', stat: { fame: '>=40' } }, once: false, cd: 8, title: 'The legend', text: 'A youth with a borrowed sword and a famous father has challenged you on the city platform. He wants to beat a legend. You are, apparently, the legend.', choices: [
    R('Beat him gently', 'power', 70, O('You disarmed him three times, each time more kindly. On the third, he laughed, and bowed, and asked you to teach him. You did not, but you thought about it.', { fame: 2, sanity: 3 }), O('He beat you, and was so astonished that he forgot to celebrate. You were proud of him anyway, which surprised you.', { fame: -3, sanity: -3 })),
    C('Lose on purpose, convincingly', O('You lost to him in seven exchanges, with a stumble at the end that only a master could have faked. He will spend his life telling the story wrong.', { fame: -2, sanity: 4 })),
    C('Decline, and show him the move you would have beaten him with', O('You showed him, slowly, on the platform, with the whole square watching. He went home without fighting anyone and practised it until spring.', { fame: 2, insight: 1 })),
  ] }),
  E('tn_elder_judge', T, { if: { age: [50, 120], locType: ['village', 'city'], home: true }, once: false, cd: 6, art: 'garden', title: 'Judge of the shrine yard', text: 'The neighbourhood children are holding their stick-sword tournament behind the shrine, and they have asked you, as the oldest fighter they know, to judge. They have very strong views on the rules.', choices: [
    C('Judge strictly by the rules', O('You judged strictly. The children respected you, feared you, and complained about you to their parents, which is what judges are for.', { sanity: 3, charm: 1 })),
    R('Make sure every child wins something', 'charm', 30, O('By sunset there was a General, a Vice-General, a Most Fearsome, a Best Bow and a Fastest Crier. Nobody went home without a title.', { sanity: 6, fame: 1 }), O('You tried to give everyone a prize and pleased no one. The General accused you of corruption. She was seven.', { sanity: 2 })),
    C('Show them one real form at the end', O('At the end you took a stick and showed them one real form, slowly. They went silent. One small girl went home and practised it until dark, and you thought of yourself at that age, a long time ago.', { sanity: 4, insight: 1 })),
  ] }),
  E('tn_child_fair', T, { if: { age: [25, 70], has: 'child', npc: { x: { age: [6, 15] } } }, bind: { x: 'child' }, once: false, cd: 4, title: 'Not to shout', text: '{x} has entered the children’s contest at the {season} fair and is pretending not to be nervous. {x.He} has asked you, three times, not to shout.', choices: [
    C('Shout anyway', O('You shouted. {x} pretended not to know you, and won the first round, and looked up at you in the crowd for a moment with a face you will keep forever.', { sanity: 5, rel: { x: { aff: -2, res: 3 } } })),
    R('Coach {x.him} the night before', 'insight', 30, O('You taught {x} one thing only: keep your eyes on the belly button, not the fists. {x.He} won two rounds and came home insufferable.', { rel: { x: { aff: 8, res: 8 } } }), O('You taught {x} three things the night before and {x.he} forgot all of them on the platform. {x.He} had fun anyway.', { rel: { x: { aff: 4 } } })),
    Q('Bribe the judge (5 taels)', { stat: { wealth: '>=5' } }, O('{x} won the whole contest. A week later {x.he} found out why, and did not speak to you until the new moon.', { wealth: -5, infamy: 1, rel: { x: { res: -12, aff: -4 } } })),
  ] }),
  E('tn_disciple_enters', T, { if: { age: [25, 120], has: 'disciple' }, bind: { x: 'disciple' }, once: false, cd: 4, title: 'Ready, or nearly', text: '{x} wants to enter the city tournament. {x.He} is ready, or nearly ready, or not ready at all; you cannot decide which.', choices: [
    P('Let {x.him} enter', 0.5, O('{x} won two bouts and lost the third, honourably. {x.He} found you afterwards and said, "I know what to work on now." That is a teacher’s whole reward.', { fame: 2, rel: { x: { res: 10, aff: 5 } } }), O('{x} lost in the first round and took it hard. You sat with {x.him} on the platform steps until the square was empty.', { rel: { x: { aff: 8 } } })),
    C('Forbid it', O('You forbade it. {x} trained twice as hard out of pure spite, which was, you will admit only to yourself, the plan.', { rel: { x: { aff: -6, res: 4 } } })),
    R('Train {x.him} one more season first', 'insight', 40, O('You drilled {x} through the whole season. {x.He} entered the next tournament a different fighter.', { npcRealm: { x: 1 }, rel: { x: { res: 10 } } }), O('You drilled {x} for a season and {x.he} grew tired of you rather than better.', { rel: { x: { aff: -4 } } })),
  ] }),
  E('tn_friend_nerves', T, { if: { age: [16, 60], has: 'friend' }, bind: { x: 'friend' }, once: false, cd: 5, title: 'Nerves', text: '{x} is fighting in the city contest tomorrow and has been sick with nerves all evening. Half the inn is betting against {x.him}.', choices: [
    P('Bet on {x.him} (10 taels)', 0.5, O('{x} won, and you won, and you spent your winnings on a feast that {x.he} was too excited to eat.', { wealth: 20, rel: { x: { aff: 8 } } }), O('{x} lost, and you lost, and {x.he} insisted on paying you back. You would not let {x.him}.', { wealth: -10, rel: { x: { aff: 6 } } }), { req: { wealth: '>=10' } }),
    C('Stay up and keep {x.him} calm', O('You told {x} stories until {x.he} fell asleep at the table. {x.He} fought better for the sleep. Friends are a kind of medicine.', { rel: { x: { aff: 10 } }, sanity: -1 })),
    P('Bet against {x.him}, quietly', 0.5, O('{x} lost. You won twelve taels and could not look {x.him} in the eye all evening.', { wealth: 12, sanity: -3 }), O('{x} won, and you lost ten taels, and deserved to.', { wealth: -10, sanity: -1 }), { req: { wealth: '>=10' } }),
  ] }),

  // ── A name in the ring ──────────────────────────────────────────
  E('tn_ring_tea', T, { if: { age: [16, 35], married: false, realm: '>=1', locType: 'city' }, bind: { x: { ageRel: [-3, 3], realm: [1, 3], role: 'acquaintance', aff: 35, res: 35, romance: true, minAge: 16 } }, title: 'After the bout', text: 'The fighter you beat this morning, {x}, is waiting outside the inn with two cups of tea and an expression that is either a challenge or an invitation. Possibly both.', choices: [
    C('Take the tea', O('You talked about the bout until the tea was cold, and then about other things until the inn closed. {x} wants a rematch. {x.He} is in no hurry to have it.', { rel: { x: { aff: 15, res: 5 } } })),
    R('Offer to show {x.him} the move that beat {x.him}', 'charm', 30, O('You showed {x} the move in the inn yard, slowly, standing much closer than the move required. Neither of you mentioned it.', { rel: { x: { aff: 20, res: 10 } } }), O('You showed {x} the move. {x.He} learned it at once and used it on you. That was the end of the evening, and the start of something.', { rel: { x: { res: 15, aff: 5 } } })),
    C('Tell {x.him} you have no time for tea', O('{x} poured both cups out on the step and walked away. You wondered about it for longer than you should have.', { rel: { x: { aff: -5 } } })),
  ] }),
  E('tn_ring_injury', T, { if: { age: [15, 60], flag: 'tn.wins>=3' }, title: 'Wrong', text: 'In your last bout, your opponent landed wrong, and his knee bent in a direction knees do not go. The physicians say he will walk. They do not say he will fight.', choices: [
    C('Visit him', O('He was angry, then not. He asked you to show him the move that did it, so he could teach it to someone one day. You showed him.', { sanity: 3, insight: 1 })),
    Q('Send money for his treatment (20 taels)', { stat: { wealth: '>=20' } }, O('You sent twenty taels and no name. A month later, a letter came back, unsigned, with one word: "Thank you."', { wealth: -20, sanity: 4 })),
    C('Tell yourself it is the risk of the ring', O('It is the risk of the ring. You fought a little more carefully after that, and never told anyone why.', { sanity: -4, insight: 1 })),
  ] }),
  E('tn_ring_name', T, { if: { age: [15, 70], flag: 'tn.wins>=5' }, title: 'A name you did not choose', text: 'Somewhere between your fifth and sixth tournament win, the storytellers gave you a name. You did not get a say in it.', choices: [
    C('Embrace it', O('You started introducing yourself by it. People stood up straighter when you did. It is a kind of armour, a name.', { fame: 5 })),
    C('Hate it quietly', O('You hated it, quietly, for the rest of your life. It will probably be on your tombstone.', { fame: 3, sanity: -1 })),
    R('Suggest a better one to the storytellers', 'charm', 35, O('You bought the storytellers a round and suggested something more dignified. Remarkably, it stuck.', { fame: 6, charm: 1 }), O('The storytellers listened carefully, thanked you, and made it worse.', { fame: 4 })),
  ] }),
  E('tn_challengers', T, { if: { age: [18, 70], flag: 'tn.wins>=8' }, once: false, cd: 5, title: 'The line outside the inn', text: 'Young fighters wait outside your inn every morning, each hoping for a bout with the famous fighter. The innkeeper has started charging them for the wait.', choices: [
    R('Fight them all, one a day', 'body', 60, O('You fought one a day for a month and lost none. The line got shorter, then stopped. You were faintly sad when it did.', { fame: 4, body: 1 }), O('On the nineteenth day, a quiet girl with a fishing spear beat you. The line doubled the next morning.', { fame: -2, health: -5 })),
    C('Go out by the kitchen door', O('You went out by the kitchen door, every morning, for a month. The cook started charging you too.', { wealth: -2 })),
    C('Pick the best of them and teach instead', O('You chose the one who had waited longest without complaining and taught them nothing for a week but how to wait. The others went home.', { insight: 1, fame: 1 })),
  ] }),
];

// ── Templates ──────────────────────────────────────────────────────

// One open bout per fighting style. Some are fought out; others are decided by the right idea.
const BOUT_ROWS = [
  { key: 'qingcheng', if: { region: 'shu' }, title: 'Pine wind', text: 'An open bout at the Chengdu brocade fair pairs you with a Qingcheng disciple who bows, smiles, and murmurs that your teacher must be very patient.',
    foe: { name: 'the Qingcheng disciple', kind: 'disciple', rel: 0.3 }, enter: 'He drew with a flourish that cost him nothing and impressed everyone.', win: 'His Pine Wind Sword was beautiful, and you hit him anyway. He will remember your face; Qingcheng always does.', lose: 'He beat you with three elegant cuts and one inelegant remark. The crowd remembered the remark.',
    winFx: { flag: [WIN, 'tn.qingcheng_grudge'], rep: { orthodox: 1 } }, fame: 3, prize: 8,
    rollT: 'Read the real cut hidden in his flourish', stat: 'insight', dc: 35, ok: 'Every Qingcheng flourish hides one real cut. You waited for it, stepped inside it, and put him on the boards.', no: 'You read the flourish perfectly. Unfortunately, the flourish was the cut.', noFx: { health: -4 },
    altT: 'Insult his teacher back, then withdraw', alt: 'You suggested his teacher must be very patient too, and walked off before he could answer. Qingcheng has added you to a long list.', altFx: { charm: 1, flag: 'tn.qingcheng_grudge' } },
  { key: 'kongtong', if: { region: 'guanzhong' }, title: 'Scarred knuckles', text: 'At the Chang’an spring contest you draw a broad-faced Kongtong boy with scarred knuckles, who cracks each of them, slowly, while staring at you.',
    fame: 3, prize: 6, rollT: 'Trade blows with him', stat: 'body', dc: 40, ok: 'You took his Seven Injuries Fist on the forearms and gave back a knee he did not see coming. The Kongtong elders nodded, which for them is applause.', okFx: { rep: { orthodox: 1 } },
    no: 'He opened with a left hook from somewhere below his belt. You woke on the boards with the shape of it memorised.', noFx: { health: -5, codex: { id: 'secret.tn_kongtong_hook', cat: 'people', title: 'The Kongtong boy’s left hook', text: 'A broad-faced Kongtong disciple at the Chang’an spring contest always opens with a rising left hook from below the belt. Step right and it finds nothing.' } },
    altT: 'Ask him about his knuckles', alt: 'He told you about the iron sand pots, the wooden posts and the stone wall, in loving detail, and forgot to fight. You both forfeited, and ate noodles.', altFx: { charm: 1, fame: -1 } },
  { key: 'shaolin', if: { region: 'central' }, title: 'The temple bell', text: 'Your opponent at the Song Mountain fair is a Shaolin lay disciple built like a temple bell, who apologises to you in advance for whatever happens.',
    foe: { name: 'the Shaolin lay disciple', kind: 'disciple', rel: 0.4 }, enter: 'He put his palms together, said a short sutra for both of you, and came forward like a landslide in no hurry.', win: 'You found the one place his Golden Bell did not cover, and he sat down with an expression of mild wonder. He thanked you, and meant it.', lose: 'Hitting him was like hitting a temple bell: loud, painful, and mostly bad for you. He helped you up and asked whether you had eaten.',
    winFx: { flag: WIN, rep: { orthodox: 2 } }, fame: 3, prize: 5,
    rollT: 'Tire him out', stat: 'body', dc: 45, ok: 'You ran rings around the bell until it was too winded to ring. The monks in the crowd laughed, kindly.', no: 'He did not tire. Shaolin monks carry water up the mountain for ten years; you never stood a chance.', noFx: { health: -3, body: 1 },
    altT: 'Tell him your master’s worst joke', alt: 'He laughed so hard he stepped off the platform. The judges called it for you, reluctantly, and the Shaolin monks gave you a long look.', altFx: { fame: 1, charm: 1, rep: { orthodox: -1 } } },
  { key: 'wudang', if: { region: 'jingchu' }, title: 'Soft as water', text: 'Your opponent at the Wuchang contest is a Wudang Daoist your own age who stands so softly that you cannot work out where to hit him.',
    fame: 2, prize: 6, rollT: 'Refuse to push: give the Taiji nothing to turn', stat: 'insight', dc: 45, ok: 'You stood still. He stood still. After a very long time he smiled, stepped back and conceded. "You understand more than you know," he said. You did not.', okFx: { insight: 2 },
    no: 'You pushed. He turned your push into a gentle flight off the platform. It was the most polite defeat of your life.', noFx: { insight: 1 },
    altT: 'Ask him to teach you instead', alt: '"Later," he said, and conceded so you would both have time. You spent the evening on the river bank pushing hands, losing every time.', altFx: { insight: 2, fame: -1 } },
  { key: 'emei', if: { region: 'shu', season: [1, 2] }, title: 'Silent waters', text: 'At the Emei pilgrims’ fair, the bracket pairs you with an Emei swordswoman who has not smiled once all morning and does not intend to start.',
    fame: 3, prize: 7, rollT: 'Match her sword for sword', stat: 'body', dc: 35, ok: 'Silent Waters Sword, they call it, and it was. You broke the surface once, and once was enough. She bowed exactly as deeply as you had earned.', okFx: { rep: { orthodox: 1 } },
    no: 'Her blade tapped your wrist, your shoulder and your throat in the time it took you to blink. She did not smile then, either.', noFx: {},
    altT: 'Concede, and ask where she learned to stand like that', alt: 'She stared at you as if you were a new kind of insect, then told you. It was the most anyone in Emei has ever said to you.', altFx: { insight: 1, rep: { orthodox: 1 } } },
  { key: 'paeng', if: { region: 'hebei' }, title: 'A saber like a door', text: 'A Paeng nephew is your opponent at the Hebei autumn bouts. He carries a saber the size of a door and, judging by the dents, has used it as one.',
    foe: { name: 'a Paeng nephew with a saber like a door', kind: 'bandit', rel: 0.4 }, enter: 'He laughed, roared, and came at you with all five of the Five Tigers at once.', win: 'You let the saber go past one tiger too many and tapped his ear with the flat of your blade. He laughed so hard he dropped it.', lose: 'The saber came down like weather. You yielded under it, and he bought you a drink, which was worse for your head.',
    winFx: { flag: WIN, rep: { families: 2 } }, fame: 3, prize: 8,
    rollT: 'Out-wait him', stat: 'body', dc: 38, ok: 'You let him swing until the saber weighed more than his patience, then stepped in. The Paeng crowd booed you, then bought you drinks.', no: 'He did not get tired. Paeng men do not get tired; they get louder.', noFx: { health: -4 },
    altT: 'Challenge him to a drinking contest instead', alt: 'The judges allowed it, because the judges were also Paeng. You lost the bout and won the drinking. Nobody remembers the bout.', altFx: { health: -3, charm: 1, rep: { families: 1 } } },
  { key: 'dang', if: { loc: ['dangclan', 'chengdu'] }, title: 'Within reason', text: 'The Dang family’s spring contest allows hidden weapons "within reason". Your opponent, a Dang cousin with very clean gloves, has nine sleeves’ worth of reason.',
    fame: 3, prize: 10, rollT: 'Count the needles', stat: 'insight', dc: 40, ok: 'Three from the left sleeve, two from the collar, one from the shoe. When the seventh did not come, you knew he was empty, and walked in.', okFx: { rep: { families: 2 } },
    no: 'You counted six needles. There were seven. The seventh was coated with something that made your arm sing for a week.', noFx: { health: -8 },
    altT: 'Ask the judges what "within reason" means', alt: 'The judges conferred for an hour. Your opponent got bored and left. You won on a technicality, and the Dang family will not forget that you asked.', altFx: { fame: 1, rep: { families: -1 } } },
  { key: 'beggar', if: { loc: 'luoyang' }, title: 'Under the bridge', text: 'Under the Tianjin Bridge, the Beggars’ Sect runs an open bout every full moon. Your opponent is a Three-Pouch beggar with a bamboo staff and remarkable breath.',
    fame: 2, prize: 3, rollT: 'Keep his staff away from your ankles', stat: 'body', dc: 30, ok: 'The Dog-Beating Staff goes for the legs, always. You kept yours off the ground just long enough. The beggars passed a bowl for you; it came back with eleven coppers and a fish head.', okFx: { rep: { orthodox: 1 } },
    no: 'He tapped your ankle, then your other ankle, then your pride. A dog helped you up the bank.', noFx: { health: -2 },
    altT: 'Fill the bowl and buy him a meal instead', alt: 'He ate like a man who had won. You learned more about Luoyang from that meal than from a year of tavern rumours.', altFx: { wealth: -2, insight: 1, rep: { orthodox: 1 } } },
  { key: 'greenforest', if: { loc: 'taihang' }, title: 'Toll or bout', text: 'A Green Forest stronghold holds a bout for travellers: beat their champion and pass toll-free, lose and pay double. Their champion holds an axe in each hand and a third in his teeth.',
    foe: { name: 'the stronghold champion', kind: 'bandit', rel: 0.5 }, enter: 'He spat out the third axe and came at you with the other two.', win: 'He lay in the mud, laughing. "Toll-free," he agreed, "and a cup of our wine for the road." The wine was terrible. The respect was not.', lose: 'He knocked you down and sat on you until you agreed to pay double. Then he gave you a cup of wine, because rules are rules.',
    winFx: { flag: WIN, rep: { unorthodox: 4 } }, loseFx: { wealth: -6 }, fame: 2, prize: 0,
    rollT: 'Duck the axes and cut his belt', stat: 'body', dc: 45, ok: 'You cut his belt. Trousers, it turns out, matter more than axes. The stronghold roared with laughter and waved you through.', okFx: { rep: { unorthodox: 3 } }, no: 'You went for his belt, and he went for your collar, and he won.', noFx: { wealth: -6, health: -4 },
    altT: 'Pay the double toll and skip it', alt: 'You paid. The bandits looked disappointed, as if you had refused cake.', altFx: { wealth: -4 } },
  { key: 'redboots', if: { region: 'west' }, title: 'Red boots', text: 'At the Jade Gate caravan fair, your opponent is a quiet traveller in red-dyed boots whose palm leaves a faint smell of burnt iron wherever it touches.',
    fame: 2, prize: 12, rollT: 'Never let the palm touch you', stat: 'insight', dc: 45, ok: 'You kept clear of the palm, and when he overreached you threw him into a stack of saddles. He looked at you as if memorising you.', okFx: { flag: [WIN, 'tn.red_boots'], codex: 'secret.tn_red_boots' },
    no: 'The palm brushed your shoulder. It was barely a touch. Your arm was cold for a month.', noFx: { health: -6, flag: 'tn.red_boots' },
    altT: 'Ask the fair stewards who he is', alt: 'The stewards did not know and did not want to. One of them made a sign against evil when you described the boots.', altFx: { insight: 1, codex: { id: 'secret.tn_red_boots', cat: 'secrets', title: 'The man in red boots', text: 'At the Jade Gate caravan fair, a Cult scout in red-dyed boots fights in open bouts to measure the young of the Central Plains. His palm smells of burnt iron: the Heavenly Demon Palm.' } } },
  { key: 'moyong', if: { region: 'liaodong' }, title: 'Returned with interest', text: 'The Moyong winter contest is held on a frozen pond. Your opponent is a Moyong cousin who watches your first move with polite interest, and then does it back to you.',
    fame: 3, prize: 8, rollT: 'Never use the same move twice', stat: 'insight', dc: 50, ok: 'You fought the whole bout without repeating yourself once. By the end the cousin was simply watching, delighted, and forgot to defend.', okFx: { insight: 2, rep: { families: 2 } },
    no: 'You repeated yourself in the fourth exchange. He returned it, with interest, and you slid across the ice on your back.', noFx: { health: -3 },
    altT: 'Copy him copying you', alt: 'You returned his return. He returned that. It went on until the judges declared a draw out of sheer cold.', altFx: { charm: 1, fame: 1 } },
];
const tplBout = template('tn_bout', BOUT_ROWS, (r) => E('tn_bout', T, {
  if: { age: [14, 40], realm: '>=1', ...r.if }, once: false, cd: 3, art: 'tournament', title: r.title, text: r.text,
  choices: [
    ...(r.foe ? [C('Fight it out on the platform', O(r.enter, { combat: { foe: r.foe, context: T, lethal: 0, win: { text: r.win, fame: r.fame, wealth: r.prize, ...r.winFx }, lose: { text: r.lose, ...(r.loseFx || {}) } } }))] : []),
    R(r.rollT, r.stat, r.dc, O(r.ok, { fame: r.fame, wealth: r.prize, flag: WIN, ...(r.okFx || {}) }), O(r.no, r.noFx)),
    C(r.altT, O(r.alt, r.altFx)),
  ],
}));

// One open tournament per city, each with its own stakes, patrons and local trick.
const CITY_ROWS = [
  { key: 'changan', if: { loc: 'changan', season: [0] }, title: 'The Lantern Contest', text: 'On the fifteenth night of the new year, Chang’an builds a platform in the West Market, and old money pays young fighters to break each other’s noses under lanterns.',
    dc: 50, fame: 4, prize: 20, rep: { merchants: 2 }, win: 'You won the lantern bracket. An old silk merchant pressed a red envelope into your hand and asked whether you were married, on behalf of a niece.', lose: 'You went out in the second round under a lantern shaped like a carp. The carp seemed to be laughing.',
    alt: P('Fight in a patron’s colours for a fee', 0.5, O('A spice merchant paid you to wear his colours. You won two rounds in them, and he paid you a bonus and his card.', { wealth: 15, rep: { merchants: 2 } }), O('You lost in his colours. He paid the fee anyway, sourly. Chang’an keeps its contracts.', { wealth: 5 })),
    watch: 'You watched from a wine-house balcony, shelling chestnuts. Chang’an fights the way it does business: politely, and to the bone.' },
  { key: 'luoyang', if: { loc: 'luoyang', season: [0, 1] }, title: 'The Alliance Open', text: 'The Murim Alliance holds an open contest in Luoyang each spring to spot talent for the Assembly. Stewards with ledgers note down everyone who survives three rounds.',
    dc: 55, fame: 5, prize: 10, rep: { orthodox: 3 }, winFx: { flag: [WIN, 'tn.alliance_noted'] }, win: 'You survived three rounds, then two more. A steward wrote your name in the ledger, underlined it, and looked at you over his spectacles.', lose: 'You survived two rounds. The steward’s brush did not move.',
    alt: R('Talk your way into the ledger anyway', 'charm', 25, O('You told the steward about your master, your training and your prospects, at length. He wrote "promising" to make you stop.', { rep: { orthodox: 2 }, flag: 'tn.alliance_noted' }), O('He wrote something. You are fairly sure it was "rude".', { rep: { orthodox: -1 } })),
    watch: 'You watched the stewards more than the fighters. They noted down the winners. They also noted down who the winners’ friends were.', watchFx: { insight: 2 } },
  { key: 'kaifeng', if: { loc: 'kaifeng' }, title: 'The canal bridge', text: 'Kaifeng holds its contests on a bridge over the canal, so that the loser falls into the water and the gamblers can see clearly who lost.',
    dc: 45, fame: 3, prize: 15, rep: { unorthodox: 1 }, win: 'Five opponents went into the canal. You stayed on the bridge, dry, and the gamblers who had backed you carried you to a wine-house on their shoulders.', lose: 'You went into the canal. The canal in Kaifeng is not a clean canal.', loseFx: { health: -3 },
    alt: P('Bet on yourself first (10 taels)', 0.45, O('You bet on yourself at long odds and fought like a person with money at stake. The bookmaker paid you without meeting your eyes.', { wealth: 25, fame: 2 }), O('You bet on yourself and went into the canal in the second round, with your ten taels.', { wealth: -10, health: -2 }), { req: { wealth: '>=10' } }),
    watch: 'You watched from the bank and fished a drowning drunk out of the canal between bouts. He was not grateful.' },
  { key: 'wuchang', if: { loc: 'wuchang' }, title: 'Two boats in the river', text: 'At Wuchang, the contest is fought on two boats lashed together in mid-river, so that every fighter must also fight the Great River.',
    dc: 45, fame: 3, prize: 12, rep: { merchants: 1 }, win: 'The river took four of your opponents and spared you. The boatmen called you "dry-foot" for a week, which on the Great River is a compliment.', lose: 'The river took you in the second round, along with your opponent. You climbed out downstream, still fighting.',
    alt: R('Fight from the rigging', 'body', 45, O('You climbed the mast and dropped on your opponents like a kite on a chicken. The crowd on the banks screamed with delight.', { fame: 4, flag: WIN }), O('You climbed the mast, and the mast swayed, and the river had you.', { health: -5 })),
    watch: 'You watched from the bank, eating river crab. Half the fighters lost to the boat, not to each other.' },
  { key: 'chengdu', if: { loc: 'chengdu', season: [2] }, title: 'The pepper bracket', text: 'Chengdu’s autumn contest awards the winner a jar of the hottest peppers in Shu, and makes every fighter eat one before each bout.',
    dc: 45, fame: 3, prize: 6, rep: { orthodox: 1 }, win: 'You won the jar of peppers, through tears. The locals respected the tears more than the victory.', lose: 'You lost to the pepper first and the fighter second. The locals thought this was very funny.',
    alt: R('Eat three peppers to intimidate the field', 'health', 55, O('Two opponents withdrew rather than fight someone who could do that. You won your first two rounds without lifting a hand, and could not feel your face for a day.', { fame: 2, flag: WIN }), O('You wept for an hour and forfeited. Chengdu will tell the story for years.', { health: -5, charm: -1 })),
    watch: 'You watched, and ate pepper noodles, and cried for reasons that had nothing to do with the fighting.' },
  { key: 'hangzhou', if: { loc: 'hangzhou', season: [1] }, title: 'The Silk Cup', text: 'Hangzhou’s merchant guilds sponsor a contest beside West Lake every summer, mainly so their sons can lose to someone respectable.',
    dc: 45, fame: 3, prize: 25, rep: { merchants: 3 }, win: 'You beat three merchants’ sons and a guild guard and won the Silk Cup, which turned out to be a real silk cup. You sold it for twenty-five taels.', lose: 'You lost to a merchant’s son, which the guild had not planned and did not know how to celebrate.',
    alt: C('Sell iced plums to the crowd instead', O('You bought a barrel of plums and a block of ice and made more than the winner by noon.', { wealth: 12, careerUp: 1 })),
    watch: 'You watched beside the lake under a borrowed parasol. The fighting was mediocre. The lake was not.', watchFx: { sanity: 3 } },
  { key: 'capital', if: { loc: 'capital' }, title: 'The garrison bouts', text: 'The capital garrison holds bouts on the parade ground before Eastern Depot officers, who take notes on everyone who wins and everyone who loses badly.',
    dc: 60, fame: 3, prize: 15, rep: { court: 4 }, winFx: { flag: [WIN, 'tn.depot_noted'] }, win: 'You won the garrison bouts. A Depot officer wrote down your name, your birthplace and the names of your parents, smiling the whole time.', lose: 'You lost, not badly enough to be noted. Somewhere in the capital, that is a victory.',
    alt: R('Lose on purpose, unremarkably', 'insight', 35, O('You lost so unremarkably that the officers did not write anything down at all. In the capital, nobody knowing your name is a kind of wealth.', { sanity: 2 }), O('They noticed you were losing on purpose. That went in the file too.', { rep: { court: -3 } })),
    watch: 'You watched the officers watching the fighters. None of them watched the fighting.', watchFx: { insight: 1, rep: { court: 1 } } },
  { key: 'jadegate', if: { loc: 'jadegate' }, title: 'The camel ring', text: 'At Jade Gate, garrison soldiers, caravan guards and steppe riders wrestle in a ring of kneeling camels for a fat-tailed sheep.',
    dc: 40, fame: 2, prize: 0, rep: { court: 1 }, winFx: { flag: WIN, health: 8 }, win: 'You won the sheep, and the whole ring ate it with you that night around one fire, soldiers and riders together.', lose: 'A steppe rider threw you into a camel. The camel bit you. You ate some sheep anyway.',
    alt: R('Wrestle the steppe champion the steppe way', 'body', 50, O('Belt to belt, no strikes, no tricks. You threw him on the third try, and the riders cheered you in a language you do not speak.', { fame: 3, body: 1 }), O('Belt to belt, he threw you like a saddle. The riders were very kind about it.', { health: -6 })),
    watch: 'You watched from the wall in the wind and the dust. Out here, the contest is the only news for a hundred li.' },
  { key: 'namgung', if: { loc: 'namgung' }, title: 'Sword Viewing Day', text: 'Once a year the Namgung Estate opens its outer court to young swordsmen of Jiangnan, so that the family may watch them and feel superior.',
    dc: 55, fame: 4, prize: 10, rep: { families: 3 }, win: 'You won the outer-court contest. A Namgung elder told you that you had nearly understood the sword, which is the highest praise the Namgung give to anyone not called Namgung.', lose: 'You lost to a boy in Namgung blue, who was given a cup of tea for it. You were given directions to the gate.',
    alt: R('Catch the patriarch’s eye', 'charm', 30, O('You bowed to the gallery at exactly the right moment. The patriarch noticed. A servant brought you a cup of the family’s own tea.', { rep: { families: 3 }, fame: 1 }), O('You bowed to the gallery at exactly the wrong moment. The patriarch noticed that, too.', { rep: { families: -1 } })),
    watch: 'You watched the family watching. Pride is a martial art too, and the Namgung are masters.' },
  { key: 'paeng', if: { loc: 'paeng', season: [3] }, title: 'Tiger Day', text: 'Each winter the Paeng Fortress holds Tiger Day: anyone may challenge a Paeng son, and anyone who wins is fed until they cannot stand.',
    dc: 50, fame: 3, prize: 0, rep: { families: 2 }, winFx: { flag: WIN, health: 10 }, win: 'You beat a Paeng son and were fed until you could not stand, then fed again lying down. The Paeng patriarch laughed like a landslide.', lose: 'The Paeng son beat you, then fed you anyway, because on Tiger Day nobody leaves hungry.',
    alt: C('Skip the fight and just eat', O('Spectators get fed too, slightly less. You ate four bowls and made three friends and had no regrets.', { health: 5, charm: 1 })),
    watch: 'You watched from the long tables, chewing. Every loss was followed by a feast. It is a good way to raise sons.', watchFx: { sanity: 3 } },
  { key: 'county', if: { loc: 'willow', age: [12, 30] }, title: 'The county fair', text: 'The county fair below Mount Hua holds a fighting contest for anyone who can pay the entry copper. Mount Hua disciples are banned from entering, which is why it is popular.',
    dc: 30, fame: 2, prize: 4, rep: { orthodox: 1 }, win: 'You won the county fair, and a string of four taels, and the right to be insufferable in Willow Creek until next autumn.', lose: 'You lost to a pig farmer from the next valley, who wept with joy. It was hard to be bitter.',
    alt: R('Ask the Mount Hua disciples on duty to judge your form', 'charm', 20, O('A bored Mount Hua disciple watched your form and gave you two corrections and the name of a senior who takes promising strays.', { insight: 1, flag: 'tn.hua_watched' }), O('The Mount Hua disciple watched your form and said nothing, then went to buy a pancake.', { sanity: -1 })),
    watch: 'You watched with a pancake in each hand. The best fighter there was the pig farmer, and nobody will ever know.' },
];
const tplCity = template('tn_open', CITY_ROWS, (r) => E('tn_open', T, {
  if: { age: [14, 45], realm: '>=1', ...r.if }, once: false, cd: 3, art: 'tournament', title: r.title, text: r.text,
  choices: [
    R('Enter the bracket', 'power', r.dc, O(r.win, { fame: r.fame, wealth: r.prize, rep: r.rep, flag: WIN, ...(r.winFx || {}) }), O(r.lose, { fame: 1, ...(r.loseFx || {}) })),
    r.alt,
    C('Watch from the stands', O(r.watch, r.watchFx || { insight: 1 })),
  ],
}));

// Wagers: one per kind of contest, each with its own odds, stakes and tells.
const WAGER_ROWS = [
  { key: 'pit', if: { loc: 'kaifeng' }, stake: 10, title: 'Masks and silver', text: 'In the Ghost Market cistern, the Ox is fighting a skinny southerner tonight. The masks are betting heavily on the Ox, which is the safest bet and the worst odds.',
    favT: 'Bet on the Ox', favP: 0.6, favWin: 6, favOk: 'The Ox won in four blows, as expected. You won six taels, as expected.', favNo: 'The southerner danced the Ox off his feet. The masks went very quiet.',
    outT: 'Bet on the southerner', outP: 0.35, outWin: 25, outOk: 'The southerner danced until the Ox fell over his own feet. You collected twenty-five taels from a mask that hated you.', outNo: 'The Ox caught the southerner in the second exchange. It was over quickly, mercifully, and expensively.',
    readT: 'Watch them warm up first', stat: 'insight', dc: 40, readWin: 15, readOk: 'The Ox was favouring his right knee. You bet on the southerner and won.', readNo: 'You saw a limp that was not there. You bet on it anyway.',
    memT: 'Bet against the Ox. You know about his left shoulder.', mem: 'foe.tn_ox', memWin: 30, memOk: 'You told the southerner, quietly, to watch the Ox’s left shoulder. Then you bet everything you had. He watched, and you collected.',
    keep: 'You kept your money in your sleeve and your sleeve against your ribs. The Ghost Market has quick fingers.' },
  { key: 'bridge', if: { loc: 'luoyang' }, stake: 3, title: 'Coppers on the bridge', text: 'Beggar boys are fighting on the Tianjin Bridge for coppers, and grown men are betting on them, which says something about Luoyang.',
    favT: 'Bet on the bigger boy', favP: 0.6, favWin: 2, favOk: 'The bigger boy won. You won two taels and felt slightly worse than if you had lost.', favNo: 'The smaller boy bit him. Luoyang rules allow biting.',
    outT: 'Bet on the smaller boy', outP: 0.3, outWin: 9, outOk: 'The smaller boy won with a bite, a trip and a remarkable vocabulary. You gave him half your winnings. He took it without a word.', outNo: 'The smaller boy lost, shook it off, and asked you for a copper. You gave him one.',
    readT: 'Ask Dong-su which boy is hungrier', stat: 'charm', dc: 30, readWin: 6, readOk: 'Dong-su of the Beggars’ Sect pointed with his chin. "That one has not eaten since yesterday." You bet on hunger, and hunger won.', readNo: 'Dong-su pointed with his chin at the wrong boy, on purpose, and laughed all the way to the noodle stall.',
    keep: 'You bought both boys a meal instead. They ate it and resumed fighting, on full stomachs, for free.' },
  { key: 'dragonboat', if: { loc: 'hangzhou', season: [1] }, stake: 20, title: 'The dragon boats', text: 'At the Dragon Boat races on West Lake, each boat carries a fighter on the prow whose job is to knock the rival drummer into the water. The betting is ferocious.',
    favT: 'Bet on the Golden Abacus boat', favP: 0.55, favWin: 14, favOk: 'The guild boat won, as the guild had arranged. You were paid by the guild’s own bookmaker.', favNo: 'The guild’s prow fighter fell in first. The guild will be discussing this with him privately.',
    outT: 'Bet on the fishermen’s boat', outP: 0.25, outWin: 70, outOk: 'The fishermen’s boat won by a drumbeat. Their prow fighter was an old woman with a boathook. You were paid seventy taels and a fish.', outNo: 'The fishermen’s boat sank, cheerfully, halfway down the course.',
    readT: 'Study the prow fighters’ balance', stat: 'insight', dc: 45, readWin: 30, readOk: 'One prow fighter stood on his toes; one stood like a mooring post. You bet on the post, and the post won.', readNo: 'You studied their balance carefully. The lake did not care.',
    keep: 'You watched the races from the shore with a bowl of sticky rice in bamboo leaves. You won nothing and lost nothing and had the best day of the year.' },
  { key: 'armwrestle', if: { loc: 'changan' }, stake: 5, title: 'The wine-house table', text: 'In a Chang’an wine-house, a caravan guard and a temple carpenter have been arm-wrestling for an hour, and the whole room has money on it.',
    favT: 'Bet on the caravan guard', favP: 0.65, favWin: 3, favOk: 'The carpenter’s arm finally went down. You won three taels and a free cup.', favNo: 'The carpenter turned out to have been holding back for an hour. Everyone who bet on the guard went home lighter.',
    outT: 'Bet on the carpenter', outP: 0.3, outWin: 15, outOk: 'The carpenter turned out to have been holding back for an hour. You won fifteen taels and his gratitude.', outNo: 'The carpenter was not holding back. He was just very stubborn.',
    readT: 'Shake both their hands first', stat: 'body', dc: 40, readWin: 8, readOk: 'The carpenter’s grip nearly cracked your knuckles. You bet on him, and won.', readNo: 'Both grips felt like iron to you. You guessed, and guessed wrong.',
    keep: 'You drank your wine and watched the room bet. Chang’an loses more money politely than other cities lose rudely.' },
  { key: 'guards', if: { loc: 'capital' }, stake: 15, title: 'The Imperial archers', text: 'The Imperial Guard holds an archery match against the Eastern Depot every autumn. The betting is unofficial, enormous and politically delicate.',
    favT: 'Bet on the Imperial Guard', favP: 0.7, favWin: 6, favOk: 'The Guard won. Commander Han Gyeong’s archers always win. You won a little, and nobody important noticed.', favNo: 'The Guard lost, which caused a small scandal and a large loss.',
    outT: 'Bet on the Eastern Depot', outP: 0.2, outWin: 60, outOk: 'The Depot won, to everyone’s astonishment. You were paid sixty taels by a bookmaker who looked over his shoulder the whole time.', outNo: 'The Depot lost. Somewhere, an officer noted who had bet on them.',
    readT: 'Watch the wind on the banners', stat: 'insight', dc: 50, readWin: 20, readOk: 'The wind was gusting from the Depot’s side. You bet on the Guard and won, and learned that weather has politics too.', readNo: 'You watched the wind. The wind changed its mind.',
    keep: 'You kept your money. In the capital, who you bet on is a kind of signature.' },
  { key: 'pepper', if: { loc: 'chengdu' }, stake: 4, title: 'Peppers and pride', text: 'In a Chengdu market, two cooks are competing to eat the hottest peppers in Shu, one per round, while fighting with chopsticks for the last dumpling.',
    favT: 'Bet on the cook from Mount Emei', favP: 0.5, favWin: 4, favOk: 'The Emei cook ate nine peppers without blinking. A nun, it emerged.', favNo: 'The Emei cook fainted at seven. The other cook took the dumpling and wept.',
    outT: 'Bet on the old woman watching', outP: 0.3, outWin: 12, outOk: 'At the eighth round, an old woman in the crowd pushed both cooks aside, ate a pepper, and took the dumpling. You had bet on exactly this, and the bookmaker paid.', outNo: 'The old woman did not intervene. She only came for the show.',
    readT: 'Watch who sweats first', stat: 'insight', dc: 30, readWin: 8, readOk: 'The bigger cook was sweating at the third pepper. You bet on the small one, and won.', readNo: 'Everyone in Chengdu sweats. It tells you nothing.',
    keep: 'You bought a pepper of your own, ate it, and spent the rest of the contest in tears. A fair price for the experience.' },
  { key: 'swim', if: { loc: 'wuchang', season: [1] }, stake: 8, title: 'Across the Great River', text: 'Every summer the river fighters of Wuchang race across the Great River and back, wrestling in the current. The boatmen are taking bets.',
    favT: 'Bet on the boatman’s son', favP: 0.55, favWin: 7, favOk: 'The boatman’s son came back first, holding his rival’s trousers aloft. You won seven taels.', favNo: 'A Water Fortress man came back first. The boatmen grew quiet.',
    outT: 'Bet on the Water Fortress man', outP: 0.4, outWin: 14, outOk: 'The Water Fortress man came back first and saluted the boatmen with a gesture they did not appreciate. You collected.', outNo: 'The Water Fortress man got cramp and was hauled out by the people he insulted.',
    readT: 'Watch the current, not the swimmers', stat: 'insight', dc: 40, readWin: 12, readOk: 'The current favoured the eastern lane today. You bet on whoever drew it, and won.', readNo: 'The current changed. Rivers are like that.',
    keep: 'You watched from the bank as the swimmers came back half-drowned and triumphant. Nobody bet on the river, and the river won.' },
  { key: 'axes', if: { loc: 'taihang' }, stake: 6, title: 'The axe throw', text: 'At a Green Forest stronghold, the bandits are throwing axes at a painted magistrate on a barn door. Guests are welcome to bet; guests are not welcome to win too much.',
    favT: 'Bet on the stronghold captain', favP: 0.6, favWin: 5, favOk: 'The captain split the magistrate’s painted hat. You won five taels and a hearty slap on the back.', favNo: 'The captain missed, blamed the wind, and looked at you as if you were the wind.',
    outT: 'Bet on the new recruit', outP: 0.3, outWin: 18, outOk: 'The new recruit hit the painted magistrate right between the eyes. The stronghold cheered. The captain did not.', outNo: 'The new recruit hit the barn, the fence, and nearly a goat.',
    readT: 'Heft the axes first', stat: 'body', dc: 35, readWin: 10, readOk: 'One axe was badly balanced. You noted who drew it, and bet against him.', readNo: 'You hefted the axes. A bandit watched you do it, and did not like it.',
    keep: 'You declined to bet with bandits, which the bandits took as a compliment to their honesty and offered you more wine.' },
  { key: 'horses', if: { loc: 'jadegate' }, stake: 12, title: 'The saber race', text: 'Outside Jade Gate, steppe riders and garrison cavalry race horses through a line of hanging gourds, cutting each one with a saber at a gallop.',
    favT: 'Bet on the garrison captain', favP: 0.5, favWin: 12, favOk: 'The captain cut nine gourds of ten. The garrison roared. You were paid in silver and bad wine.', favNo: 'The captain’s horse refused the third gourd. Horses have opinions.',
    outT: 'Bet on the steppe girl', outP: 0.45, outWin: 15, outOk: 'The steppe girl cut all ten gourds and the rope they hung from. You won fifteen taels and a scornful look.', outNo: 'The steppe girl cut ten gourds and was disqualified for being a girl. Nobody had told her the rule. Nobody had told you, either.',
    readT: 'Look at the horses, not the riders', stat: 'insight', dc: 35, readWin: 14, readOk: 'One horse had been watered too recently. You bet against it, and won.', readNo: 'All the horses looked like horses to you.',
    keep: 'You watched the gourds burst one by one against the evening sky, and kept your silver for the road west.' },
  { key: 'logs', if: { loc: 'dongting' }, stake: 10, title: 'Floating logs', text: 'Water Fortress men are fighting on floating logs in the reeds of Lake Dongting, and the betting boats are crowded together like ducks.',
    favT: 'Bet on the Fortress champion', favP: 0.65, favWin: 5, favOk: 'The Fortress champion stayed on his log as if nailed to it. You won five taels from a boat that sank shortly afterwards.', favNo: 'The champion slipped. The lake is fair, if nothing else is.',
    outT: 'Bet on the fisherman’s daughter', outP: 0.3, outWin: 22, outOk: 'The fisherman’s daughter spun her log until the champion fell off his. The Fortress men laughed louder than anyone; they like a good upset.', outNo: 'The fisherman’s daughter went into the reeds, laughing, and came up with a fish.',
    readT: 'Watch their feet on the wet bark', stat: 'insight', dc: 45, readWin: 15, readOk: 'One fighter’s toes gripped the bark; one fighter’s heels did. You bet on toes, and toes won.', readNo: 'Bark is bark. Feet are feet. You lost money learning this.',
    keep: 'You watched from a reed boat and let the old fisherman beside you do your betting for you, in his head. He was right every time.' },
];
const tplWager = template('tn_wager', WAGER_ROWS, (r) => {
  const req = { wealth: `>=${r.stake}` };
  return E('tn_wager', T, {
    if: { age: [14, 80], ...r.if }, once: false, cd: 3, title: r.title, text: r.text,
    choices: [
      P(`${r.favT} (${r.stake} taels)`, r.favP, O(r.favOk, { wealth: r.favWin }), O(r.favNo, { wealth: -r.stake }), { req }),
      P(`${r.outT} (${r.stake} taels)`, r.outP, O(r.outOk, { wealth: r.outWin }), O(r.outNo, { wealth: -r.stake }), { req }),
      R(r.readT, r.stat, r.dc, O(r.readOk, { wealth: r.readWin, insight: 1 }), O(r.readNo, { wealth: -r.stake }), { req }),
      ...(r.mem ? [M(r.memT, r.mem, O(r.memOk, { wealth: r.memWin }), { req })] : []),
      C('Keep your money', O(r.keep)),
    ],
  });
});

// Lightness-skill races, one per landscape, with a shortcut for anyone who knows the right steps.
const RACE_ROWS = [
  { key: 'roofs', if: { loc: 'kaifeng' }, title: 'Over the roofs of Kaifeng', text: 'Young martial artists race at night across the roofs of Kaifeng, from the Drum Tower to the Iron Pagoda. The city has stopped complaining; it now sells tickets.',
    stat: 'body', dc: 45, fame: 3, okFx: { wealth: 10 }, ok: 'You ran the ridgelines like a cat with somewhere to be and touched the Iron Pagoda first. The roof-watchers below threw coins.', no: 'You went through a roof into a family’s dinner. They were very understanding about it, for a price.', noFx: { health: -5, wealth: -3 },
    man: 'uno_ghost_step', manT: 'Run it with the Ghost Shadow Step', manOk: 'You ran like a rumour: nobody saw you pass, only that you had passed. The Ghost Market brokers took note of who could run like that.', manFx: { rep: { unorthodox: 2 } },
    altT: 'Bet on the race from the street', alt: 'You bet on a girl in black, who won by a whole roof. The ticket-seller paid you with ill grace.', altFx: { wealth: 4 } },
  { key: 'ladder', if: { loc: 'wudang' }, title: 'The Ladder to the Clouds', text: 'Wudang’s younger disciples race up the stone stairs to the Golden Summit without touching the handrails, and visitors may join them if they can keep up.',
    stat: 'body', dc: 50, fame: 2, okFx: { rep: { orthodox: 2 } }, ok: 'You reached the Golden Summit third, behind two Wudang disciples who had done it a thousand times. They bowed to you, breathing easily. You could not bow back. You could not breathe.', no: 'You touched the handrail on the nine hundredth step, and then sat on it. The disciples waved as they passed.', noFx: { health: -2 },
    man: 'wu_ladder', manT: 'Climb with the Ladder to the Clouds', manOk: 'You climbed with Wudang’s own art and arrived at the summit first, which made the Wudang disciples very quiet and the old Daoist at the top very pleased.', manFx: { rep: { orthodox: 3 } },
    altT: 'Walk up slowly and admire the view', alt: 'You took all day. The peaks bowed toward the summit in the evening light, and you understood why someone built a sect here.', altFx: { sanity: 4, insight: 1 } },
  { key: 'snow', if: { loc: 'kunlun' }, title: 'No tracks in the snow', text: 'Kunlun’s disciples have a game: race across a field of fresh snow and arrive with the fewest footprints behind you. The winners leave none.',
    stat: 'qi', dc: 55, fame: 3, okFx: { insight: 1 }, ok: 'You crossed the field leaving six prints, barely dents. A Kunlun disciple looked at them for a long time, then at you.', no: 'You crossed the field leaving a trench. The Kunlun disciples were too polite to laugh in front of you.', noFx: { health: -3 },
    man: 'kun_cloud_step', manT: 'Cross with the Cloud Dragon steps', manOk: 'You crossed the field and left nothing behind but wind. The Kunlun disciples bowed to you as one of their own.', manFx: { rep: { orthodox: 2 } },
    altT: 'Build a snowman instead', alt: 'You built a snowman in the shape of the Kunlun Sect Leader. The disciples were scandalised and, secretly, delighted.', altFx: { charm: 1, sanity: 3 } },
  { key: 'steps', if: { loc: 'emei' }, title: 'The cup on the stairs', text: 'At Emei, pilgrims and disciples race up the long stairs to the Golden Summit carrying a full cup of tea. Spill a drop and you go back to the bottom.',
    stat: 'body', dc: 40, fame: 2, okFx: { sanity: 2 }, ok: 'You reached the summit with a full cup and handed it to the waiting nun, who drank it, cold, and nodded once.', no: 'You spilled on the third flight, and the seventh, and the twelfth. You know those stairs very well now.', noFx: { body: 1 },
    man: 'step_basic', manT: 'Skim the stairs with the Grass-Skimming Step', manOk: 'Your feet barely touched the stone. The tea did not ripple. The nun at the top raised an eyebrow, which at Emei is a standing ovation.', manFx: { rep: { orthodox: 1 } },
    altT: 'Carry a pilgrim’s cup for her instead', alt: 'An old pilgrim had been trying for six years. You carried her cup for her, and she reached the summit for the first time and wept.', altFx: { sanity: 5, fame: 1 } },
  { key: 'reeds', if: { loc: 'dongting' }, title: 'Across the reeds', text: 'Water Fortress youths race across the reed beds of Lake Dongting, running on the reed tops where a sparrow would sink. Most of them end up swimming.',
    stat: 'body', dc: 50, fame: 3, okFx: { rep: { unorthodox: 2 } }, ok: 'You ran across a hundred paces of reeds and arrived dry. The Water Fortress youths cheered you, then pushed you in, out of respect.', no: 'You ran six steps and swam the rest. The lake was warm, at least, and full of opinions.', noFx: { health: -3 },
    man: 'beg_drunk_step', manT: 'Stagger across with the Drunken Immortal Steps', manOk: 'You lurched and swayed and never once sank. The Water Fortress youths had never seen anything like it, and were not sure if you were drunk. Neither were you.', manFx: { rep: { unorthodox: 3 } },
    altT: 'Row alongside and fish people out', alt: 'You fished nine racers out of the reeds. The Water Fortress remembers who helps.', altFx: { rep: { unorthodox: 2 }, charm: 1 } },
  { key: 'planks', if: { loc: ['mounthua', 'willow'] }, title: 'The plank road', text: 'On the cliff face of Mount Hua there is a road of planks pegged into the rock, a thousand feet above nothing. Young fools race along it every autumn.',
    stat: 'body', dc: 45, fame: 3, okFx: { sanity: -1 }, ok: 'You ran the plank road and did not look down once, which is the whole secret. You won, and your hands did not stop shaking until dinner.', no: 'A plank shifted. You caught a chain, and a ledge caught you. You lay there for some time, thinking about your life.', noFx: { health: -8 },
    man: 'hua_fragrance_step', manT: 'Run it with the Dark Fragrance Steps', manOk: 'You ran it like a plum petal on the wind, and the old Mount Hua elder watching from the far end took his pipe out of his mouth for the first time in years.', manFx: { rep: { orthodox: 2 } },
    altT: 'Refuse, sensibly', alt: 'You refused. A Mount Hua disciple who had run it eleven times told you it was the most intelligent decision anyone had made all day.', altFx: { insight: 1 } },
  { key: 'bamboo', if: { loc: ['qingcheng', 'chengdu'] }, title: 'The bamboo tops', text: 'In the bamboo forests below Mount Qingcheng, young swordsmen race from stalk-top to stalk-top. The stalks bend. The swordsmen, ideally, do not.',
    stat: 'body', dc: 45, fame: 3, okFx: { rep: { orthodox: 1 } }, ok: 'You rode the bending bamboo like a boat on waves and arrived first. Below you, the pandas of the forest did not look up.', no: 'The bamboo bent, and kept bending, and set you down very gently in a stream.', noFx: { health: -2 },
    man: 'dian_cloud_step', manT: 'Tread the bamboo with the Cloud-Treading Step', manOk: 'Diancang’s Cloud-Treading Step is meant for exactly this. The Qingcheng racers recognised it, and were irritated, and lost.', manFx: { rep: { orthodox: 1 }, flag: 'tn.qingcheng_grudge' },
    altT: 'Cut bamboo shoots for dinner instead', alt: 'You cut a basket of shoots and cooked them for the racers afterwards. Qingcheng swordsmen, it turns out, are cheerful when fed.', altFx: { charm: 1 } },
  { key: 'lotus', if: { loc: 'hangzhou', season: [1] }, title: 'The lotus leaves', text: 'Hangzhou’s young gentlemen race across West Lake on the lotus leaves, for a wager and the admiration of the boats. Most of them sink gracefully.',
    stat: 'insight', dc: 45, fame: 3, okFx: { charm: 1 }, ok: 'You chose only the broadest leaves, the ones with frogs on them, and crossed dry. A lady on a painted boat threw you her fan.', no: 'You chose a leaf with a frog on it. It was a very small frog and a very small leaf.', noFx: { health: -2, charm: -1 },
    man: 'lost_reversed_step', manT: 'Cross with the Reversed Meridian Step', manOk: 'Your qi ran backwards and so, it seemed, did gravity. You crossed the lake on leaves that should not have held a sparrow. Nobody on the boats spoke for some time.', manFx: { fame: 3 },
    altT: 'Hire a boat and follow the racers', alt: 'You rowed after the racers and pulled the sinking ones aboard. By the end you had a boat full of wet young gentlemen and a great many invitations.', altFx: { charm: 2 } },
  { key: 'cliffs', if: { loc: 'taihang' }, title: 'The bandits’ cliff', text: 'Green Forest bandits race down a cliff face to the road below, as a game and as practice for ambushes. They are delighted to have a guest.',
    stat: 'body', dc: 50, fame: 2, okFx: { rep: { unorthodox: 3 } }, ok: 'You reached the road first and were standing there, arms folded, when the bandits arrived. They made you an honorary member of the stronghold on the spot.', no: 'You reached the road second, by the fastest possible route, which is falling.', noFx: { health: -8 },
    man: 'cult_shadow_step', manT: 'Descend with the Shadow Demon Step', manOk: 'You went down the cliff like a shadow at sunset. When you reached the road, the bandits were not cheering. Some of them knew a Cult art when they saw one.', manFx: { rep: { unorthodox: 1 }, infamy: 2 },
    altT: 'Take the goat path down', alt: 'You took the goat path down. A goat passed you. The bandits loved it.', altFx: { charm: 1 } },
  { key: 'dunes', if: { loc: 'jadegate' }, title: 'The singing dune', text: 'West of Jade Gate is a dune that sings when you run on it. The caravan boys race to the top at dawn; the winner makes it sing the longest.',
    stat: 'body', dc: 40, fame: 2, okFx: { sanity: 3 }, ok: 'You reached the crest first and the whole dune hummed under you like a great bell. The caravan boys sat in the sand and listened until it stopped.', no: 'Every step you took up the dune slid two steps back. You arrived last, and the dune sang mockingly.', noFx: { body: 1 },
    man: 'kun_cloud_step', manT: 'Run with the Cloud Dragon steps', manOk: 'You barely touched the sand, and the dune barely sang, a single high note like a struck cup. The caravan boys had never heard it do that.', manFx: { insight: 1 },
    altT: 'Sit at the bottom and listen', alt: 'You sat at the bottom while the boys ran. The dune sang, and the sun came up, and nobody needed to win anything.', altFx: { sanity: 5 } },
];
const tplRace = template('tn_race', RACE_ROWS, (r) => E('tn_race', T, {
  if: { age: [12, 40], realm: '>=1', ...r.if }, once: false, cd: 4, title: r.title, text: r.text,
  choices: [
    R('Race', r.stat, r.dc, O(r.ok, { fame: r.fame, flag: WIN, ...r.okFx }), O(r.no, r.noFx)),
    C(r.manT, O(r.manOk, { fame: r.fame + 1, flag: WIN, mastery: { [r.man]: 5 }, ...r.manFx }), { show: { manual: r.man } }),
    C(r.altT, O(r.alt, r.altFx)),
  ],
}));

// Drinking contests: every province has its liquor and its champions.
const DRINK_ROWS = [
  { key: 'willow', if: { loc: 'willow', season: [0] }, title: 'The elders’ jar', text: 'At New Year, the old men of Willow Creek hold a drinking contest with the rice wine they have been brewing since autumn. You are finally old enough to be humiliated by them.',
    dc: 45, ok: 'You out-drank three grandfathers and the village chief, who fell asleep mid-sentence. The elders treat you as an adult now, which mainly means you get blamed for things.', okFx: { fame: 1, charm: 1 }, no: 'A grandfather with four teeth drank you under the table and then carried you home, singing.', noFx: { health: -3 },
    qiRealm: 2, qiP: 0.7, qiOk: 'You sweated the wine out through your palms and won easily. Grandfather Kim watched the puddle spread under your hands and said nothing. He knew a cheat when he saw one, and he approved.', qiOkFx: { fame: 1 }, qiNo: 'The puddle under your hands steamed. The elders were outraged and impressed, in that order.', qiNoFx: { charm: -1 },
    alt: C('Pour for the elders instead', O('You poured all night and listened to stories about your grandparents you had never heard. It was the best New Year you can remember.', { sanity: 5, insight: 1 })) },
  { key: 'beggar_chief', if: { loc: 'luoyang', alive: 'beggar_chief', year: [18, 33] }, title: 'Cup for cup', text: 'Hong Chil, the Nine-Fingered Beggar, is drinking under the bridge and challenging passers-by. Match him cup for cup, he says, and he will answer one question truthfully.',
    dc: 80, ok: 'Somewhere past the twentieth cup, Hong Chil set his bowl down and looked at you with eyes that were not drunk at all. "Ask," he said. You asked who on Mount Hua owed money to the Ghost Market. He told you.', okFx: { rel: { '@beggar_chief': { res: 15, aff: 10 } }, codex: 'secret.gu_debts' }, no: 'You fell over at cup eleven. Hong Chil finished your bowl, ate your chicken, and left a note on your chest: "Ask me again in ten years."', noFx: { health: -4, rel: { '@beggar_chief': { aff: 5 } } },
    qiRealm: 3, qiP: 0.4, qiOk: 'You forced the wine out through your fingertips. Hong Chil forced his out through his toes, and laughed. "Cheat with me, then!" You both cheated until dawn, and he answered your question anyway.', qiOkFx: { rel: { '@beggar_chief': { aff: 15 } }, codex: 'secret.gu_debts' }, qiNo: 'Hong Chil flicked a finger at your wrist and your qi stopped dead. "No cheating," he said, and refilled your bowl. You did not last long after that.', qiNoFx: { health: -5, rel: { '@beggar_chief': { res: 3 } } },
    alt: C('Bring him a roast chicken and just talk', O('He ate the whole chicken, licked all nine fingers, and told you three things about Luoyang that nobody else knows. None of them was the thing you wanted.', { wealth: -2, insight: 2, rel: { '@beggar_chief': { aff: 10 } } })) },
  { key: 'paeng', if: { loc: 'paeng' }, title: 'Sorghum and saber', text: 'At the Paeng Fortress, the drinking contest uses sorghum spirit strong enough to strip lacquer. Between cups, each drinker must lift a saber over their head and say a toast.',
    dc: 65, ok: 'You lifted the saber twenty times and gave twenty toasts, the last one in verse. The Paeng patriarch named you a friend of the family, and nobody argued.', okFx: { rep: { families: 4 }, fame: 2 }, no: 'You dropped the saber on the ninth cup. It missed your foot. That was the only good news.', noFx: { health: -5 },
    qiRealm: 2, qiP: 0.5, qiOk: 'You sweated it out through your fingertips while toasting with the other hand. The Paeng saw nothing, which with Paeng is not difficult.', qiOkFx: { rep: { families: 2 } }, qiNo: 'Steam rose from your hand while you toasted. A Paeng elder pointed and roared with laughter. "A qi drinker! Give him the bigger cup!"', qiNoFx: { health: -3, rep: { families: 1 } },
    alt: C('Arm-wrestle the drinkers instead', O('You arm-wrestled every drunk Paeng in the hall, one by one, and lost to all of them, and became extremely popular.', { charm: 1, rep: { families: 2 } })) },
  { key: 'yellowwine', if: { loc: 'hangzhou' }, title: 'Yellow wine and verse', text: 'In a Hangzhou pavilion, scholars drink warm yellow wine and each cup must be paid for with a line of poetry. The last one still rhyming wins.',
    dc: 45, ok: 'You were still rhyming at cup twenty. The scholars were still listening. One of them wrote your lines on the pavilion wall, where they are, presumably, still.', okFx: { fame: 1, insight: 1 }, no: 'At cup nine your verse stopped rhyming. At cup eleven it stopped making sense. At cup twelve it became, briefly, genius, and nobody wrote it down.', noFx: { health: -2 },
    qiRealm: 2, qiP: 0.6, qiOk: 'Sober as a stone, you rhymed until the scholars wept. Cheating at poetry is still poetry.', qiOkFx: { fame: 1, charm: 1 }, qiNo: 'Sober as a stone, you discovered you could not write poetry sober either.', qiNoFx: { charm: -1 },
    alt: R('Out-rhyme them without drinking at all', 'insight', 45, O('You rhymed with tea. The scholars were offended, then fascinated, then drunk.', { insight: 2, fame: 1 }), O('Without wine, your verse was dry as a ledger. The scholars told you so.', { charm: -1 })) },
  { key: 'snakewine', if: { loc: 'kaifeng' }, title: 'Snake wine', text: 'In the Ghost Market, a stall-keeper offers a free jar to anyone who can drink a cup of his snake wine for every year of the snake coiled in the bottom. The snake is old.',
    dc: 55, ok: 'You drank thirty cups for thirty years of snake and won the jar. You also saw things that night that you will never describe to anyone.', okFx: { wealth: 6, sanity: -2 }, no: 'At cup twelve the snake looked at you. At cup thirteen it spoke. You do not remember what it said, but you have a feeling you agreed to something.', noFx: { sanity: -4, health: -3 },
    qiRealm: 3, qiP: 0.55, qiOk: 'You pushed the venom-wine out of your meridians and won. The stall-keeper looked at the puddle and offered you a job.', qiOkFx: { wealth: 6, infamy: 1 }, qiNo: 'The snake wine did not want to leave. It stayed, and so did the visions.', qiNoFx: { sanity: -5 },
    alt: C('Buy a cup and walk on', O('One cup of snake wine was enough. For an hour the lanterns of the Ghost Market had faces, and some of them were people you had lost.', { wealth: -1, sanity: -1, insight: 1 })) },
  { key: 'baijiu', if: { loc: 'chengdu' }, title: 'Fire and pepper', text: 'A Chengdu tavern holds a contest of white spirit with a pepper floating in every cup. The champion is a teahouse grandmother who has not lost in eleven years.',
    dc: 60, ok: 'On the thirtieth cup the grandmother set hers down, looked at you with new respect, and told you that you could marry her granddaughter. You declined, very politely.', okFx: { fame: 2, health: -2 }, no: 'The grandmother finished her thirtieth cup and then yours. Then she went back to work at the teahouse.', noFx: { health: -6 },
    qiRealm: 2, qiP: 0.5, qiOk: 'You sweated out the spirit, but not the pepper. You won with your face streaming. The grandmother thought it was emotion, and patted your cheek.', qiOkFx: { fame: 1 }, qiNo: 'You forced the spirit out and the pepper with it, through a sneeze. The tavern will be talking about that sneeze for years.', qiNoFx: { charm: -2 },
    alt: C('Bet on the grandmother', O('You bet on the grandmother. Everyone bet on the grandmother. The bookmaker went home in tears.', { wealth: 2 })) },
  { key: 'koumiss', if: { loc: 'jadegate' }, title: 'Mare’s milk', text: 'Steppe traders at Jade Gate challenge the garrison to drink fermented mare’s milk from a horn, one horn per verse of a song that has, apparently, no end.',
    dc: 50, ok: 'You drank to the forty-first verse. The steppe traders adopted you into a clan whose name you could not pronounce, and gave you a horn of your own.', okFx: { fame: 2, wealth: 5 }, no: 'You drank to the twelfth verse and slept beside the horses. The horses did not mind.', noFx: { health: -3 },
    qiRealm: 2, qiP: 0.6, qiOk: 'You sweated it out. The steppe traders did not know what you were doing but thought it was a very good trick, and paid you to do it again.', qiOkFx: { wealth: 8 }, qiNo: 'Mare’s milk does not leave the body politely. You learned this in front of a large audience.', qiNoFx: { charm: -2 },
    alt: C('Learn the song instead', O('You learned nine verses of the endless song. The traders sang them with you around the fire. You still remember them, and sometimes, on long roads, you sing.', { sanity: 4, charm: 1 })) },
  { key: 'banquet', if: { loc: 'capital', age: [18, 80] }, title: 'The eunuch’s banquet', text: 'A senior eunuch is holding a banquet, with a drinking game in which each forfeit is a confession. Half the guests are Eastern Depot officers, and all of them are listening.',
    dc: 50, ok: 'You out-drank the table without confessing anything. The eunuch toasted you. "A guest who keeps secrets," he said. "How rare."', okFx: { rep: { court: 4 } }, no: 'You lost the game at cup eight and confessed something about the Director’s hat. Everyone laughed. Somebody wrote it down.', noFx: { rep: { court: -6 } },
    qiRealm: 2, qiP: 0.45, qiOk: 'You stayed sober and let everyone else confess. You left with your secrets and several of theirs.', qiOkFx: { rep: { court: 2 }, insight: 2 }, qiNo: 'A Depot officer noticed the damp tablecloth under your hand. "Interesting," he said, and nothing else, which was worse.', qiNoFx: { rep: { court: -3 } },
    alt: C('Plead a weak stomach and leave early', O('You left early. Some of the guests you left behind were arrested in the spring. Your stomach, it seems, is wise.', { sanity: 2 })) },
  { key: 'icewine', if: { loc: 'moyong' }, title: 'Ice wine', text: 'At the Moyong winter gathering, the family serves wine with ice from the northern sea in it, and expects guests to keep pace with their courtesy, which is cold and endless.',
    dc: 50, ok: 'You drank cup for cup with a Moyong elder until he smiled, very slightly, which the family has not seen in some years.', okFx: { rep: { families: 3 } }, no: 'The cold went to your head and the wine to your knees. A Moyong servant guided you to a chair with flawless, freezing politeness.', noFx: { health: -2, charm: -1 },
    qiRealm: 3, qiP: 0.5, qiOk: 'You warmed the wine in your meridians and breathed it out as mist. The Moyong elder watched the mist, and returned your technique, and you both breathed mist at each other until dawn.', qiOkFx: { rep: { families: 3 }, insight: 1 }, qiNo: 'You tried to warm the wine with qi. It froze in your channels instead. You spent a week feeling like a well in winter.', qiNoFx: { health: -6 },
    alt: R('Compliment the ice instead of the wine', 'charm', 35, O('You praised the ice. The Moyong were delighted; nobody has ever noticed the ice. It is cut by the patriarch himself.', { rep: { families: 4 } }), O('You praised the ice. They looked at you as if you had praised the floor.', {})) },
  { key: 'tea', if: { loc: 'songshan' }, title: 'Forty cups of tea', text: 'Shaolin’s young monks are not allowed wine, so they hold a contest of bitter tea instead: forty cups, each stronger, and the last monk still sitting still wins.',
    dc: 40, ok: 'You sat perfectly still through forty cups. Your heart was racing like a horse but your face was a temple. The monks bowed to you.', okFx: { rep: { orthodox: 2 }, insight: 1 }, no: 'At cup twenty-two you began to vibrate. At cup twenty-five you ran three times around the courtyard. The monks were very kind.', noFx: { sanity: -2 },
    qiRealm: 2, qiP: 0.65, qiOk: 'You calmed your heart with your breath and sat like a stone. An old monk sweeping nearby stopped sweeping, briefly.', qiOkFx: { rep: { orthodox: 1 }, qi: 8 }, qiNo: 'You tried to calm your heart with qi, and your qi was as jittery as your heart.', qiNoFx: { sanity: -1 },
    alt: C('Pour for the monks instead', O('You poured for the monks until they were vibrating and you were not. They thanked you as if you had done them a service. You were not sure you had.', { charm: 1, rep: { orthodox: 1 } })) },
];
const tplDrink = template('tn_drink', DRINK_ROWS, (r) => E('tn_drink', T, {
  if: { age: [16, 80], ...r.if }, once: false, cd: 4, art: 'inn', title: r.title, text: r.text,
  choices: [
    R('Drink', 'health', r.dc, O(r.ok, r.okFx), O(r.no, r.noFx)),
    P('Sweat the wine out through your fingertips', r.qiP, O(r.qiOk, r.qiOkFx), O(r.qiNo, r.qiNoFx), { req: { realm: `>=${r.qiRealm}` } }),
    r.alt,
  ],
}));

// Archery: every place shoots at something different, and Dang-trained cheats throw needles instead.
const BOW_ROWS = [
  { key: 'pheasant', if: { loc: 'willow', age: [10, 30], season: [2] }, title: 'The straw pheasant', text: 'At the harvest fair, the hunters of Willow Creek set up a straw pheasant on a pole at sixty paces. Hit it and you win a jar of the chief’s rice wine.',
    stat: 'body', dc: 25, ok: 'Your arrow went through the pheasant’s straw neck. The hunters cheered. The chief handed over the jar, slowly.', okFx: { item: { rice_wine: 1 }, fame: 1 }, no: 'Your arrow went into the chief’s woodpile. He was not pleased. The woodpile was not pleased.', noFx: {},
    needle: 'emei_needles', needleOk: 'You flicked a needle and the straw pheasant’s head fell off. The hunters argued about it until dark.', needleFx: { fame: 1, charm: -1 },
    alt: C('Make arrows for the other children', O('You fletched arrows all day with feathers from the chief’s geese. The geese have not forgiven you.', { insight: 1, charm: 1 })) },
  { key: 'coin', if: { loc: 'capital', age: [16, 40] }, title: 'Through the coin', text: 'The Ministry of War’s archery trial: shoot an arrow through the square hole of a copper coin swinging on a thread at fifty paces. Officers with brushes stand ready.',
    stat: 'insight', dc: 50, ok: 'Your arrow went through the hole and pinned the coin to the target. The Ministry awarded you a sword with its seal on the guard.', okFx: { item: { fine_sword: 1 }, rep: { court: 5 }, fame: 2 }, no: 'You hit the thread. The coin fell. The officers wrote down that you had hit the thread, which is both a success and a failure.', noFx: { rep: { court: 1 } },
    needle: 'uno_silent_needle', needleOk: 'You threw a Silent Death Needle through the coin’s hole. Then you saw the officers’ faces, and realised what you had just shown them.', needleFx: { fame: 2, rep: { court: -3 }, infamy: 2 },
    alt: P('Bet on the Ministry’s favourite', 0.6, O('The favourite went through the coin twice. You won a few taels and a lecture on proper archery from the man beside you.', { wealth: 6 }), O('The favourite hit the officer holding the thread. Nobody was hurt except your wager.', { wealth: -6 }), { req: { wealth: '>=6' } }) },
  { key: 'horseback', if: { loc: 'jadegate', age: [14, 50] }, title: 'From the saddle', text: 'At Jade Gate, garrison archers and steppe riders shoot at straw men from horseback at a full gallop. The steppe riders have never lost.',
    stat: 'body', dc: 50, ok: 'You hit four straw men out of five at a gallop. The steppe riders looked at each other, then at you, and offered you a horse.', okFx: { fame: 3, wealth: 10 }, no: 'You hit one straw man and nearly a camel. The horse, at least, enjoyed itself.', noFx: { health: -2 },
    needle: 'qing_rain_needles', needleOk: 'You let fly a fan of Green Rain Needles at a gallop and every straw man went down at once. The steppe riders called it witchcraft and refused to compete.', needleFx: { fame: 2 },
    alt: C('Ride with the riders and learn their way', O('You rode with them for a week. You are a worse archer than you hoped and a better rider than you knew.', { body: 2, charm: 1 })) },
  { key: 'willow_branch', if: { loc: 'hangzhou', season: [1] }, title: 'Shooting the willow', text: 'At the Dragon Boat festival, Hangzhou’s archers shoot at willow branches hung with gourds full of pigeons. Hit the gourd, and the pigeons fly free, and the crowd decides who shot most beautifully.',
    stat: 'insight', dc: 40, ok: 'Your gourd burst and a dozen pigeons went up over West Lake into the evening. The crowd chose you. A silk merchant’s wife gave you her jade pendant.', okFx: { item: { jade_pendant: 1 }, fame: 2 }, no: 'You shot the willow, not the gourd. The pigeons stayed in. The crowd groaned.', noFx: { charm: -1 },
    needle: 'dang_needles', needleOk: 'Your needle split the gourd’s cord and it fell gently into the lake and opened, and the pigeons rose from the water. It was the most beautiful thing anyone had seen that day. You were disqualified.', needleFx: { fame: 3 },
    alt: C('Buy a gourd of pigeons and set them free yourself', O('You bought a gourd for a tael and let the pigeons go yourself. Nobody applauded. It was still lovely.', { wealth: -1, sanity: 4 })) },
  { key: 'snowbell', if: { loc: 'moyong' }, title: 'The bell in the snow', text: 'At the Moyong winter contest, archers shoot at a small bronze bell hanging behind a curtain of falling snow. The family judges by the sound.',
    stat: 'insight', dc: 55, ok: 'You shot through the snow by listening to the wind. The bell rang a pure, high note. A Moyong elder closed his eyes and said, "Again." It rang again.', okFx: { rep: { families: 4 }, insight: 1 }, no: 'Your arrow vanished into the snow. The bell did not ring. The silence was very Moyong.', noFx: {},
    needle: 'emei_needles', needleOk: 'Your needle rang the bell so softly that half the gallery thought they had imagined it. The Moyong heir did not. She asked for your name.', needleFx: { rep: { families: 2 }, fame: 1 },
    alt: C('Listen to the others shoot', O('You stood in the snow and listened to the bell ring and fail to ring for an hour. You learned more about archery from the silence than from the sound.', { insight: 2 })) },
  { key: 'wall', if: { loc: 'changan', season: [2] }, title: 'The Double Ninth on the wall', text: 'On the Double Ninth festival, the archers of Chang’an climb the city wall and shoot at chrysanthemum targets floating on the moat. Chrysanthemum wine is served throughout, which affects results.',
    stat: 'body', dc: 40, ok: 'You hit seven chrysanthemums out of nine, and the wine had nothing to do with it, mostly. The magistrate gave you a purse of silver.', okFx: { wealth: 15, fame: 2 }, no: 'You hit the moat, repeatedly. The ducks grew concerned.', noFx: {},
    needle: 'qing_rain_needles', needleOk: 'You threw needles from the wall and sank every flower at once. The magistrate did not know whether to arrest you or hire you, and did neither.', needleFx: { fame: 2, rep: { court: -1 } },
    alt: C('Drink the chrysanthemum wine and watch', O('You drank the chrysanthemum wine and watched the flowers float on the moat in the autumn light. Somewhere, you are told, archery was happening.', { sanity: 4 })) },
  { key: 'lantern', if: { loc: 'taihang' }, title: 'The stronghold lantern', text: 'Green Forest bandits test their archers by shooting the lantern off the stronghold flagpole at night. Visitors are invited to try. Visitors who miss buy the wine.',
    stat: 'body', dc: 40, ok: 'Your arrow cut the lantern’s cord and it fell into the courtyard and did not even go out. The bandits roared and made you drink with the captain.', okFx: { rep: { unorthodox: 3 }, fame: 1 }, no: 'You missed the lantern and hit the flag. The flag was the stronghold’s pride. You bought a great deal of wine.', noFx: { wealth: -5 },
    needle: 'uno_silent_needle', needleOk: 'Your needle snuffed the lantern flame without touching the lantern. The courtyard went dark and silent. In the dark, a bandit whispered, "Blood Shadow."', needleFx: { rep: { unorthodox: 2 }, infamy: 2 },
    alt: C('Buy the wine without shooting', O('You bought the wine without shooting. The bandits thought this was the most sensible thing a visitor had ever done.', { wealth: -3, rep: { unorthodox: 2 } })) },
  { key: 'pepper_string', if: { loc: 'chengdu' }, title: 'The pepper garland', text: 'Chengdu archers shoot at the string holding a garland of dried peppers over the market square. Cut it and the peppers rain down, and the crowd fights over them.',
    stat: 'insight', dc: 40, ok: 'Your arrow cut the string. Peppers rained down on the square, and a riot of grandmothers broke out. A physician pressed a pot of wound salve on you in thanks; he would be busy all week.', okFx: { item: { healing_salve: 1 }, fame: 2 }, no: 'You hit the garland, not the string. One pepper fell, onto a magistrate.', noFx: { fame: -1 },
    needle: 'dang_needles', needleOk: 'Your needle cut the string. A Dang cousin in the crowd watched the needle, not the peppers, and went home to report.', needleFx: { fame: 1, rep: { families: -1 } },
    alt: C('Stand under the garland with a basket', O('When someone else cut the string, you were already standing beneath it with a basket. You ate well for a month.', { wealth: 3, insight: 1 })) },
];
const tplBow = template('tn_bow', BOW_ROWS, (r) => E('tn_bow', T, {
  if: { age: [14, 60], ...r.if }, once: false, cd: 3, title: r.title, text: r.text,
  choices: [
    R('Shoot', r.stat, r.dc, O(r.ok, { flag: WIN, ...r.okFx }), O(r.no, r.noFx)),
    C('Throw a needle instead of shooting', O(r.needleOk, r.needleFx), { show: { manual: r.needle } }),
    r.alt,
  ],
}));

// Famous young fighters of the roster, met across a bracket. Some are fought; others are won another way.
const NAMED_ROWS = [
  { key: 'jin', id: 'namgung_jin', if: { region: ['jiangnan', 'central'], year: [12, 37] }, once: false, cd: 6, title: 'The Namgung heir', text: 'Namgung Jin is in the other half of the bracket and wins each bout without once looking at his opponent. In the final, he looks at you.',
    fightT: 'Fight Namgung Jin', enter: 'He drew the Heavenly Emperor Sword in a single motion, and the air in the square grew heavy, like the moment before a storm.', win: 'Namgung Jin got up slowly, as if the ground had betrayed him. "Who taught you that?" he said. He did not wait for an answer. He will find out.', winFx: { fame: 6, flag: WIN, rel: { '@namgung_jin': { res: 20, role: 'rival' } } }, lose: 'He beat you in seven exchanges and told you, coldly and correctly, which three of yours had been wasted.', loseFx: { insight: 2, rel: { '@namgung_jin': { res: 5 } } },
    rollT: 'Make him laugh before the bout', stat: 'charm', dc: 45, ok: 'You said something about the weight of his family’s name and the size of his family’s sword. He laughed, once, sharp and surprised, as if it had escaped him. Then he beat you, but differently.', okFx: { rel: { '@namgung_jin': { aff: 12, res: 5 } } }, no: 'He did not laugh. He looked at you as if you were weather, and beat you as if you were weather too.', noFx: { rel: { '@namgung_jin': { res: -3 } } },
    altT: 'Withdraw, and tell him he is not worth your time', alt: 'You withdrew from the final. Namgung Jin, who has been called many things, had never been called not worth the time. He has thought of nothing else since.', altFx: { fame: -1, rel: { '@namgung_jin': { res: 5, aff: -5, role: 'rival' } } } },
  { key: 'paeng_gu', id: 'paeng_gu', if: { region: 'hebei', year: [8, 60] }, title: 'Fight first, drink after', text: 'Paeng Gu, a Paeng son your own age, has drawn you in the first round and is delighted about it. "Fight first, drink after," he says. "Or drink first. I am flexible."',
    fightT: 'Fight first', enter: 'He came at you with the Five Tigers Severing Saber and a grin the size of Hebei.', win: 'Paeng Gu went down laughing, came up laughing, and paid for everything that evening.', winFx: { flag: WIN, rel: { '@paeng_gu': { aff: 15, res: 10, role: 'friend' } } }, lose: 'His saber put you on the boards. He carried you to the wine-house on his shoulder, singing about you.', loseFx: { rel: { '@paeng_gu': { aff: 15 } } },
    rollT: 'Drink first', stat: 'health', dc: 55, ok: 'You drank him under the table before the bout. He forfeited, being under a table, and declared you his best friend from the floor.', okFx: { flag: WIN, rel: { '@paeng_gu': { aff: 20, role: 'friend' } } }, no: 'You forfeited the bout, being asleep. Paeng Gu won, and sat by your bed all evening, very pleased with both of you.', noFx: { health: -3, rel: { '@paeng_gu': { aff: 12 } } },
    altT: 'Refuse to fight anyone that cheerful', alt: 'He was hurt, then hungry, then your friend anyway. Paeng Gu has no talent for grudges.', altFx: { rel: { '@paeng_gu': { aff: 10 } } } },
  { key: 'yeonwoo', id: 'yeonwoo', if: { region: ['jingchu', 'central'], year: [10, 70] }, title: 'Sorry in advance', text: 'Your opponent is Song Yeon-woo of Wudang, who apologises before the bout, apologises during it, and has so far won every single one.',
    fightT: 'Fight him', enter: '"I am so sorry," he said, and drew a Taiji Sword that moved like a slow river.', win: 'He apologised for losing, too. Then he asked, very sincerely, what you had done in the fourth exchange, and wrote it down.', winFx: { flag: WIN, fame: 3, rel: { '@yeonwoo': { res: 15, aff: 5 } } }, lose: 'He apologised for winning, and offered to show you where you went wrong. He was right about all of it.', loseFx: { insight: 2, rel: { '@yeonwoo': { aff: 8 } } },
    rollT: 'Apologise first', stat: 'charm', dc: 30, ok: 'An apology contest broke out on the platform. After ten minutes the judges declared a draw to make it stop. Song Yeon-woo was overjoyed; nobody had ever out-apologised him before.', okFx: { charm: 1, rel: { '@yeonwoo': { aff: 15 } } }, no: 'He out-apologised you easily, then out-fought you, then apologised for that.', noFx: { rel: { '@yeonwoo': { aff: 5 } } },
    altT: 'Ask him to spar privately instead', alt: 'You sparred by the river at dusk with nobody watching. He did not apologise once. You learned that he only does it when people are looking.', altFx: { body: 1, rel: { '@yeonwoo': { res: 8, aff: 8 } } } },
  { key: 'hyeryeong', id: 'hyeryeong', if: { region: ['shu', 'central'], year: [9, 70] }, title: 'Dinner as an apology', text: 'Gang Hye-ryeong of Emei has already broken one opponent’s sword this morning and then cooked him dinner as an apology. You are her next opponent.',
    fightT: 'Fight her', enter: 'She drew the Silent Waters Sword and smiled, which no one from Emei is supposed to do.', win: 'She stared at the sword at her throat, then grinned. "Dinner," she said. "I insist." It was the best meal of your year.', winFx: { flag: WIN, fame: 3, health: 5, rel: { '@hyeryeong': { res: 15, aff: 10 } } }, lose: 'She knocked your sword into the crowd, then cooked you dinner. It was the best meal of your year, and the most humbling.', loseFx: { health: 5, rel: { '@hyeryeong': { aff: 10 } } },
    rollT: 'Never let her touch your blade', stat: 'body', dc: 45, ok: 'You kept your blade away from hers for the whole bout and won on a touch to the shoulder. She was so delighted that her sword was intact that she hugged you.', okFx: { flag: WIN, rel: { '@hyeryeong': { aff: 12, res: 10 } } }, no: 'She touched your blade once. It broke. She was already apologising.', noFx: { rel: { '@hyeryeong': { aff: 8 } } },
    altT: 'Tell her you have heard about her cooking', alt: 'She blushed, forfeited, and took you to the kitchen. You did not fight at all that day, and it was one of the best days of your life.', altFx: { health: 4, rel: { '@hyeryeong': { aff: 15 } } } },
  { key: 'dongsu', id: 'dongsu', if: { loc: 'luoyang', year: [10, 70] }, title: 'Dong-su’s book', text: 'Dong-su of the Beggars’ Sect runs the betting on the bridge bouts and has offered you a cut if you fight, lose in the third round, and look surprised.',
    rollT: 'Win instead, and split the winnings with him', stat: 'body', dc: 40, ok: 'You won all four rounds. Dong-su, who had bet on you the whole time, split the winnings and laughed until he fell off the bridge.', okFx: { flag: WIN, wealth: 10, rel: { '@dongsu': { aff: 10, res: 10 } } }, no: 'You lost honestly in the first round. Dong-su lost his book. He bought you noodles anyway, out of solidarity.', noFx: { wealth: -2, rel: { '@dongsu': { aff: 5 } } },
    altT: 'Take the deal', alt: 'You lost in the third round and looked very surprised. Dong-su paid you, grinning, and from then on called you partner.', altFx: { wealth: 8, infamy: 1, rel: { '@dongsu': { aff: 12, role: 'friend' } } } },
  { key: 'yeon', id: 'moyong_yeon', if: { region: ['liaodong', 'hebei'], year: [12, 70] }, title: 'Returned, improved', text: 'In the Moyong winter exhibition, your opponent is Moyong Yeon, the family heir, who returns your own technique to you in the third exchange, improved. She seems genuinely curious what you will do next.',
    rollT: 'Do something you have never done before', stat: 'insight', dc: 50, ok: 'You improvised something with no name. She stopped, lowered her sword, and said, "Again. Slower." You talked until the torches burned out.', okFx: { insight: 2, rel: { '@moyong_yeon': { aff: 15, res: 15 } } }, no: 'Your improvisation came out as your favourite move. She returned it, with a look of faint disappointment.', noFx: { rel: { '@moyong_yeon': { res: -2 } } },
    altT: 'Stop fighting and ask what she sees', alt: 'She told you, precisely and without mercy, everything that was wrong with how you fight. Then, more quietly, the one thing that was not.', altFx: { insight: 1, rel: { '@moyong_yeon': { aff: 10 } } } },
  { key: 'dang_min', id: 'dang_min', if: { region: 'shu', year: [11, 70] }, title: 'Sorry about the needles', text: 'Dang Min, the Dang prodigy, is your opponent in the hidden-weapons bracket and keeps apologising for the needles he is obliged to throw.',
    rollT: 'Catch his needles', stat: 'body', dc: 45, ok: 'You caught three needles out of the air. He was so pleased that he forgot to keep throwing and started asking how you did it.', okFx: { flag: WIN, rel: { '@dang_min': { aff: 10, res: 15 } } }, no: 'A needle found your arm. He treated it himself, with an antidote he had invented that morning, and refused to let you pay.', noFx: { health: -4, rel: { '@dang_min': { aff: 12 } } },
    altT: 'Ask him about his antidotes', alt: 'He talked about antidotes for an hour, shyly, then not shyly at all. You came away with a recipe and a friend.', altFx: { insight: 1, recipe: 'healing_salve', rel: { '@dang_min': { aff: 15 } } } },
  { key: 'jegal_ha', id: 'jegal_ha', if: { loc: ['jegal', 'capital', 'paeng'], year: [11, 70] }, title: 'Baduk on the floor', text: 'The Jegal contest is fought on a baduk board drawn on the floor: every stone placed is a step taken. Your opponent, Jegal Ha, has already lost twice today on purpose, to see what would happen.',
    rollT: 'Play the board, not the floor', stat: 'insight', dc: 55, ok: 'You played the board, and the floor followed. She resigned on move ninety, delighted. "Nobody plays the board," she said. "They all play me."', okFx: { flag: WIN, insight: 2, rel: { '@jegal_ha': { res: 20, aff: 10 } } }, no: 'She let you win, and made sure you knew it. You will be thinking about which move was the gift for weeks.', noFx: { sanity: -1, rel: { '@jegal_ha': { aff: 5 } } },
    altT: 'Kick the stones over', alt: 'You kicked the stones across the floor. There was a terrible silence, and then Jegal Ha laughed until she had to sit down. "Nobody has ever done that," she said.', altFx: { rel: { '@jegal_ha': { aff: 15, res: -3 } } } },
  { key: 'mokcheol', id: 'mokcheol', if: { sect: 'cult', year: [9, 70] }, title: 'Both of you watched', text: 'At the Pit of Red Sand, you are paired with Mok Cheol, the quiet boy who shares his food and never his feelings. Neither of you wants this. Both of you are being watched.',
    rollT: 'Fight so hard that neither of you is punished', stat: 'body', dc: 35, ok: 'You fought so fiercely that the watchers on the rim were satisfied with a draw. That night Mok Cheol left half his bread on your mat.', okFx: { rep: { cult: 2 }, rel: { '@mokcheol': { aff: 15, res: 10 } } }, no: 'You lost. When nobody was looking, Mok Cheol helped you up.', noFx: { health: -3, rel: { '@mokcheol': { aff: 10 } } },
    altT: 'Throw the bout so he eats tonight', alt: 'You went down in the second exchange. You went hungry. He knew, and never said, and never forgot.', altFx: { health: -3, rep: { cult: -2 }, rel: { '@mokcheol': { aff: 20, role: 'friend' } } } },
  { key: 'taeo', id: 'taeo', if: { loc: 'luoyang', year: [16, 70] }, title: 'The crooked smile', text: 'Your opponent at the escort-yard bouts is Kang Tae-o, a young escort guard with a crooked smile, who turns red every time the crowd cheers his name.',
    rollT: 'Go easy on him: he looks terrified', stat: 'insight', dc: 30, ok: 'You let him find his feet before you beat him. Afterwards he found you and thanked you, red to the ears, for not embarrassing him.', okFx: { flag: WIN, rel: { '@taeo': { aff: 15 } } }, no: 'You went easy on him, and he was not terrified at all, only shy. He beat you, and apologised, and turned red.', noFx: { rel: { '@taeo': { aff: 10, res: 5 } } },
    altT: 'Cheer for him louder than his friends do', alt: 'You cheered for him from the other side of the platform. He turned so red that he lost. He has never let you forget it, and never wanted to.', altFx: { charm: 1, rel: { '@taeo': { aff: 12 } } } },
  { key: 'harin', id: 'hua_harin', if: { loc: ['mounthua', 'willow', 'changan'], year: [10, 33] }, title: 'Laughing too loudly', text: 'At the Mount Hua open day, the junior chosen to face the visitors is Ok Ha-rin, who laughs too loudly and trains too hard, and who is laughing now.',
    fightT: 'Fight her', enter: 'She drew the Plum Blossom Sword, still laughing, and the laugh stopped exactly when the sword moved.', win: 'She laughed louder losing than most people laugh winning, and made you promise a rematch.', winFx: { flag: WIN, fame: 2, rel: { '@hua_harin': { res: 10, aff: 10 } } }, lose: 'She beat you with twenty-four plum blossoms, then offered you a real plum from her sleeve.', loseFx: { rel: { '@hua_harin': { aff: 10 } } },
    rollT: 'Match her laugh for laugh', stat: 'charm', dc: 25, ok: 'You laughed back. The whole platform laughed. The elders frowned, then gave up and laughed too. Nobody remembers who won.', okFx: { rel: { '@hua_harin': { aff: 15 } } }, no: 'You laughed, and it came out wrong. She stopped laughing and looked at you with real concern.', noFx: { rel: { '@hua_harin': { aff: 5 } } },
    altT: 'Ask her about Mount Hua', alt: 'She told you everything: the debts, the leaking roofs, the proud old men, the plum trees. She loves it the way people love things that are falling down.', altFx: { insight: 1, codex: 'people.hua_harin', rel: { '@hua_harin': { aff: 8 } } } },
];
const tplNamed = template('tn_named', NAMED_ROWS, (r) => {
  const who = `@${r.id}`;
  return E('tn_named', T, {
    if: { alive: r.id, age: [14, 32], realm: '>=1', ...r.if }, once: r.once ?? true, cd: r.cd, art: 'tournament', title: r.title, text: r.text,
    choices: [
      ...(r.fightT ? [C(r.fightT, O(r.enter, { meet: who, combat: { foe: who, context: T, lethal: 0, win: { text: r.win, ...r.winFx }, lose: { text: r.lose, ...r.loseFx } } }))] : []),
      R(r.rollT, r.stat, r.dc, O(r.ok, { meet: who, ...r.okFx }), O(r.no, { meet: who, ...r.noFx })),
      C(r.altT, O(r.alt, { meet: who, ...r.altFx })),
    ],
  });
});

// Selection trials held by sects and houses that recruit by open contest.
const SELECT_ROWS = [
  { key: 'kongtong', sect: 'kongtong', if: { loc: ['changan', 'kongtong'], age: [8, 18] }, title: 'The brick', text: 'Kongtong recruiters have set up a table in Chang’an’s East Market: break a brick with your fist and you are in. The pile of bricks is large. The pile of bandages is larger.',
    stat: 'body', dc: 30, rep: { orthodox: 3 }, ok: 'The brick broke. So, nearly, did your hand. The recruiter wrapped it himself and wrote your name in the Kongtong roll.', okFx: { health: -3 }, no: 'The brick did not break. Your knuckles did, slightly. The recruiter gave you a bandage and a kindly shove.', noFx: { health: -4 },
    alt: R('Break it with your forehead', 'health', 60, O('The brick broke. The recruiter stared at you, then at the brick, then wrote your name down with an expression of deep respect.', { join: 'kongtong', rep: { orthodox: 3 }, health: -6 }), O('The brick did not break. You saw stars, and then the sky, and then a very concerned recruiter.', { health: -10 })),
    walk: 'You looked at the bandages and kept walking. Your hands thanked you.' },
  { key: 'diancang', sect: 'diancang', if: { loc: ['chengdu', 'diancang'], age: [8, 16] }, title: 'The falling leaf', text: 'A Diancang swordsman has come north to Chengdu to find students. His test: catch a falling leaf on the point of a stick before it lands. He has brought a great many leaves.',
    stat: 'body', dc: 30, rep: { orthodox: 3 }, ok: 'You caught the leaf on the point of the stick on your third try. The swordsman nodded once. You will walk south with him in the spring.', okFx: { body: 1 }, no: 'The leaves landed, one after another, all afternoon. He thanked you for trying and gave you a leaf to keep.', noFx: {},
    alt: R('Watch the wind instead of the leaf', 'insight', 35, O('You stopped chasing the leaf and waited where the wind would bring it. The swordsman laughed. "That," he said, "is the Diancang Swift Sword." You were in.', { join: 'diancang', rep: { orthodox: 3 }, insight: 1 }), O('The wind changed. The leaf did not care about your theory.', {})),
    walk: 'You watched the other children chase leaves and went home. The south is very far away.' },
  { key: 'qingcheng', sect: 'qingcheng', if: { loc: ['qingcheng', 'chengdu'], age: [8, 16] }, title: 'Forty bows', text: 'Qingcheng is selecting disciples at its mountain gate this spring. Candidates must bow correctly to forty elders in a row, each of whom expects something slightly different.',
    stat: 'charm', dc: 20, rep: { orthodox: 3 }, ok: 'Forty bows, each exactly right. The fortieth elder smiled thinly and handed you a green robe. Qingcheng values precision, and remembers it.', okFx: {}, no: 'You bowed too deeply to the nineteenth elder, who took it as mockery. Qingcheng forgets nothing; you will be on a list somewhere.', noFx: { flag: 'tn.qingcheng_grudge' },
    alt: P('Bow to the servants too', 0.5, O('You bowed to the gatekeeper and the tea servant as well. An elder noticed, and wrote "courteous" in your file, and you were in.', { join: 'qingcheng', rep: { orthodox: 4 } }), O('The elders thought you were mocking them. The servants appreciated it.', { charm: 1 })),
    walk: 'Forty bows seemed a great many bows. You went down the mountain with your back straight.' },
  { key: 'zhongnan', sect: 'zhongnan', if: { loc: ['zhongnan', 'changan'], age: [8, 16] }, title: 'The seven', text: 'Zhongnan tests candidates in sevens: seven children must cross a courtyard in formation while the elders throw sandbags. The group passes or fails together.',
    stat: 'insight', dc: 30, rep: { orthodox: 3 }, ok: 'You saw where the formation was weak and stepped into the gap. All seven of you crossed. All seven of you were accepted, and all six of the others will remember you.', okFx: { charm: 1 }, no: 'The formation broke at the middle, where you were. Everyone was very nice about it, which was worse.', noFx: {},
    alt: C('Take the place of the boy who fell', O('A small boy was knocked flat in the first rush. You picked him up, put him in your place and took his. Your group failed. An elder came to find you afterwards and said, "You will come anyway."', { join: 'zhongnan', rep: { orthodox: 2 }, sanity: 3 })),
    walk: 'You watched one group of seven cross and fail, and decided you did not want to fail in company.' },
  { key: 'beggars', sect: 'beggars', if: { loc: 'luoyang', age: [8, 30] }, title: 'One day on the bridge', text: 'The Beggars’ Sect’s entrance trial: spend one day begging on the Tianjin Bridge and bring back more than a Three-Pouch elder. Nobody has ever beaten the elder.',
    stat: 'charm', dc: 35, rep: { orthodox: 3 }, ok: 'You told passers-by a story so sad that a merchant wept and a magistrate paid. You beat the elder by four coppers. He laughed, and gave you your first pouch.', okFx: { fame: 1 }, no: 'The elder collected forty coppers. You collected six and a lecture from a monk.', noFx: {},
    alt: C('Share your takings with the beggar children', O('You gave your coppers away to the children on the bridge. You came back with nothing. The elder had been watching all day. "That," he said, "is begging." You were in.', { join: 'beggars', rep: { orthodox: 2 }, sanity: 3 })),
    walk: 'You put a copper in the elder’s bowl and walked on. He thanked you and told you your fortune, which was mostly accurate.' },
  { key: 'paeng', sect: 'paeng', if: { loc: 'paeng', age: [10, 25] }, title: 'The millstone', text: 'The Paeng Fortress takes outsiders who can carry a millstone around the courtyard three times. Then they feed you, which is the real test.',
    stat: 'body', dc: 40, rep: { families: 5 }, ok: 'Three times around, and the millstone did not touch the ground once. Then you ate four bowls. The patriarch laughed like a landslide and took you on as a retainer.', okFx: { health: 3 }, no: 'You carried the millstone twice around and then it carried you to the ground. They fed you anyway.', noFx: { health: 2 },
    alt: R('Skip the stone and win the eating', 'health', 50, O('You did not lift the millstone at all. You ate seven bowls. The Paeng were so moved that they took you on anyway, as a kind of mascot.', { join: 'paeng', rep: { families: 3 } }), O('You ate five bowls and could not move for a day. The Paeng thought this was a perfectly good effort but not quite Paeng.', { health: -2 })),
    walk: 'You looked at the millstone, and at the Paeng, and decided you were not quite loud enough to join.' },
  { key: 'greenforest', sect: 'greenforest', if: { loc: 'taihang', age: [14, 40] }, title: 'Blade, bowl and brother', text: 'The Green Forest recruits the usual way: whoever wins the wrestling at the stronghold gate gets a blade, a bowl and a brother.',
    stat: 'body', dc: 35, rep: { unorthodox: 8, orthodox: -3 }, ok: 'You threw the gatekeeper into the mud and drank from the common bowl. You are a sworn brother of the Green Forest Alliance now, for better and worse.', okFx: { infamy: 3 }, no: 'The gatekeeper threw you into the mud, then helped you up and said, "Come back when you are hungrier."', noFx: { health: -3 },
    alt: C('Wrestle, but refuse the oath', O('You won the wrestling and refused the bowl. The bandits were offended, then impressed. "An honest guest," said their captain, and let you go with a gift of dried meat.', { fame: 1, rep: { unorthodox: 2 } })),
    walk: 'You walked past the stronghold gate. The bandits watched you go, and wrote you down as a coward, which was safer than the alternative.' },
  { key: 'abacus', sect: 'goldenabacus', if: { loc: 'hangzhou', age: [12, 30] }, title: 'A hundred sums', text: 'The Golden Abacus Guild holds its selection as an abacus contest: a hundred sums in an hour, under a clerk who sighs at every mistake.',
    stat: 'insight', dc: 35, rep: { merchants: 8 }, ok: 'A hundred sums and the clerk did not sigh once. He looked almost disappointed. You start on the first of the month.', okFx: {}, no: 'At sum sixty-one the clerk sighed. At sixty-two he sighed again. By seventy you could hear nothing but sighing.', noFx: {},
    alt: R('Talk your way past the sums', 'charm', 30, O('You persuaded the clerk that a good merchant does not need to add, only to know someone who can. He hired you as that someone’s supervisor.', { join: 'goldenabacus', rep: { merchants: 5 }, charm: 1 }), O('The clerk sighed. It was the longest sigh of the day.', {})),
    walk: 'You looked at the abacus and the clerk and decided there were other ways to get rich, most of them faster.' },
  { key: 'depot', sect: 'easterndepot', if: { loc: 'capital', age: [16, 35] }, title: 'The room with no windows', text: 'The Eastern Depot’s open trial is held in a courtyard with no windows. Survive an hour of questioning without telling them anything true.',
    stat: 'insight', dc: 45, rep: { court: 10, orthodox: -5 }, ok: 'An hour of questions and not one true answer. The officer smiled at you, which in the Depot is the warmest thing that ever happens. You were handed a black and silver uniform.', okFx: {}, no: 'In the forty-third minute you told them where you were born. The officer wrote it down, and thanked you, and let you go, and kept the page.', noFx: { rep: { court: -2 } },
    alt: C('Tell them everything true, cheerfully', O('You told them everything, cheerfully, in great detail, including your opinions about their uniforms. They let you go, puzzled. Your file says "harmless".', { rep: { court: 2 }, sanity: 2 })),
    walk: 'You did not go into the courtyard with no windows. The Depot noted that you had not gone in.' },
  { key: 'moyong', sect: 'moyong', if: { loc: 'moyong', age: [10, 20] }, title: 'Seen once', text: 'The Moyong family takes outside retainers once a decade, by a test of imitation: watch an elder perform a form once, then perform it back.',
    stat: 'insight', dc: 45, rep: { families: 6 }, ok: 'You performed it back without a single error. The elder looked at you as if you were a mirror that had briefly become a window. You are a Moyong retainer now.', okFx: { insight: 1 }, no: 'You remembered the beginning and the end. The middle was a fog. So, mostly, was the elder’s expression.', noFx: {},
    alt: P('Perform it back, slightly better', 0.4, O('You improved it. The elder was silent for a long time, then said, "Again," and you did, and he took you in himself, as his own retainer.', { join: 'moyong', rep: { families: 8 }, insight: 2 }), O('You improved it. The Moyong do not like being improved upon. You were shown the gate with frozen courtesy.', { rep: { families: -2 } })),
    walk: 'You watched the elder perform the form once, and walked home trying to remember it. You still try, sometimes.' },
];
const tplSelect = template('tn_select', SELECT_ROWS, (r) => E('tn_select', T, {
  if: { sect: 'none', ...r.if }, title: r.title, text: r.text,
  choices: [
    R('Take the test', r.stat, r.dc, O(r.ok, { join: r.sect, rep: r.rep, ...r.okFx }), O(r.no, r.noFx)),
    r.alt,
    C('Walk away', O(r.walk)),
  ],
}));

// Offers to fix a bout: every fixer wants something different, and some do not take no gracefully.
const FIX_ROWS = [
  { key: 'fortress', if: { region: 'jingchu' }, title: 'The toll-man', text: 'A Water Fortress toll-man finds you before the river contest. "The Fortress has money on your opponent," he says. "Lose, and the Fortress will be grateful. The Fortress is rarely grateful."', bribe: 30,
    loseT: 'Take the money and lose', lose: 'You lost, and the Fortress was grateful, and your boat never paid a toll on Lake Dongting again.', loseFx: { rep: { unorthodox: 3 }, infamy: 1, fame: -1 },
    winT: 'Take the money and win', win: 'You won with the Fortress’s silver in your sleeve. The toll-man watched from a boat, and did not wave.', winFx: { rep: { unorthodox: -6 }, infamy: 1, next: { id: 'tn_fixer_returns', in: 2 } },
    exT: 'Tell the contest stewards', stat: 'charm', dc: 35, exOk: 'The stewards moved the contest to another day and another river. The Fortress lost its bet and learned your name.', exOkFx: { rep: { orthodox: 3, unorthodox: -4 }, fame: 2 }, exNo: 'The stewards were Fortress men too. They thanked you for your concern.', exNoFx: { rep: { unorthodox: -3 } },
    refuse: 'The toll-man shrugged. "The river is long," he said, which you suspect was a threat.' },
  { key: 'guild', if: { loc: 'hangzhou' }, title: 'The guild’s interest', text: 'A Golden Abacus clerk explains, with an abacus, how much the Guild stands to make if you lose in the semifinal, and how much of that could be yours.', bribe: 40,
    loseT: 'Take your share and lose', lose: 'You lost in the semifinal. The clerk paid you to the copper, and wrote your name in a ledger of people who can be relied upon.', loseFx: { rep: { merchants: 4 }, infamy: 1, sanity: -2 },
    winT: 'Take your share and win', win: 'You won. The clerk’s abacus went very still. Somewhere in Hangzhou, a ledger was amended.', winFx: { rep: { merchants: -5 }, infamy: 1, next: { id: 'tn_fixer_returns', in: 3 } },
    exT: 'Show the clerk’s sums to a magistrate', stat: 'insight', dc: 40, exOk: 'The clerk’s sums, read aloud in court, explained a great many of Hangzhou’s surprising results. The magistrate was pleased. The Guild was not.', exOkFx: { rep: { merchants: -3, court: 3 }, fame: 3 }, exNo: 'The magistrate was a Guild partner. The sums were returned to the clerk with an apology.', exNoFx: { rep: { merchants: -2 } },
    refuse: 'The clerk recalculated, without you. "A pity," he said. "You were very good value."' },
  { key: 'bookmaker', if: { loc: 'kaifeng' }, title: 'The bookmaker’s boy', text: 'A Kaifeng bookmaker’s boy slips you a note: twenty-five taels to go into the canal in the second round, with a convincing splash.', bribe: 25,
    loseT: 'Take it and splash convincingly', lose: 'You went into the canal in the second round with a splash they still talk about. The bookmaker paid in full. Kaifeng respects a professional.', loseFx: { infamy: 2, fame: -1 },
    winT: 'Take it and stay on the bridge', win: 'You stayed on the bridge. The bookmaker’s boy, in the crowd, went white, then ran.', winFx: { infamy: 1, next: { id: 'tn_fixer_returns', in: 2 } },
    exT: 'Push the boy into the canal', stat: 'charm', dc: 30, exOk: 'You pushed the boy into the canal in front of everyone and told them why. The crowd loved it. The bookmaker left the city.', exOkFx: { fame: 3, rep: { unorthodox: -2 } }, exNo: 'You pushed the boy in. The crowd thought you were a bully. The bookmaker thought you were a problem.', exNoFx: { fame: -1, rep: { unorthodox: -2 } },
    refuse: 'You handed back the note. The boy looked relieved; he had not wanted to carry it.' },
  { key: 'uncle', if: { region: 'jiangnan', notSect: ['namgung'] }, title: 'An uncle’s request', text: 'A Namgung uncle invites you to tea. His nephew is fighting you tomorrow, he explains, and it would mean a great deal to the family if the boy won.', bribe: 20,
    loseT: 'Accept the tea and lose', lose: 'You lost to the nephew, who did not know, and was so happy that you nearly forgave yourself. The uncle sent you a fine tea every New Year afterwards.', loseFx: { rep: { families: 5 }, fame: -2, sanity: -2 },
    winT: 'Accept the tea and win anyway', win: 'You beat the nephew. The uncle did not look at you again. The family, it emerged, has a long memory and short patience.', winFx: { rep: { families: -5 } },
    exT: 'Tell the nephew', stat: 'charm', dc: 40, exOk: 'You told the nephew. He went red, then pale, then went to find his uncle. The next day he fought you with everything he had, and lost, and shook your hand.', exOkFx: { rep: { families: -2, orthodox: 2 }, fame: 4 }, exNo: 'The nephew did not believe you, and fought you angrily, and badly, and lost.', exNoFx: { rep: { families: -3 } },
    refuse: 'You declined the tea. The uncle smiled, very coldly. Some doors in Jiangnan are closed to you now.' },
  { key: 'depot', if: { loc: 'capital' }, title: 'The Ministry’s favourite', text: 'An Eastern Depot officer stops you in the street. The Ministry’s favourite is fighting you tomorrow, he explains, and the Ministry’s favourite must win. He does not offer money.', bribe: 0,
    loseT: 'Lose, as advised', lose: 'You lost. The officer nodded to you in the street the next day. You have never felt so dirty from so small a gesture.', loseFx: { rep: { court: 5 }, sanity: -4, fame: -1 },
    winT: 'Win anyway', win: 'You won. The Ministry’s favourite wept. The officer wrote something down. You can feel the page, somewhere in the capital, with your name on it.', winFx: { rep: { court: -8 }, fame: 3, flag: [WIN, 'tn.depot_grudge'] },
    exT: 'Report him to Commander Han Gyeong', stat: 'charm', dc: 45, exOk: 'Commander Han Gyeong listened, said nothing, and the next day the officer had been transferred to a garrison in the far south. The Commander remembers honest people.', exOkFx: { rel: { '@guard_commander': { res: 15 } }, rep: { court: 2 } }, exNo: 'The Commander could not be reached. The officer, however, heard that you had tried.', exNoFx: { rep: { court: -5 } },
    refuse: 'You said nothing at all, and fought as you would have fought. You lost anyway. The officer did not know whether to be satisfied.' },
  { key: 'shadow', if: { loc: 'kaifeng', realm: '>=3' }, title: 'A face you cannot remember', text: 'A woman whose face you forget even while looking at it tells you: lose tomorrow, or your opponent’s old master dies tonight. She does not say who is paying.', bribe: 0,
    loseT: 'Lose', lose: 'You lost. The old master lived. Nobody ever told him why, and you never will.', loseFx: { sanity: -3, fame: -2 },
    winT: 'Win, and hope she is bluffing', win: 'You won. In the morning, they found the old master in the canal. The Blood Shadow Pavilion does not bluff.', winFx: { sanity: -10, fame: 2 },
    exT: 'Warn the old master tonight', stat: 'insight', dc: 50, exOk: 'You found the old master’s house before midnight and sat in his garden with your sword across your knees. At the third watch, a shadow came, saw you, and left. You lost nothing but sleep.', exOkFx: { fame: 3, sanity: 3, rep: { unorthodox: -5 } }, exNo: 'You found the house. You were too late.', exNoFx: { sanity: -8 },
    refuse: 'You told her you would fight as you always fight. She smiled and was gone, and you could not remember the smile either. The old master lived. It had been a test, and you have no idea whether you passed.' },
  { key: 'elder', if: { loc: 'luoyang' }, title: 'A boy who needs it', text: 'A Nine-Pouch elder of the Beggars’ Sect asks you to lose to a beggar boy tomorrow. The boy needs one win to be taken into the sect. "He will not ask you," the elder says. "So I am asking."', bribe: 0,
    loseT: 'Lose to the boy', lose: 'You lost to the boy, convincingly. He was taken into the sect that night, and walked past you on the bridge a year later with three pouches on his belt, and did not know you, and that was right.', loseFx: { rep: { orthodox: 3 }, sanity: 5, fame: -1 },
    winT: 'Win anyway: he should earn it', win: 'You won. The boy cried and then came back and asked you to show him what he had done wrong. You showed him. He was taken in the next year, on his own.', winFx: { fame: 2, sanity: -1 },
    exT: 'Teach the boy one move tonight', stat: 'insight', dc: 30, exOk: 'You taught the boy one move under the bridge by lamplight. The next day he used it on you, and won, and you did not have to lose on purpose at all.', exOkFx: { rep: { orthodox: 3 }, sanity: 4, insight: 1 }, exNo: 'You taught him one move. He forgot it. You lost to him anyway, out of pity, which he did not need to know.', exNoFx: { rep: { orthodox: 2 }, sanity: 2 },
    refuse: 'The elder nodded as if he had expected it, and went to ask somebody else.' },
  { key: 'cult', if: { region: 'west' }, title: 'A gift from the west', text: 'A soft-spoken man with a merchant’s robes and a soldier’s hands offers you fifty taels to lose to a quiet youth from the western passes. He wants, he says, to see how the youth moves when he wins.', bribe: 50,
    loseT: 'Take it and lose', lose: 'You lost to the quiet youth. The merchant with soldier’s hands watched every move the youth made, and wrote it all down in a script you did not recognise.', loseFx: { rep: { cult: 5, orthodox: -2 }, infamy: 1 },
    winT: 'Take it and win', win: 'You beat the quiet youth. He looked at you, then at the merchant, as if afraid of what came next. The merchant was smiling.', winFx: { rep: { cult: -3 }, fame: 3, flag: [WIN, 'tn.cult_watched'] },
    exT: 'Report a Cult scout to the garrison', stat: 'insight', dc: 45, exOk: 'You described his hands, his script and his questions to the garrison commander. The merchant was gone by nightfall, but the garrison doubled its watch, and the Alliance heard your name.', exOkFx: { rep: { orthodox: 4, cult: -5 }, fame: 2 }, exNo: 'The commander laughed at you. "A Cult spy, at a caravan fair?" The merchant waved to you as he left.', exNoFx: { rep: { cult: -2 } },
    refuse: 'He bowed and withdrew, unoffended. "Perhaps another year," he said. "We have many years."' },
];
const tplFix = template('tn_fix', FIX_ROWS, (r) => E('tn_fix', T, {
  if: { age: [16, 45], realm: '>=1', ...r.if }, title: r.title, text: r.text,
  choices: [
    C(r.loseT, O(r.lose, { wealth: r.bribe, flag: 'tn.thrown', ...r.loseFx })),
    C(r.winT, O(r.win, { wealth: r.bribe, flag: WIN, ...r.winFx })),
    R(r.exT, r.stat, r.dc, O(r.exOk, r.exOkFx), O(r.exNo, r.exNoFx)),
    C('Refuse', O(r.refuse)),
  ],
}));

// The judges’ table: every ruling makes someone an enemy.
const JUDGE_ROWS = [
  { key: 'heir', if: { region: ['jiangnan', 'central', 'hebei'] }, title: 'The heir and the farmer', text: 'A Family heir has clearly lost to a farmer’s son from the provinces. The heir’s father is sitting at the end of your judges’ table, looking at you.',
    honestT: 'Give it to the farmer’s son', honest: 'You raised the farmer’s son’s hand. The crowd roared. The father at the end of the table stood up and left without a word, and his family will remember it.', honestFx: { rep: { families: -5 }, fame: 3, sanity: 3 },
    polT: 'Give it to the heir', pol: 'You gave it to the heir. The crowd booed. The farmer’s son looked at you once and walked off the platform, and you will remember his face.', polFx: { rep: { families: 5 }, sanity: -5, infamy: 1 },
    clT: 'Call a rematch, and let it decide itself', stat: 'charm', dc: 45, clOk: 'You declared the bout too close to call. The rematch was not close. The farmer’s son won again, and even the father could not argue.', clOkFx: { rep: { families: -1 }, fame: 2 }, clNo: 'Nobody wanted a rematch. Both sides were angry with you instead of each other.', clNoFx: { rep: { families: -3 } } },
  { key: 'needle', if: { region: ['shu', 'central'] }, title: 'A needle on the stone', text: 'After a bare-handed bout, a single needle lies on the platform. The winner is a Dang cousin. The loser is unconscious.',
    honestT: 'Disqualify the Dang cousin', honest: 'You disqualified the cousin. The Dang family sent a letter of complaint so elegantly poisonous that you burned it with tongs.', honestFx: { rep: { families: -4, orthodox: 3 }, fame: 2 },
    polT: 'Rule the needle fell from the crowd', pol: 'The needle fell from the crowd, you ruled. Everyone knew it had not. The Dang family sent you a gift. You did not open it.', polFx: { rep: { families: 3 }, sanity: -3 },
    clT: 'Prove where it came from', stat: 'insight', dc: 45, clOk: 'You found the pinhole in the cousin’s sleeve and the matching needle in his collar, in front of everyone. Nobody, not even the Dang, could argue with that.', clOkFx: { fame: 4, rep: { families: -2 } }, clNo: 'You could not prove it. You disqualified him anyway, on suspicion, and the Dang will never forgive you for being right without proof.', clNoFx: { rep: { families: -5 } } },
  { key: 'disguise', if: { locType: 'city' }, title: 'The rules say', text: 'A fighter in the men’s bracket has just won the semifinal and lost her cap. The rules, which are old, say she must be disqualified. The crowd, which is young, says otherwise.',
    honestT: 'Follow the rules', honest: 'You disqualified her. She bowed to you, perfectly, and left. The rule was followed. You did not sleep well.', honestFx: { rep: { orthodox: 1 }, sanity: -3 },
    polT: 'Pretend you did not notice the cap', pol: 'You looked very hard at your notes until the cap was back on. She won the final. Nobody official ever noticed anything.', polFx: { sanity: 2, fame: 1 },
    clT: 'Change the rules on the spot', stat: 'charm', dc: 40, clOk: 'You stood up and declared that the Alliance’s rule applied to men "and those who fight like them", which she clearly did. The crowd loved it. The other judges, outvoted by four hundred people, agreed.', clOkFx: { fame: 4, rep: { orthodox: -2 }, sanity: 3 }, clNo: 'The other judges overruled you. She was disqualified anyway, but she knew who had tried.', clNoFx: { sanity: -1 } },
  { key: 'demonpalm', if: { region: ['west', 'guanzhong', 'central'] }, title: 'A smell of burnt iron', text: 'A young fighter wins his bout with a palm strike that leaves a scorch mark on his opponent’s robe. The other judges have not noticed. You have: the Heavenly Demon Palm.',
    honestT: 'Denounce him as a Cult spy', honest: 'You denounced him. The crowd turned on him; the stewards dragged him off. Whether he was a spy or a frightened boy with the wrong teacher, you never learned.', honestFx: { rep: { orthodox: 5, cult: -5 } },
    polT: 'Say nothing', pol: 'You said nothing. He won the next round too, and on his way out of the city, he bowed to you, very slightly, from the gate.', polFx: { rep: { cult: 3 }, sanity: -2 },
    clT: 'Ask him privately where he learned it', stat: 'insight', dc: 50, clOk: 'You found him alone. He was a deserter, he said, from a Cult that had eaten his brothers. You let him go west by another road. He left you a name: a Cult commander who is not as loyal as he looks.', clOkFx: { rep: { cult: 2 }, flag: 'tn.cult_deserter', insight: 1 }, clNo: 'You approached him privately. By the time you reached his room, it was empty, and the window was open.', clNoFx: {} },
  { key: 'draw', if: { locType: ['city', 'estate'] }, title: 'Dead even', text: 'Two exhausted fighters have just hit each other at exactly the same moment and fallen at exactly the same time. The crowd is silent. The judges are looking at you.',
    honestT: 'Declare a draw', honest: 'A draw. The crowd groaned. Both fighters, carried off on doors, shook hands across the gap. Some outcomes should be shared.', honestFx: { fame: 1, sanity: 2 },
    polT: 'Give it to the fighter with the better sect', pol: 'You gave it to the one with the better-connected master. The other fighter’s friends threw cabbages at your table.', polFx: { rep: { orthodox: 2 }, sanity: -3 },
    clT: 'Decide who bled first', stat: 'insight', dc: 40, clOk: 'You remembered the order of every blow and awarded it on the first cut, and explained the bout to the crowd exchange by exchange. They applauded the explanation more than the result.', clOkFx: { fame: 3, insight: 1 }, clNo: 'You remembered it wrong. The fighter you ruled against remembered it right, at length, in public.', clNoFx: { fame: -2 } },
  { key: 'purse', if: { age: [30, 90] }, title: 'Something in your sleeve', text: 'Before the final, a rich man shakes your hand and leaves something heavy in your sleeve. His son is in the final. The purse is warm from his hand.',
    honestT: 'Return the purse publicly', honest: 'You held up the purse in front of the stands and returned it to him, loudly. The crowd cheered. The rich man smiled through his teeth, which looked painful.', honestFx: { fame: 4, rep: { merchants: -3 } },
    polT: 'Keep it, and rule for his son', pol: 'You kept it and ruled for his son. Fifty taels. It was the most expensive money you have ever earned.', polFx: { wealth: 50, infamy: 3, sanity: -4 },
    clT: 'Keep it, and judge honestly anyway', stat: 'charm', dc: 35, clOk: 'His son lost, fairly. The rich man came to complain and found that he could not, without saying why. You gave the fifty taels to the loser’s school.', clOkFx: { fame: 2, sanity: 3 }, clNo: 'His son lost. The rich man complained, loudly, about the purse, which was not wise of him, and not good for you.', clNoFx: { infamy: 2, fame: -2 } },
  { key: 'poison', if: { age: [30, 90] }, title: 'Grey lips', text: 'In the middle of the final, one fighter staggers and his lips turn grey. His opponent’s blade has a faint sheen that was not there this morning.',
    honestT: 'Halt the bout and call the physicians', honest: 'You stopped the bout and shouted for physicians. The fighter lived. His opponent was gone before anyone thought to stop him.', honestFx: { fame: 3, rep: { orthodox: 2 } },
    polT: 'Let it finish; the rules allow blades', pol: 'The rules allow blades. You let it finish. The grey-lipped fighter lost, and was carried off, and you did not ask what happened next.', polFx: { sanity: -6 },
    clT: 'Name the poison and its cure', stat: 'insight', dc: 55, clOk: 'Grey lips, sweet breath, pinned pupils: Dang mountain moss. You called for licorice root and cold tea and the boy was sitting up by sunset. The physicians bowed to you.', clOkFx: { fame: 5, insight: 2, codex: { id: 'secret.tn_grey_lips', cat: 'recipes', title: 'Grey lips', text: 'Dang mountain moss on a blade turns the lips grey and the breath sweet. Licorice root and cold tea, given within the hour, undo it.' } }, clNo: 'You could not name it. The physicians could not either. He lived, but he will not fight again.', clNoFx: { sanity: -3 } },
  { key: 'friend', if: { has: 'friend' }, bind: { x: 'friend' }, title: 'Your friend’s disciple', text: 'The final is between a stranger and the disciple of your old friend {x}, who is sitting beside you on the judges’ bench. The stranger won. Narrowly. You think.',
    honestT: 'Give it to the stranger', honest: 'You gave it to the stranger. {x} did not speak to you for the rest of the day, and then came to your room with a jar of wine. "You were right," {x.he} said. "I hate it."', honestFx: { fame: 2, rel: { x: { aff: -6, res: 10 } } },
    polT: 'Give it to the disciple', pol: 'You gave it to {x}’s disciple. {x} embraced you. The stranger went home. You think about the stranger more than you would like.', polFx: { sanity: -3, rel: { x: { aff: 10, res: -5 } } },
    clT: 'Ask {x} to rule instead', stat: 'charm', dc: 40, clOk: '{x} looked at you for a long moment, then gave it to the stranger. Your friendship survived. So did your conscience, and {x.his}.', clOkFx: { rel: { x: { aff: 5, res: 10 } }, sanity: 2 }, clNo: '{x} refused, offended that you would ask. You had to rule anyway, and both of you were unhappy.', clNoFx: { rel: { x: { aff: -4 } } } },
];
const tplJudge = template('tn_judge', JUDGE_ROWS, (r) => E('tn_judge', T, {
  if: { age: [30, 90], ...JUDGE, ...r.if }, bind: r.bind, title: r.title, text: r.text,
  choices: [
    C(r.honestT, O(r.honest, r.honestFx)),
    C(r.polT, O(r.pol, r.polFx)),
    R(r.clT, r.stat, r.dc, O(r.clOk, r.clOkFx), O(r.clNo, r.clNoFx)),
  ],
}));

// Contests inside each sect, family and faction: two ways to shine, one way to stay out of it.
const cup = (id) => (r) => E(id, T, {
  if: { sect: r.sect, rank: [0, 3], age: [10, 45], ...r.if }, once: false, cd: 3, art: r.art, title: r.title, text: r.text,
  choices: [
    R(r.aT, r.aStat, r.aDc, O(r.aOk, { merit: r.merit, flag: WIN, mastery: { [r.art2]: 6 }, ...r.aFx }), O(r.aNo, { merit: 2, ...r.aNoFx })),
    R(r.bT, r.bStat, r.bDc, O(r.bOk, { merit: Math.round(r.merit * 0.7), mastery: { [r.art2]: 3 }, ...r.bFx }), O(r.bNo, { merit: 1, ...r.bNoFx })),
    C(r.cT, O(r.c, r.cFx)),
  ],
});
const SECT_ROWS = [
  { key: 'mounthua', sect: 'mounthua', if: { season: [0] }, art: 'blossom', art2: 'hua_plum_sword', merit: 12, title: 'Petal catching', text: 'When the plum trees on the Lotus Peak drop their petals, Mount Hua’s disciples compete to cut the most petals in a single breath without touching a branch.',
    aT: 'Cut the petals', aStat: 'body', aDc: 30, aOk: 'You cut twenty-four petals in one breath and not a single twig. An elder said "Hm," which is Mount Hua for a banquet.', aFx: {}, aNo: 'You cut six petals and a branch. The branch was the elder’s favourite.', aNoFx: {},
    bT: 'Count the petals as they fall', bStat: 'insight', bDc: 35, bOk: 'You stopped chasing petals and watched how they fell. Then you cut only the ones that were falling toward you. Fewer petals, and none wasted.', bFx: { insight: 1 }, bNo: 'You counted until the petals blurred, then cut at the blur.', bNoFx: {},
    cT: 'Gather the petals for Granny Pyo’s tea', c: 'You gathered the fallen petals in your robe and took them to the kitchen. Granny Pyo made plum-petal tea and gave you the first cup.', cFx: { rel: { '@hua_cook': { aff: 10 } }, sanity: 3 } },
  { key: 'shaolin', sect: 'shaolin', art: 'temple', art2: 'shao_arhat', merit: 14, title: 'The Lane of Wooden Men', text: 'The Lane of Wooden Men: a corridor of wooden machines that punch, kick and sweep. Every Shaolin warrior monk must walk it end to end, and many try before they are ready.',
    aT: 'Walk the Lane', aStat: 'body', aDc: 45, aOk: 'You walked out of the far end bruised from scalp to heel and upright. The monks waiting there rang a small bell, just once.', aFx: { body: 1 }, aNo: 'The fourteenth wooden man swept your legs and the fifteenth caught you on the way down. They carried you out on a door.', aNoFx: { health: -8 },
    bT: 'Learn the machines’ rhythm first', bStat: 'insight', bDc: 40, bOk: 'You sat at the mouth of the Lane for three days listening to the gears. Then you walked it like a dance. The old monk who builds the machines frowned and went to adjust them.', bFx: { insight: 1 }, bNo: 'The machines have no rhythm. That is the point of them.', bNoFx: { health: -3 },
    cT: 'Sweep the Lane instead', c: 'You swept the Lane while the others walked it. An old monk sweeping the far end nodded at you as if you had done the harder thing.', cFx: { insight: 1, merit: 2 } },
  { key: 'wudang', sect: 'wudang', art: 'temple', art2: 'wu_taiji_fist', merit: 12, title: 'Pushing hands', text: 'Wudang’s yearly contest is pushing hands: two disciples, wrists touching, each trying to unbalance the other without ever losing contact.',
    aT: 'Yield until they fall', aStat: 'insight', aDc: 40, aOk: 'You gave way and gave way until your opponents fell into the space where you had been. The elders smiled the slow Wudang smile.', aFx: { insight: 1 }, aNo: 'You yielded so much that you fell over backwards on your own.', aNoFx: {},
    bT: 'Root yourself like a pine', bStat: 'body', bDc: 35, bOk: 'Nobody could move you. The elders said this was not quite the point, but conceded that it worked.', bFx: { body: 1 }, bNo: 'You rooted yourself like a pine, and were felled like one.', bNoFx: {},
    cT: 'Brew tea for the elders', c: 'You brewed tea for the elders. They drank it while watching, and commented on the bouts, and you learned more from the comments than from the bouts.', cFx: { insight: 1, merit: 2 } },
  { key: 'emei', sect: 'emei', art: 'temple', art2: 'emei_sword', merit: 12, title: 'The silent contest', text: 'Emei’s contest is fought in silence. The first disciple to make any sound at all, even a gasp, loses.',
    aT: 'Fight without a sound', aStat: 'sanity', aDc: 75, aOk: 'You took a cut to the forearm and did not breathe. Your opponent gasped when she saw the blood. You won, silently.', aFx: {}, aNo: 'You sneezed. It was spring.', aNoFx: {},
    bT: 'Make her gasp', bStat: 'body', bDc: 35, bOk: 'You put a blade-flat to her neck so fast that she gasped before she could stop herself. Silent Waters, the Abbess said afterwards, does not mean slow.', bFx: {}, bNo: 'She did not gasp. You, when her blade touched your wrist, did.', bNoFx: {},
    cT: 'Sit the contest out in meditation', c: 'You sat silently at the edge of the courtyard for the entire contest. Nobody noticed you were not competing. That, the Abbess told you later, was its own kind of victory.', cFx: { qi: 8, sanity: 3 } },
  { key: 'kunlun', sect: 'kunlun', art: 'snow', art2: 'kun_cloud_sword', merit: 12, title: 'Snow burial', text: 'Kunlun disciples compete by standing barefoot in the snow at the peak, sword raised, until only one remains standing.',
    aT: 'Stand', aStat: 'health', aDc: 60, aOk: 'You stood until your feet were stone and your sword arm was ice. Then you were the last. They carried you inside and thawed you by the fire like a fish.', aFx: { health: -4 }, aNo: 'You lasted until the second bell. Your toes have not quite forgiven you.', aNoFx: { health: -6 },
    bT: 'Circulate the Snow Heart Method', bStat: 'qi', bDc: 50, bOk: 'You let the cold in and moved it with your breath, and it became just another kind of qi. Steam rose from your shoulders. The Sect Leader, watching from his window, nodded.', bFx: { qi: 8 }, bNo: 'Your qi froze halfway round its circuit. You stood very still for an hour, not by choice.', bNoFx: { health: -4 },
    cT: 'Bring blankets to the ones who fall', c: 'You brought blankets and hot broth to the disciples who fell. Kunlun is aloof, but it remembers who brought the broth.', cFx: { merit: 3, charm: 1 } },
  { key: 'kongtong', sect: 'kongtong', art: 'mountain', art2: 'kong_seven_injuries', merit: 14, title: 'Iron Wall Day', text: 'On Iron Wall Day, Kongtong disciples take turns punching each other in the chest. Each takes the blow, then answers it. The last one standing wins; the rest go to the infirmary.',
    aT: 'Take the blows', aStat: 'body', aDc: 45, aOk: 'You took eleven blows and answered every one. Your chest is purple. You are very proud of your chest.', aFx: { body: 1 }, aNo: 'The sixth blow sat you down. The seventh, delivered politely to someone else, sat them down beside you.', aNoFx: { health: -6 },
    bT: 'Hit so hard they do not answer', bStat: 'power', bDc: 40, bOk: 'You hit your first opponent so hard he forgot his turn. The elders debated whether this was within the spirit of the contest and decided it was the spirit of the contest.', bFx: {}, bNo: 'You hit hard. They hit harder. That is Kongtong.', bNoFx: { health: -4 },
    cT: 'Work in the infirmary', c: 'You spent the day binding cracked ribs. By evening you knew every disciple’s weak side, which on Kongtong is not nothing.', cFx: { insight: 1, merit: 2 } },
  { key: 'qingcheng', sect: 'qingcheng', art: 'forest', art2: 'qing_pine_sword', merit: 12, title: 'Splitting pine needles', text: 'Qingcheng disciples compete to split falling pine needles lengthwise with the edge of a sword. The elders record every result in a ledger that goes back three hundred years.',
    aT: 'Split the needles', aStat: 'insight', aDc: 45, aOk: 'You split nine needles cleanly. Your name went into the ledger beside a sect leader’s from two centuries ago. The elders read it twice.', aFx: {}, aNo: 'You split one needle and the ledger recorded it. Qingcheng records everything.', aNoFx: {},
    bT: 'Split them faster, if less perfectly', bStat: 'body', bDc: 40, bOk: 'You split twenty needles roughly. The elders argued for an hour about whether rough counts, and recorded the argument.', bFx: {}, bNo: 'Speed without precision, the ledger noted, in a fine hand.', bNoFx: {},
    cT: 'Read the old ledgers instead', c: 'You read the ledgers by lamplight. Three hundred years of results, and in the margins three hundred years of grudges, every one of them still open.', cFx: { insight: 2 } },
  { key: 'diancang', sect: 'diancang', art: 'mountain', art2: 'dian_swift_sword', merit: 12, title: 'The single draw', text: 'Diancang’s contest is a single draw: two disciples face each other with sheathed swords, and the first to touch the other wins. Most bouts last less than a heartbeat.',
    aT: 'Draw first', aStat: 'body', aDc: 40, aOk: 'Your sword was out and back before your opponent’s hand reached his hilt. The elder had to ask the crowd who had won.', aFx: {}, aNo: 'You drew fast. Your opponent drew faster. That is all there is to say about it, which is the Diancang way.', aNoFx: {},
    bT: 'Wait for them to move', bStat: 'insight', bDc: 40, bOk: 'You waited. Your opponent could not bear it and drew. You moved inside the draw. The elders nodded: Diancang is fast, but not foolish.', bFx: { insight: 1 }, bNo: 'You waited. So did they. The sun set. The elders declared it a draw and went to dinner.', bNoFx: {},
    cT: 'Hold the incense that times the bouts', c: 'You held the incense stick that times each bout. Most bouts ended before the smoke rose. You learned what "fast" means from the outside.', cFx: { insight: 1, merit: 1 } },
  { key: 'zhongnan', sect: 'zhongnan', art: 'forest', art2: 'zhong_heaven_gate', merit: 12, title: 'Seven stars', text: 'Zhongnan’s contest is fought by formations of seven, each team trying to break the other’s Big Dipper without losing its own shape.',
    aT: 'Hold your star in the formation', aStat: 'insight', aDc: 35, aOk: 'You held your star while the formation turned around you, and when the other team broke, it broke against your place. The elders praised the team. Your teammates praised you.', aFx: { charm: 1 }, aNo: 'You stepped out of your star by half a pace. The formation broke at you. Your teammates were very understanding, for Daoists.', aNoFx: {},
    bT: 'Break their formation alone', bStat: 'power', bDc: 50, bOk: 'You charged the other formation alone and broke it. The elders were appalled. Then they asked you to show them how.', bFx: {}, bNo: 'You charged alone. Seven swords met you. The elders were not appalled; they had seen it before.', bNoFx: { health: -4 },
    cT: 'Draw the formations in the dust for the juniors', c: 'You drew both formations in the dust and explained each move to the juniors. Three of them later became very good, and remembered you.', cFx: { insight: 1, merit: 2 } },
  { key: 'beggars', sect: 'beggars', art: 'city', art2: 'beg_staff', merit: 12, title: 'The Bowl Bouts', text: 'Once a year the Beggars’ Sect holds the Bowl Bouts under the Luoyang bridges: every beggar fights with a bowl of rice balanced on his head. Spill it and you lose, and go hungry.',
    aT: 'Fight with the bowl on your head', aStat: 'body', aDc: 35, aOk: 'You fought five bouts without spilling a grain, and ate your rice afterwards with great dignity. An elder gave you a pouch.', aFx: {}, aNo: 'You spilled in the second bout. A dog ate your dinner. The dog was also a member of the sect, in a sense.', aNoFx: {},
    bT: 'Knock their bowls with your staff', bStat: 'insight', bDc: 35, bOk: 'You aimed at bowls, not beggars. Rice rained on the riverbank and you won without hitting anyone. The Clan Chief laughed from under the bridge.', bFx: {}, bNo: 'You aimed at a bowl and hit an elder. The elder kept his rice.', bNoFx: {},
    cT: 'Cook the rice for the losers', c: 'You cooked congee for everyone who spilled. By the end of the day you had fed half the sect, and half the sect owed you.', cFx: { charm: 1, merit: 3 } },
];
const tplSectCup = template('tn_cup', SECT_ROWS, cup('tn_cup'));

const HOUSE_ROWS = [
  { key: 'namgung', sect: 'namgung', art: 'estate', art2: 'nam_emperor_sword', merit: 14, title: 'Thunder in the courtyard', text: 'Each spring the young Namgung cross swords in the family courtyard before the patriarch, and every bout is recorded by a clerk who also records who was standing nearest whom.',
    aT: 'Win your bouts', aStat: 'power', aDc: 50, aOk: 'You won your bracket with the Heavenly Emperor Sword and the clerk recorded it twice. The patriarch’s eyebrows moved. In the Namgung, that is applause.', aFx: { rep: { families: 3 } }, aNo: 'You lost to a cousin, who was congratulated, and you were recorded standing alone.', aNoFx: {},
    bT: 'Stand nearest the right people', bStat: 'charm', bDc: 35, bOk: 'You lost your bouts, but you were standing beside the patriarch’s favourite niece when he looked over. The clerk recorded that too.', bFx: { rep: { families: 3 } }, bNo: 'You stood nearest the wrong people, and the clerk recorded it.', bNoFx: { rep: { families: -1 } },
    cT: 'Watch Namgung Jin’s bouts', c: 'You watched the heir fight. He did not look at any of his opponents. Afterwards, alone in the yard, he practised until midnight. You were the only one who saw.', cFx: { insight: 1 } },
  { key: 'moyong', sect: 'moyong', art: 'snow', art2: 'moy_return_art', merit: 12, title: 'The mirror bouts', text: 'The Moyong test their young by mirror bouts: each fighter must return the other’s technique, and the first to be returned upon twice loses.',
    aT: 'Return everything', aStat: 'insight', aDc: 50, aOk: 'You returned every technique and were returned upon only once. The patriarch said, "Adequate," and in the Moyong that word has been known to make grown men weep.', aFx: { rep: { families: 3 } }, aNo: 'You were returned upon twice in four exchanges. A cousin bowed to you with very precise pity.', aNoFx: {},
    bT: 'Use techniques nobody can return', bStat: 'body', bDc: 45, bOk: 'You fought ugly: elbows, shoulders, nothing with a name. Nobody could return it because nobody wanted to. The elders were horrified and recorded it as a win.', bFx: {}, bNo: 'Ugly techniques, it turns out, can also be returned. Uglier.', bNoFx: { health: -3 },
    cT: 'Study the family archive of returned techniques', c: 'The Moyong keep a record of every technique they have ever returned. You read about your own sect’s arts and learned their weaknesses, with a chill.', cFx: { insight: 2 } },
  { key: 'paeng', sect: 'paeng', art: 'feast', art2: 'paeng_tiger_saber', merit: 12, title: 'The Five Tigers feast', text: 'The Paeng hold their family contest during a feast: every bout is fought between courses, and the losers serve the winners.',
    aT: 'Fight between courses', aStat: 'power', aDc: 40, aOk: 'You won four bouts and four courses. You were served by four cousins, who were good sports about it, mostly.', aFx: { health: 3 }, aNo: 'You lost in the first bout and served soup for the rest of the night. You were good at it. The Paeng noticed.', aNoFx: {},
    bT: 'Out-eat the field', bStat: 'health', bDc: 55, bOk: 'You ate so much that your opponents lost on sight. The patriarch laughed like a landslide.', bFx: { rep: { families: 2 } }, bNo: 'You ate too much and fought like a full bucket.', bNoFx: { health: -2 },
    cT: 'Drink with the old uncles', c: 'You drank with the old Paeng uncles at the end of the table, who told you how the Five Tigers really got their name. It was not the story in the family books.', cFx: { insight: 1, rep: { families: 1 } } },
  { key: 'dang', sect: 'dang', art: 'garden', art2: 'dang_needles', merit: 14, title: 'The garden contest', text: 'The Dang family contest is held in the poison garden: hit a target with a needle without touching any plant on the way. Most of the plants are lethal. All of the cousins are watching.',
    aT: 'Throw through the garden', aStat: 'insight', aDc: 45, aOk: 'Your needle threaded twenty paces of hanging nightshade and hit the target dead centre. The matriarch’s chair creaked as she leaned forward.', aFx: { rep: { families: 3 } }, aNo: 'Your needle grazed a leaf. The leaf turned black. So, for a week, did your thumb.', aNoFx: { health: -6 },
    bT: 'Throw over the garden', bStat: 'body', bDc: 45, bOk: 'You threw high, over everything, and let the needle fall onto the target like rain. Not the Dang way. It worked.', bFx: {}, bNo: 'You threw high, and the wind brought it down in the foxglove.', bNoFx: {},
    cT: 'Tend the garden instead', c: 'You tended the poison garden for the day, gloved to the elbow. You know three new poisons now, and their antidotes, and which cousin keeps a private bed.', cFx: { insight: 2 } },
  { key: 'jegal', sect: 'jegal', art: 'library', art2: 'jegal_formations', merit: 12, title: 'The sand table', text: 'The Jegal family contest is fought on a sand table: two cousins command imaginary armies through an imaginary pass, and the elders judge who would have lived.',
    aT: 'Command your army', aStat: 'insight', aDc: 50, aOk: 'You lost half your army in the pass and won the war in the valley beyond it. The elders were silent for a long time, then asked you to do it again.', aFx: { rep: { families: 3 } }, aNo: 'Your imaginary army died to the last imaginary man. The elders made you write a letter to each of their imaginary mothers.', aNoFx: {},
    bT: 'Read your opponent, not the table', bStat: 'charm', bDc: 40, bOk: 'Your cousin always attacks when nervous. You made him nervous. The elders said this was not strategy. You said it was the oldest strategy. They wrote that down.', bFx: {}, bNo: 'Your cousin was not nervous. You were.', bNoFx: {},
    cT: 'Rearrange the sand into a garden', c: 'You made the sand table into a garden while the elders were at lunch. Jegal Mun came back, looked at it for an hour, and declared it a formation. Perhaps it was.', cFx: { insight: 1, sanity: 2 } },
  { key: 'greenforest', sect: 'greenforest', if: { loc: 'taihang' }, art: 'forest', art2: 'uno_mountain_axe', merit: 12, title: 'The Mountain Tiger’s feast', text: 'The seventy-two strongholds send their strongest to the Mountain Tiger’s feast to throw axes, lift millstones and insult each other in verse.',
    aT: 'Throw axes', aStat: 'body', aDc: 40, aOk: 'Your axe split the target and the stake behind it. The Mountain Tiger raised his bowl to you across the whole feast.', aFx: { rep: { unorthodox: 3 } }, aNo: 'Your axe split the target next to yours. Its owner took it personally.', aNoFx: { health: -3 },
    bT: 'Insult them in verse', bStat: 'charm', bDc: 35, bOk: 'You insulted the third stronghold’s captain in a couplet so perfect that he asked for a copy. The feast roared.', bFx: { rep: { unorthodox: 2 } }, bNo: 'Your verse did not scan. The captains insulted your verse, in verse, which scanned.', bNoFx: {},
    cT: 'Keep the Mountain Tiger’s cup full', c: 'You kept the Mountain Tiger’s cup full all night. He told you stories of when the Green Forest still had honour, and, sometimes, still does.', cFx: { rel: { '@mountain_tiger': { aff: 10 } } } },
  { key: 'waterfortress', sect: 'waterfortress', art: 'lake', art2: 'uno_water_palm', merit: 12, title: 'Underwater', text: 'The Water Fortress contest is held underwater: two fighters go into the lake holding a stone, and the one who comes up last wins. Sometimes they fight down there. Usually they just wait.',
    aT: 'Stay under', aStat: 'health', aDc: 60, aOk: 'You came up long after your opponent, blue-lipped and grinning. The Fortress men hammered on the boats in applause.', aFx: { rep: { unorthodox: 2 } }, aNo: 'You came up first, gasping, to a great deal of laughter from people who had all done the same once.', aNoFx: {},
    bT: 'Fight down there', bStat: 'body', bDc: 45, bOk: 'You took your opponent’s stone away in the green dark. He came up stoneless and furious, and you came up laughing, with two.', bFx: { rep: { unorthodox: 3 } }, bNo: 'He took your stone. You came up very fast.', bNoFx: { health: -2 },
    cT: 'Haul up the ones who stay too long', c: 'You dove for those who stayed under too long. Twice you brought someone up who would not have come up on their own. The Fortress does not forget that.', cFx: { rep: { unorthodox: 3 }, merit: 3 } },
  { key: 'bloodshadow', sect: 'bloodshadow', art: 'night', art2: 'uno_silent_needle', merit: 14, title: 'The bell on the sleeper', text: 'The Blood Shadow Pavilion’s contest: steal a small bell from the belt of a sleeping elder without ringing it. The elder is not really asleep. Nobody has ever said so.',
    aT: 'Take the bell', aStat: 'body', aDc: 50, aOk: 'You took the bell without a sound. In the morning the elder thanked you for returning it, and you had not returned it. It was on your belt. It was on his.', aFx: {}, aNo: 'The bell rang. The elder opened one eye and closed it again. That was all, and it was enough.', aNoFx: {},
    bT: 'Wait until he truly sleeps', bStat: 'insight', bDc: 45, bOk: 'You waited three nights. On the third his breathing changed. You took the bell and left a pastry in its place. He kept the pastry.', bFx: {}, bNo: 'You waited three nights. He did not sleep. Neither, by the end, did you.', bNoFx: { sanity: -2 },
    cT: 'Ring the bell yourself, from across the room', c: 'You flicked a pebble across the room and rang the bell on purpose. The elder sat up and laughed, which nobody in the Pavilion had heard before. You did not win. You were noticed.', cFx: { merit: 4 } },
  { key: 'cult', sect: 'cult', if: { age: [16, 45] }, art: 'demonic', art2: 'cult_demon_palm', merit: 14, title: 'The Hundred Demons', text: 'At the Cult’s Festival of a Hundred Demons, young warriors fight in masks before the Heavenly Demon’s empty throne. Nobody is supposed to know who is under the mask. Everybody does.',
    aT: 'Fight in the mask', aStat: 'power', aDc: 55, aOk: 'You won four bouts in a red demon mask. When you took it off at the end, the elders were not surprised. They had been watching your feet.', aFx: { rep: { cult: 4 } }, aNo: 'You lost in a blue demon mask. Your opponent bowed, and you recognised the bow. So did they.', aNoFx: {},
    bT: 'Fight as someone else', bStat: 'insight', bDc: 45, bOk: 'You fought in another warrior’s style, under another warrior’s mask. Nobody knew. The other warrior was praised for a victory he did not win, and owes you forever.', bFx: { infamy: 1 }, bNo: 'You fought in another’s style and lost in it. He was blamed. He knows it was you.', bNoFx: { rep: { cult: -1 } },
    cT: 'Carve masks for the festival', c: 'You carved masks all month. On festival night, one hundred demons wore your faces. That is a kind of power the Cult does not have a word for.', cFx: { charm: 1, merit: 2 } },
  { key: 'depot', sect: 'easterndepot', art: 'palace', art2: 'court_guard_saber', merit: 12, title: 'The officers’ contest', text: 'The Eastern Depot holds a contest among its officers every year, ostensibly in saber. In practice, the winner is whoever the Director wants to promote, and the contest is how everyone finds out.',
    aT: 'Win it with the saber', aStat: 'power', aDc: 50, aOk: 'You won with the saber. There was a long silence while everyone looked toward the Director’s box. Then the Director clapped, twice. You are someone now.', aFx: { rep: { court: 4 } }, aNo: 'You lost to the man the Director wanted. That, you understood afterwards, was the correct result.', aNoFx: {},
    bT: 'Find out in advance who is meant to win', bStat: 'insight', bDc: 40, bOk: 'You found out, and lost to him gracefully, and he remembered it. So did the Director, who sent you a cup of wine afterwards and nothing else.', bFx: { rep: { court: 3 } }, bNo: 'You guessed wrong, lost to the wrong man, and he was not grateful.', bNoFx: { rep: { court: -2 } },
    cT: 'Keep the score honestly', c: 'You kept the score, honestly. It was a dangerous thing to do in that room. Commander Han Gyeong, at the back, caught your eye and nodded.', cFx: { rel: { '@guard_commander': { res: 8 } } } },
  { key: 'guild', sect: 'goldenabacus', art: 'market', art2: 'escort_spear', merit: 12, title: 'The escort trials', text: 'The Golden Abacus Guild tests its escort agencies against each other every year: a mock caravan, a mock ambush, and a very real bonus for the agency that loses the fewest mock crates.',
    aT: 'Guard the crates', aStat: 'body', aDc: 40, aOk: 'You lost no crates and broke three mock bandits’ mock ribs, which were real ribs. The Guild paid your bonus and the bandits’ physicians.', aFx: { wealth: 10, rep: { merchants: 3 } }, aNo: 'The mock bandits made off with four crates, one of which contained your lunch.', aNoFx: {},
    bT: 'Hire the mock bandits beforehand', bStat: 'charm', bDc: 35, bOk: 'You bought the mock bandits dinner the night before. They mock-attacked another agency. The Guild, which admires initiative, said nothing.', bFx: { wealth: 6, rep: { merchants: 2 } }, bNo: 'The mock bandits ate your dinner and attacked you anyway. They were very apologetic about it.', bNoFx: { wealth: -3 },
    cT: 'Audit the crates afterwards', c: 'You audited the mock crates after the trial and found that two agencies had been mock-stealing from each other for years. The Guild was grateful in the way the Guild is grateful: with a ledger entry.', cFx: { insight: 1, rep: { merchants: 2 } } },
];
const tplHouseCup = template('tn_house', HOUSE_ROWS, cup('tn_house'));

// Betting on the Dragon-Phoenix Assembly, where memory of the outcome is worth a fortune.
const ODDS_ROWS = [
  { key: 'y12', year: 12, mem: 'timeline.assembly_12', title: 'The junior Assembly odds', text: 'Every bookmaker from Kaifeng to Hangzhou is taking bets on the junior Dragon-Phoenix Assembly. The favourite is a Namgung boy nobody outside Jiangnan has seen fight.',
    stake: 10, favT: 'Bet on the Namgung boy', favP: 0.65, favWin: 8, favOk: 'Namgung Jin won, as everyone said he would. The bookmaker paid you short odds, with a long face.', favNo: 'Your bet was void: the bracket did not go as anyone expected.',
    longT: 'Bet on an unknown', longP: 0.1, longWin: 80, longOk: 'Your unknown won. Nobody, including the unknown, can explain it.', longNo: 'Your unknown went out in the first round. The bookmaker thanked you for your support.',
    memT: 'Bet everything on Namgung Jin, by the margin you remember', memWin: 60, memOk: 'You named not just the winner but the round each of his opponents fell in. In the autumn, the bookmaker paid out with the face of a man passing a stone, and asked, very quietly, who you were.' },
  { key: 'y18', year: 18, mem: 'timeline.assembly_18', title: 'Odds on the Assembly', text: 'The Assembly is coming, and the bookmakers are offering long odds on anyone from the Namgung reaching the final except the heir, who is not entering this year.',
    stake: 15, favT: 'Bet on the Namgung heir’s cousins', favP: 0.4, favWin: 15, favOk: 'A Namgung fighter reached the final, which paid. You did not ask which one.', favNo: 'No Namgung cousin reached the final, which was a first for the bookmakers and a last for your silver.',
    longT: 'Bet on a girl reaching the final', longP: 0.15, longWin: 90, longOk: 'A girl reached the final. The bookmakers had not believed it possible. You had, or at least you had hoped.', longNo: 'No girl reached the final this year. The bookmakers had been sure.',
    memT: 'Bet that Namgung So-hee reaches the final', memWin: 90, memOk: 'You put everything on a girl whose family keeps her in a cage of silk. In the autumn she astonished the whole murim, and you collected at odds of nine to one.' },
  { key: 'y24', year: 24, mem: 'timeline.assembly_24', title: 'The heir’s Assembly', text: 'Namgung Jin is the new heir of his house, and the bookmakers say grief has made him either dangerous or brittle. They cannot agree which, so the odds are generous.',
    stake: 20, favT: 'Bet that grief made him dangerous', favP: 0.55, favWin: 20, favOk: 'He fought like a man with nothing to lose, and won like one. You were paid and felt strange about it.', favNo: 'He fought like a man with nothing to lose, and lost something anyway.',
    longT: 'Bet that grief made him brittle', longP: 0.35, longWin: 45, longOk: 'He broke in the semifinal, in front of everyone. You were paid, and did not spend it for a long time.', longNo: 'He did not break. He has not broken since.',
    memT: 'Bet on the way you remember him fighting', memWin: 50, memOk: 'You remember how he fought that year: like a man with nothing to lose. You bet on it and were paid, and wished, a little, that you had been wrong.' },
  { key: 'y30', year: 30, mem: 'timeline.assembly_30', title: 'The last Assembly', text: 'News from the west is bad, and the bookmakers are offering odds on whether this autumn’s Assembly will even be held.',
    stake: 10, favT: 'Bet that it is cancelled', favP: 0.3, favWin: 20, favOk: 'It was not held after all, you heard at first, and were paid; then it was held, and the bookmaker came to find you.', favNo: 'It went ahead despite the news from the west. You lost your bet and gained a season of dread.',
    longT: 'Bet that it goes ahead', longP: 0.7, longWin: 5, longOk: 'It went ahead, as if the world were not about to end. You won a little silver, and the sense that you should have spent it on something else.', longNo: 'Somehow, your bookmaker went missing before paying out. Things go missing, in years like this.',
    memT: 'Bet that it goes ahead, and that it will be the last for years', memWin: 25, memOk: 'You bet that it would be held and that it would be the last. The bookmaker laughed at the second half. He paid the first half in autumn, and fourteen years later, if he lived, he will have understood the rest.' },
  { key: 'y44', year: 44, mem: 'timeline.assembly_44', title: 'The Assembly returns', text: 'The first Assembly since the war, and nobody knows the new names. The bookmakers are guessing, which is the most honest they have been in years.',
    stake: 10, favT: 'Bet on a sect fighter', favP: 0.5, favWin: 10, favOk: 'A sect fighter won. The old order holds, for now.', favNo: 'A nobody won, which seems to be what this generation does.',
    longT: 'Bet on a war orphan', longP: 0.25, longWin: 40, longOk: 'A war orphan won, in borrowed boots. Half the city wept. You wept and were paid.', longNo: 'The orphans did well, but not that well. Not yet.',
    memT: 'Bet on the names you remember from that autumn', memWin: 45, memOk: 'You remembered the names from another life: a generation that grew up in war, and who among them came through. You bet, and won, and went to watch them fight, and did not tell anyone why you cried.' },
];
const tplOdds = template('tn_odds', ODDS_ROWS, (r) => {
  const req = { wealth: `>=${r.stake}` };
  return E('tn_odds', T, {
    if: { age: [10, 90], locType: 'city', ...before(r.year) }, art: 'market', title: r.title, text: r.text,
    choices: [
      P(`${r.favT} (${r.stake} taels)`, r.favP, O(r.favOk, { wealth: r.favWin }), O(r.favNo, { wealth: -r.stake }), { req }),
      P(`${r.longT} (${r.stake} taels)`, r.longP, O(r.longOk, { wealth: r.longWin }), O(r.longNo, { wealth: -r.stake }), { req }),
      M(r.memT, r.mem, O(r.memOk, { wealth: r.memWin, flag: `tn.foresaw_${r.year}` }), { req }),
      C('Stay out of it', O('You kept your silver. Some people bet on the Assembly; some people watch it; some people simply live through it.')),
    ],
  });
});

export default [
  ...handWritten,
  ...tplBout, ...tplCity, ...tplWager, ...tplRace, ...tplDrink, ...tplBow, ...tplNamed,
  ...tplSelect, ...tplFix, ...tplJudge, ...tplSectCup, ...tplHouseCup, ...tplOdds,
];
